// Ісаї — Біблія, переклад Патріарха Філарета. Згенеровано scripts/build_bible.py, не правте вручну.
import type { BChap } from '../types';
const C: BChap[] = [{"v":["Видіння Ісаї, сина Амосового, яке він бачив про Юдею та Єрусалим, у дні Озії, Іоафама, Ахаза, Єзекії — царів юдейських.","Слухайте, небеса, і слухай, земле, бо Господь говорить: Я виховав і підніс синів, а вони обурилися проти Мене.","Віл знає володаря свого, і осел — ясла господаря свого; а Ізраїль не знає [Мене], народ Мій не розуміє.","На жаль, народ грішний, народ обтяжений беззаконнями, плем’я лиходіїв, сини погибельні! Залишили Господа, знехтували Святого Ізраїлевого, — повернулися назад.","У що бити ще вас, що продовжуєте свою затятість? Уся голова у виразках, і все серце зачахло.","Від підошви ноги до тімені голови немає у нього здорового місця: виразки, плями, гнійні рани, неочищені й необв’язані і не пом’якшені єлеєм.","Земля ваша спустошена; міста ваші спалені вогнем; поля ваші на ваших очах з’їдають чужі; усе спорожніло, як після руйнування чужинцями.","І залишилася дочка Сиону, як намет у винограднику, як курінь на горо́ді, як обложене місто.","Якби Господь Саваоф не полишив нам невеликого залишку, то ми були б те саме, що Содом, уподібнилися б Гоморрі.","Слухайте слово Господнє, князі содомські; слухай закон Бога нашого, народе гоморрський!","Для чого Мені безліч жертв ваших? — говорить Господь. Я пересичений всепаленнями баранів і жиром відгодованої худоби, і крови тельців і агнців і козлів не хочу.","Коли ви приходите стати перед лице Моє, хто вимагає від вас, щоб ви топтали двори Мої?","Не носіть більше дарів марних: куріння огидне для Мене; новомісяч і субот, святкових зібрань не можу терпіти: беззаконня — і святкування!","Новомісяччя ваші і свята ваші ненавидить душа Моя: вони тягар для Мене; Мені тяжко нести їх.","І коли ви простягаєте руки ваші, Я закриваю від вас очі Мої; і коли ви примножуєте моління ваші, Я не чую: ваші руки повні крови.","Обмийтеся, очистіться; віддаліть злі діяння ваші від очей Моїх; перестаньте чинити зло;","навчіться чинити добро, шукайте правди, рятуйте пригнобленого, захищайте сироту, заступайтеся за вдову.","Тоді прийдіть — і розсудимо, — говорить Господь. Якщо будуть гріхи ваші, як багряне, — як сніг убілю; якщо будуть червоні, як пурпур, — як вовну убілю.","Якщо захочете і послухаєтеся, то будете споживати блага землі;","якщо ж зречетеся і будете чинити опір, то меч пожере вас: бо вуста Господні говорять.","Як зробилася блудницею вірна столиця, сповнена правосуддя! Правда жила у ній, а тепер — убивці.","Срібло твоє стало окалиною, вино твоє зіпсоване водою;","князі твої — законопорушники і спільники злодіїв; усі вони люблять подарунки і ганяються за мздою; не захищають сироту, і справа вдови не доходить до них.","Тому говорить Господь, Господь Саваоф, Сильний Ізраїлів: о, задовольню Я Себе над супротивниками Моїми й помщуся ворогам Моїм!","І зверну на тебе руку Мою і, як у лузі, очищу з тебе домішки, і відокремлю від тебе все свинцеве;","і знову буду поставляти тобі суддів, як раніше, і радників, як спочатку; тоді будуть говорити про тебе: «місто правди, столиця вірна».","Сион спасеться правосуддям, і сини його, які навернулися, правдою;","усім же відступникам і грішникам — погибель, і ті, що залишили Господа, знищаться.","Вони будуть посоромлені за діброви, які настільки любі для вас, і посоромлені за сади, які ви обрали собі;","бо ви будете, як дуб, якого лист обпав, і як сад, у якому немає води.","І сильний буде лахміттям, і діло його — іскрою; і будуть горіти разом, — і ніхто не погасить."],"x":{"2":"4.32.1","3":"4.32.6","4":"31.30.9|31.57.3|37.9.5","5":"32.2.30|32.4.19","6":"4.28.35","7":"4.28.51-52|31.5.5","9":"33.3.22|62.9.29|0.19.24|32.23.14","11":"26.15.8|31.66.3|32.6.20|40.5.21-22","12":"32.7.22","13":"26.21.27","15":"26.1.28|32.14.12|36.8.18|43.3.4|31.59.3","16":"25.33.15|56.3.11","17":"25.81.4","18":"31.41.1|31.43.25|31.44.22","19":"2.25.18","22":"32.6.30|36.22.18","23":"38.9.15|1.22.22|32.5.28|48.7.10","24":"4.28.63","25":"31.1.22|49.3.2-3","26":"32.33.16","29":"31.65.3|38.4.13","30":"25.1.3","31":"49.4.1"}},{"v":["Слово, яке було у видінні до Ісаї, сина Амосового, про Юдею та Єрусалим.","І буде в останні дні, гора дому Господнього буде поставлена у главу гір і підніметься над пагорбами, і потечуть до неї усі народи.","І підуть багато народів і скажуть: прийдіть, і зійдемо на гору Господню, у дім Бога Якова, і навчить Він нас Своїх шляхів і будемо ходити стежками Його; бо від Сиону вийде закон, і слово Господнє — з Єрусалима.","І буде Він судити народи, і викриє багато племен; і перекують мечі свої на орала, і списи свої — на серпи: не підніме народ на народ меча, і не будуть більше вчитися воювати.","О, доме Якова! Прийдіть, і будемо ходити у світлі Господньому.","Але Ти відкинув народ Твій, дім Якова, тому що вони багато чого перейняли від сходу: і чаклуни у них, як у филистимлян, і з синами чужих вони у спілкуванні.","І наповнилася земля його сріблом і золотом, і немає числа скарбам його; і наповнилася земля його конями, і немає числа колісницям його;","і наповнилася земля його ідолами: вони поклоняються ділу рук своїх, тому, що зробили персти їх.","І схилилася людина, і принизився муж, — і Ти не простиш їх.","Іди у скелю і сховайся у землю від страху Господа і від слави величі Його.","Поникнуть горді погляди людини, і високе людське принизиться; і один Господь буде високий у той день.","Бо гряде день Господа Саваофа на все горде й зарозуміле і на все звеличене, — і воно буде принижене, —","і на всі кедри ливанські, високі і піднесені, і на всі дуби васанські,","і на всі високі гори, і на всі підвищені пагорби,","і на усяку високу вежу, і на всяку міцну стіну,","і на всі кораблі фарсиські, і на всі жадані прикраси їх.","І впаде велич людська, і високе людське принизиться; і один Господь буде високий у той день,","й ідоли зовсім зникнуть.","І ввійдуть люди в ущелини скель і у прірви землі від страху Господа і від слави величі Його, коли Він повстане скрушити землю.","У той день людина кине кротам і кажанам срібних своїх ідолів і золотих своїх ідолів, яких зробила собі для поклоніння їм,","щоб увійти в ущелини скель і у розпадини гір від страху Господа і від слави величі Його, коли Він повстане скрушити землю.","Перестаньте ви надіятися на людину, дихання якої у ніздрях її, бо що вона значить?"],"x":{"2":"31.56.7|43.4.1|32.3.17","3":"43.4.2","4":"53.4.27|39.3.10|48.9.10","6":"32.12.7","8":"31.44.10|32.2.28","10":"32.23.24|40.9.2","11":"31.5.15","12":"32.46.10|39.2.10|49.4.1","14":"31.41.15|48.4.7","15":"31.30.25","17":"31.5.15-16","19":"38.10.8|52.23.30|76.6.16","20":"31.31.7","22":"13.35.21|24.27.3"}},{"v":["Ось, Господь, Господь Саваоф, відніме у Єрусалима і в Іуди посох і тростину, всяке підкріплення хлібом і всяке підкріплення водою,","хороброго вождя і воїна, суддю і пророка, і прозорливця і старця,","п’ятдесятника і вельможу і радника, і мудрого художника і майстерного у слові.","І дам їм отроків у начальники, і діти будуть панувати над ними.","І у народі один буде пригнічуваний іншим, і кожен — ближнім своїм; юнак буде нахабно підноситися над старцем, і простолюдин над вельможею.","Тоді вхопиться людина за брата свого, у сімействі батька свого, і скаже: у тебе є одяг, будь нашим вождем, і нехай будуть ці руїни під рукою твоєю.","А він із клятвою скаже: не можу зцілити ран суспільства; і в моєму домі немає ні хліба, ні одягу; не робіть мене вождем народу.","Так руйнувався Єрусалим, і упав Іуда, тому що язик їх і діла їх — проти Господа, образливі для очей слави Його.","Вираз облич їх свідчить проти них, і про гріх свій вони розповідають відкрито, як содомляни, не приховують: горе душі їх! бо самі на себе накликають зло.","Скажіть праведникові, що благо йому, бо він буде споживати плоди діл своїх;","а беззаконникові — горе, бо буде йому відплата за діла рук його.","Гнобителі народу Мого — діти, і жінки панують над ним. Народе Мій! вожді твої вводять тебе в оману і путь стежок твоїх зіпсували.","Повстав Господь на суд — і стоїть, щоб судити народи.","Господь вступає у суд зі старійшинами народу Свого і з князями його: ви спустошили виноградник; награбоване у бідного — у ваших домах;","навіщо ви утискуєте народ Мій і гнітите бідних? говорить Господь, Господь Саваоф.","І сказав Господь: за те, що дочки Сиону гордовиті і ходять, піднявши шию і зваблюючи поглядами, і виступають величною ходою і гримлять ланцюжками на ногах, —","оголить Господь тім’я дочок Сиону і відкриє Господь сором їх;","у той день відніме Господь красиві ланцюжки на ногах і зірочки, і півмісяці,","серги, і намиста, й опахала, запонки і зап’ястя, і пояси, і сосудці з парфумами, і привіски чарівні,","персні і кільця в носі,","верхній одяг і нижній, і хустки, і гаманці,","світлі тонкі опанчі і пов’язки, і покривала.","І буде замість пахощів сморід, і замість пояса буде мотузка, і замість завитого волосся — проплішина, і замість широкої опанчі — вузьке веретище, замість краси — клеймо.","Чоловіки твої впадуть від меча, і хоробрі твої — на війні.","І будуть зітхати і плакати ворота столиці, і буде вона сидіти на землі спустошена."],"x":{"1":"36.4.16|36.5.16","3":"11.24.14","4":"27.10.16","5":"36.22.29","7":"1.15.26","9":"0.13.13|0.18.20","10":"31.32.17|55.3.18","11":"32.25.14","13":"25.97.9","15":"31.1.17|40.2.7","16":"71.2.9","25":"33.1.4"}},{"v":["І вхопляться сім жінок за одного чоловіка у той день, і скажуть: «свій хліб будемо їсти і свій одяг будемо носити, тільки нехай будемо називатися твоїм ім’ям, — зніми з нас ганьбу».","У той день паросток Господа з’явиться у красі і честі, і плід землі — у величі і славі, для уцілілих синів Ізраїля.","Тоді ті, що залишилися на Сионі й уціліли в Єрусалимі, будуть називатися святими, усі вписані у книгу для життя в Єрусалимі,","коли Господь омиє скверну дочок Сиону й очистить кров Єрусалима із середовища його духом суду і духом вогню.","І створить Господь над усяким місцем гори́ Сиону і над зібраннями її хмару і дим під час дня і блищання палючого вогню у час ночі; бо над усім шанованим буде покров.","І буде намет для осінення удень від спеки і для притулку і захисту від непогоди і дощу."],"x":{"1":"0.30.23","2":"32.23.5|53.1.9","3":"52.10.20","4":"36.24.6|53.16.8|66.5.26","5":"1.13.21|31.10.32|63.10.1","6":"31.25.4|38.14.8|50.7.25"}},{"v":["Заспіваю Улюбленому моєму пісню Улюбленого мого про виноградник Його. В Улюбленого мого був виноградник на вершині плодючої гори,","і Він обніс його огорожею, й очистив його від каменів, і насадив у ньому добірні виноградні лози, і побудував вежу посередині його, і викопав у ньому точило, й очікував, що він принесе добрі грона, а він приніс дикі ягоди.","І нині, жителі Єрусалима і мужі Іуди, розсудіть Мене з виноградником Моїм.","Що ще належало б зробити для виноградника Мого, чого Я не зробив йому? Чому, коли Я очікував, що він принесе добрі грона, він приніс дикі ягоди?","Отже, Я скажу вам, що зроблю з виноградником Моїм: відніму в нього огорожу, і буде він спустошеним; зруйную стіни його, і буде потоптаним,","і залишу його у запустінні: не будуть ні обрізувати, ні обкопувати його, — і заросте він терням і бур’яном, і повелю хмарам не проливати на нього дощ.","Виноградник Господа Саваофа є дім Ізраїлів, і мужі Іуди — улюблене насадження Його. І чекав Він правосуддя, але ось — кровопролиття; чекав правди, і ось — волання.","Горе вам, хто приєднує дім до дому, хто приєднує поле до поля, так що іншим не залишається місця, начебто ви одні оселені на землі.","У вуха мої сказав Господь Саваоф: численні доми ці будуть порожні, великі і красиві — без мешканців;","десять ділянок у винограднику дадуть один бат, і хомер посіяного зерна ледь принесе ефу.","Горе тим, які з раннього ранку шукають сикери і до пізнього вечора розгарячають себе вином;","і цитра і гуслі, тимпан і сопілка і вино на бенкетах їх; а на справи Господа вони не дивляться і про діяння рук Його не думають.","За те народ мій піде у полон непередбачено, і вельможі його будуть голодувати, і багатії його будуть знемагати від спраги.","За те пекло розширилося і безмірно розкрило пащу свою: і зійде туди слава їх і багатство їх, і шум їх і все́, що веселить їх.","І принизиться людина, і смириться муж, і очі гордих поникнуть;","а Господь Саваоф звеличиться у суді, і Бог Святий виявить святість Свою у правді.","І будуть пастися вівці за своєю волею, і чужі будуть живитися залишеними плідними пасовищами багатих.","Горе тим, хто тягне на себе беззаконня мотузками суєти, і гріх — ніби ременями колісничними;","які говорять: «нехай Він поспішить і прискорить діло Своє, щоб ми бачили, і нехай наблизиться і прийде для виконання ради Святого Ізраїлевого, щоб ми пізнали!»","Горе тим, які зло називають добром, і добро — злом, пітьму вважають світлом, і світло — пітьмою, гірке вважають солодким, і солодке — гірким!","Горе тим, які мудрі у своїх очах і розумні перед самими собою!","Горе тим, які сміливі пити вино і сильні готувати міцний напій,","які за подарунки виправдовують винного і правих позбавляють законного!","За те, як вогонь з’їдає солому, і полум’я знищує сіно, так зотліє корінь їх, і цвіт їх розвіється, як порох; тому що вони відкинули закон Господа Саваофа і знехтували слово Святого Ізраїлевого.","За те запалає гнів Господа на народ Його, і простягне Він руку Свою на нього й уразить його, так що здригнуться гори, і трупи їхні будуть як послід на вулицях. І при усьому цьому гнів Його не відвернеться, і рука Його ще буде простягнута.","І підніме прапор народам далеким, і дасть знак тому, хто живе на краю землі, — і ось, він легко і скоро прийде;","не буде у нього ні втомленого, ні знеможеного; жоден не задрімає і не засне, і не зніметься пояс зі стегон його, і не розірветься ремінь на взутті його;","стріли його загострені, і всі луки його натягнуті; копита коней його подібні до кременю, і колеса його — як вихор;","ревіння його — як ревіння левиці; він рикає подібно до скимнів, і зареве, і схопить здобич і віднесе, і ніхто не відніме.","І зареве на нього у той день ніби ревіння розбурханого моря; і спогляне він на землю, і ось — пітьма, горе, і світло померкло у хмарах."],"x":{"1":"32.2.21|50.21.33|51.12.1|52.20.9","2":"32.8.13","5":"25.79.13|14.9.9|38.2.12","6":"31.1.30|48.14.17","7":"25.79.16","8":"43.2.2","11":"26.23.30|27.10.16|52.6.25","12":"31.28.7|40.6.5","14":"31.30.33","15":"31.2.11","17":"31.14.30","18":"26.5.22|43.7.3","19":"32.17.15|40.5.18|57.3.4","20":"11.17.9|40.6.12","21":"26.3.7|62.12.16","22":"26.31.4","23":"26.17.15","24":"31.9.18","25":"31.9.12|31.10.6","26":"2.26.25|31.13.2","28":"32.4.13","29":"24.4.10|32.2.15|32.4.7|36.32.2","30":"24.18.5|31.8.22"}},{"v":["У рік смерти царя Озії бачив я Господа, Який сидить на престолі високому і величному, і краї риз Його наповнювали весь храм.","Навколо Нього стояли серафими; у кожного з них по шість крил: двома закривав кожен лице своє, і двома закривав ноги свої, і двома літав.","І взивали вони один до одного і говорили: Святий, Святий, Святий Господь Саваоф! уся земля повна слави Його!","І похитнулися верхи врат від голосу тих, що викликували, і дім наповнився курінням.","І сказав я: горе мені! загинув я! бо я людина з нечистими вустами, і живу серед народу також з нечистими вустами, — і очі мої бачили Царя, Господа Саваофа.","Тоді прилетів до мене один із серафимів, і в руці у нього розпалене вугілля, яке він узяв кліщами з жертовника,","і торкнувся вуст моїх і сказав: ось, це торкнулося вуст твоїх, і беззаконня твоє вилучене від тебе, і гріх твій очищений.","І почув я голос Господа, Який говорить: кого Мені послати? і хто піде задля Нас? І я сказав: ось я, пошли мене.","І сказав Він: іди і скажи цьому народові: слухом почуєте — і не зрозумієте, і очима будете дивитися — і не побачите.","Бо огрубіло серце народу цього, і вухами насилу чують, і очі свої зімкнули, нехай не побачать очима, і не почують вухами, і не зрозуміють серцем, і не навернуться, щоб Я зцілив їх.","І сказав я: чи надовго, Господи? Він сказав: доки не опустіють міста, і залишаться без жителів, і доми без людей, і доки земля ця зовсім не спустіє.","І виселить Господь людей, і велике запустіння буде на цій землі.","І якщо ще залишиться десята частина на ній і повернеться, і вона знову буде спустошена; але як від теревинфа і як від дуба, коли вони і зрубані, залишається корінь їх, так святе сíм’я буде коренем її."],"x":{"1":"1.24.10|13.26.23|53.12.41","2":"37.7.9-10","3":"76.3.7|76.4.8|52.1.49","4":"36.10.4","5":"1.30.20|4.5.25|6.13.22","6":"75.13.10","7":"32.1.9|37.10.16","8":"71.3.1","9":"32.5.21|50.13.14|51.4.12|52.8.10|53.12.40|54.28.26|62.11.8","11":"13.33.11","13":"48.8.12|48.13.8|31.53.10|38.2.23"}},{"v":["І було у дні Ахаза, сина Іоафамового, сина Озії, царя Юдейського, Рецин, цар Сирійський, і Факей, син Ремаліїн, цар Ізраїльський, пішли проти Єрусалима, щоб завоювати його, але не могли завоювати.","І було сповіщено дому Давидовому і сказано: сиріяни розташувалися у землі Єфремовій; і сколихнулося серце його і серце народу його, як колишуться від вітру дерева у лісі.","І сказав Господь Ісаї: вийди ти і син твій Шеар-Ясув назустріч Ахазу, до кінця водопроводу верхнього ставка, на дорогу до поля білильного,","і скажи йому: спостерігай і будь спокійним; не страшися і нехай не сумує серце твоє від двох кінців цих димлячих головешок, від розпаленого гніву Рецина і сиріян і сина Ремаліїного.","Сирія, Єфрем і син Ремаліїн задумали проти тебе зло, говорячи:","підемо на Юдею й підбуримо її, і оволодіємо нею і поставимо у ній царем сина Тавеїлового.","Але Господь Бог так говорить: це не станеться і не збудеться;","бо глава Сирії — Дамаск, і глава Дамаска — Рецин; а через шістдесят п’ять років Єфрем перестане бути народом;","і глава Єфрема — Самарія, і глава Самарії — син Ремаліїн. Якщо ви не вірите, то тому, що ви не засвідчені.","І продовжував Господь говорити до Ахаза, і сказав:","проси собі знамення у Господа Бога твого: проси або у глибині, або на висоті.","І сказав Ахаз: не буду просити і не буду спокушати Господа.","Тоді сказав Ісая: слухайте ж, доме Давидів! хіба мало для вас утруднювати людей, навіщо ви хочете утруднювати і Бога мого?","Отже, Сам Господь дасть вам знамення: ось, Діва в утробі прийме і народить Сина, і наречуть ім’я Йому: Еммануїл.","Він буде годуватися молоком і медом, доки не буде розуміти відкидати зле й обирати добре;","бо перш ніж це немовля буде розуміти відкидати зле й обирати добре, земля та, якої ти страхаєшся, буде залишена обома царями її.","Але наведе Господь на тебе і на народ твій і на дім батька твого дні, які не приходили з часу відпадіння Єфрема від Іуди, наведе царя Ассирійського.","І буде у той день: дасть знак Господь мусі, яка при гирлі ріки Єгипетської, і бджолі, що у землі Ассирійській, —","і прилетять і всядуться усі вони по долинах опустілих і по розщелинах скель, і по всіх колючих чагарниках, і по всіх деревах.","У той день поголить Господь бритвою, найнятою по той бік ріки, царем Ассирійським, голову і волосся на ногах, і навіть відніме бороду.","І буде у той день: хто буде мати корову і двох овець,","за достатком молока, яке вони дадуть, буде їсти масло; маслом і медом будуть годуватися усі, хто залишився у цій землі.","І буде у той день: на кожному місці, де росла тисяча виноградних лоз на тисячу срібників, буде терня і колючий чагарник.","Зі стрілами і луками будуть ходити туди, бо уся земля буде терням і колючим чагарником.","І на жодну з гір, які розчищалися сапами, не підеш, боячись терня і колючого чагарника: туди будуть виганяти волів, і дрібна худоба буде топтати їх."],"x":{"1":"11.16.5","2":"25.77.9|25.79.3","3":"31.36.2","7":"31.8.10","8":"31.8.4","9":"31.28.16","11":"31.38.7|52.2.12","12":"4.6.16","14":"50.1.23|52.1.31","16":"31.8.4","17":"11.15.29","18":"31.5.26","20":"11.16.7-8","23":"2.26.22"}},{"v":["І сказав мені Господь: візьми собі великий сувій і накресли на ньому людськими письменами: Магер-шелал-хаш-баз*.","І я узяв собі вірних свідків: Урію священика і Захарію, сина Варахіїного, —","і приступив я до пророчиці, і вона зачала і народила сина. І сказав мені Господь: наречи йому ім’я: Магер-шелал-хаш-баз,","бо раніше ніж дитя буде вміти вимовити: батько мій, мати моя, — багатства Дамаска і здобич самарійську понесуть перед царем Ассирійським.","І продовжував Господь говорити до мене і сказав ще:","за те, що цей народ зневажає води Силоама, які течуть тихо, і захоплюється Рецином і сином Ремаліїним,","наведе на нього Господь води ріки бурхливі і великі — царя Ассирійського з усією славою його; і підніметься вона в усіх протоках своїх і виступить із усіх берегів своїх;","і піде по Юдеї, наводнить її і високо підніметься — дійде до шиї; і розпростерті крила її будуть по усій широті землі Твоєї, Еммануїле!","Ворогуйте, народи, але тремтіть, і слухайте, усі віддалені землі! Озброюйтесь, але тремтіть; озброюйтесь, але тремтіть!","Задумуйте задуми, але вони руйнуються; говоріть слово, але воно не збудеться: бо з нами Бог!","Бо так говорив мені Господь, тримаючи на мені міцну руку і напоумлюючи мене не ходити шляхом цього народу, і сказав:","«Не називайте змовою усього того, що народ цей називає змовою; і не бійтеся того, чого він боїться, і не страшіться.","Господа Саваофа — Його шануйте свято, і Він — страх ваш, і Він — тремтіння ваше!","І буде Він освяченням і каменем спотикання, і скелею спокуси для обох домів Ізраїля, петлею і сіткою для жителів Єрусалима.","І багато хто з них спіткнеться і впаде, і розіб’ється, і заплутається у сітях, і буде уловлений.","Зав’яжи свідчення, і запечатай одкровення при учениках Моїх».","Отже, я надіюся на Господа, Який сховав лице Своє від дому Якова, й уповаю на Нього.","Ось я і діти, яких дав мені Господь, як вказівки і знамення в Ізраїлі від Господа Саваофа, Який живе на горі Сионі.","І коли скажуть вам: зверніться до викликачів померлих і до чаклунів, до шептунів і утробомовців, — тоді відповідайте: чи не повинен народ звертатися до свого Бога? чи запитують мертвих про живих?","Звертайтеся до закону й одкровення. Якщо вони не говорять, як це слово, то немає у них світла.","І будуть вони бродити по землі, жорстоко пригноблені і голодні; і під час голоду будуть злостивитися, хулити царя свого і Бога свого.","І глянуть угору, і подивляться на землю; і ось — горе і морок, густа пітьма, і будуть скинуті у пітьму. Але не завжди буде морок там, де тепер він загуснув."],"x":{"1":"31.30.8|45.2.2","4":"31.7.8:16","6":"17.3.15|53.9.11","7":"76.17.15|31.10.8","8":"31.30.28","10":"31.7.7","11":"31.42.8","12":"50.10.26","13":"56.3.15","14":"31.28.16","15":"31.28.13","16":"31.29.11|31.54.13|53.6.45","18":"75.2.13","19":"2.19.31|4.18.11:15","20":"50.13.52|54.28.23","21":"25.58.16","22":"31.5.30"},"n":{"1":["Поспішає грабунок, прискорює здобич."]}},{"v":["Час, що минув, принизив землю Завулонову і землю Неффалимову; але наступний звеличить приморську путь, зайорданську країну, Галилею язичницьку.","Народ, що ходить у пітьмі, побачить світло велике; на тих, що живуть у країні тіні смертної, світло засяє.","Ти примножиш народ, збільшиш радість його. Він буде веселитися перед Тобою, як веселяться під час жнив, як радіють при розподілі здобичі.","Бо ярмо, яке обтяжувало його, і жезл, який уражав його, і тростину, яка пригноблювала його, Ти скрушиш, як у день Мадіама.","Бо усяке взуття воїна під час битви й одяг, обагрений кров’ю, будуть віддані на спалення, на поживу вогню.","Бо Немовля народилося нам — Син даний нам; владарювання на раменах Його, і наречуть ім’я Йому: Дивний, Радник, Бог кріпкий, Отець вічности, Князь миру*.","Примноженню владарювання Його і миру немає межі на престолі Давида й у царстві його, щоб Йому утвердити його і зміцнити його судом і правдою віднині і довіку. Ревність Господа Саваофа зробить це.","Слово посилає Господь на Якова, і воно сходить на Ізраїля,","щоб знав увесь народ, Єфрем і жителі Самарії, які з гордістю і пихатим серцем говорять:","цеглини упали — побудуємо з тесаного каменю; сикомори вирубані — замінимо їх кедрами.","І воздвигне Господь проти нього ворогів Рецина, і супротивників його озброїть:","сиріян зі сходу, а филистимлян із заходу; і будуть вони пожирати Ізраїля повним ротом. При усьому цьому не відвернеться гнів Його, і рука Його ще простерта.","Але народ не навертається до Того, Хто б’є його, і до Господа Саваофа не прибігає.","І відсіче Господь у Ізраїля голову і хвіст, пальму і тростину, в один день:","старець і знатний, — це голова; а пророк-лжевчитель є хвіст.","І вожді цього народу введуть його в оману, і ті, що водять їх, загинуть.","Тому за юнаків його не порадіє Господь, і сиріт його і вдів його не помилує: бо усі вони — лицеміри і лиходії, і вуста усіх говорять нечестиво. При усьому цьому не відвернеться гнів Його, і рука Його ще простерта.","Бо беззаконня, як вогонь, розгорілося, пожирає терня і колючий чагарник і палає у хащах лісу, і піднімаються стовпи диму.","Лють Господа Саваофа обпалить землю, і народ зробиться ніби поживою вогню; не пощадить людина брата свого.","І будуть різати праворуч, і залишаться голодні; і будуть їсти ліворуч, і не будуть ситі; кожен буде пожирати плоть м’язів своїх:","Манассія — Єфрема, і Єфрем — Манассію, обоє разом — Іуду. При усьому цьому не відвернеться гнів Його, і рука Його ще простерта."],"x":{"1":"50.4.15","2":"50.4.16|66.5.14|52.1.79","3":"62.15.9|25.118.162","4":"31.10.26|31.14.5|6.7.23","5":"36.39.9","6":"52.2.7|53.3.16|58.4.9|6.13.18","7":"52.1.32-33","12":"31.5.25","13":"32.5.3|25.33.5","14":"31.19.15","15":"31.3.3","16":"50.15.14|52.6.39","17":"31.5.25|31.10.6","18":"31.5.24|31.10.16|44.1.10","19":"46.1.18","21":"31.9.12|31.11.13|65.5.15"},"n":{"6":["У слов’янській Біблії цей стих читається так: «Бо Немовля народилося нам, Син, і даний нам; владарювання Його на раменах Його, і наречуть ім’я Йому: Великої Ради Ангел, Дивний, Радник, Бог кріпкий, Володар, Князь миру, Отець будучого віку; бо приведу мир князям, мир і здоров’я Його»."]}},{"v":["Горе тим, які постановляють несправедливі закони і пишуть жорстокі рішення,","щоб усунути бідних від правосуддя і викрасти права у слабосилих з народу Мого, щоб удів зробити здобиччю своєю й пограбувати сиріт.","І що ви будете робити у день відвідання, коли прийде загибель здалеку? До кого звернетеся по допомогу? І де залишите багатство ваше?","Без Мене зігнуться між в’язнями і впадуть між убитими. При усьому цьому не відвернеться гнів Його, і рука Його ще простерта.","О, Ассур, жезл гніву Мого! і бич у руці його — Моє обурення!","Я пошлю його проти народу нечестивого і проти народу гніву Мого, дам йому повеління пограбувати грабежем і здобути здобич і потоптати його, як бруд на вулицях.","Але він не так подумає і не так помислить серце його; у нього буде на серці — зруйнувати і знищити чимало народів.","Бо він скаже: «чи не всі царі князі мої?","Халне чи не те саме, що Кархемис? Емаф чи не те саме, що Арпад? Самарія чи не те саме, що Дамаск?","Оскільки рука моя оволоділа царствами ідольськими, в яких кумирів більше, ніж у Єрусалимі й Самарії, —","то чи не зроблю того самого з Єрусалимом і статуями його, як зробив із Самарією та ідолами її?»","І буде, коли Господь звершить усе Своє діло на горі Сионі і в Єрусалимі, скаже: подивлюся на успіх гордовитого серця царя Ассирійського і на марнославство високо піднятих очей його.","Він говорить: «силою руки моєї і моєю мудрістю я зробив це, тому що я розумний: і переставляю межі народів, і розграбовую скарби їх, і скидаю з престолів, як велетень;","і рука моя захопила багатство народів, як гнізда; і як забирають залишені у них яйця, так забрав я всю землю, і ніхто не поворухнув крилом, і не відкрив рота, і не пискнув».","Чи величається сокира перед тим, хто рубає нею? Чи пила пишається перед тим, хто рухає нею? Начебто жезл повстає проти того, хто піднімає його; начебто палка піднімається на того, хто не дерево!","За те Господь, Господь Саваоф, пошле чахлість на повних його, і між знаменитими його запалить полум’я, як полум’я вогню.","Світло Ізраїля буде вогнем, і Святий його — полум’ям, яке спалить і пожере терня його і бур’ян його в один день;","і славний ліс його і сад його, від душі до тіла, знищить; і він буде, як чахлий умирущий.","І залишок дерев лісу його такий буде нечисленний, що дитя спроможне буде зробити опис.","І буде у той день: залишок Ізраїля й ті з дому Якова, що спаслися, не будуть більше покладатися на того, хто уразив їх, але покладуть уповання на Господа, Святого Ізраїлевого, щиросердо.","Залишок навернеться, залишок Якова — до Бога сильного.","Бо хоч би народу в тебе, Ізраїле, було стільки, скільки піску морського, тільки залишок його навернеться; знищення визначено повною правдою;","бо визначене знищення звершить Господь, Господь Саваоф, по усій землі.","Тому так говорить Господь, Господь Саваоф: народе Мій, що живеш на Сионі! не бійся Ассура. Він уразить тебе жезлом і тростину свою підніме на тебе, як Єгипет.","Ще трохи, дуже трохи, і мине Моє обурення, і лють Моя обернеться на знищення їх.","І підніме Господь Саваоф бич на нього, як у час поразки Мадіама біля скелі Орива, або як простяг на море жезл, і підніме його, як на Єгипет.","І буде у той день: зніметься з рамен твоїх тягар його, і ярмо його — із шиї твоєї; і розпадеться ярмо від жиру.","Він іде на Аїаф, проходить Мигрон, у Михмасі складає свої запаси.","Проходять тіснини; у Геві ночівля їх; Рама трясеться; Гива Саулова розбіглася.","Вий голосом твоїм, дочко Галима; нехай почує тебе Лаїс, бідний Анафоф!","Мадмена розбіглася, жителі Гевима поспішають утікати.","Ще день простоїть він у Нові; погрожує рукою своєю горі Сиону, пагорбу Єрусалимському.","Ось, Господь, Господь Саваоф, страшною силою зірве гілки дерев, і ті, що величаються зростом, будуть зрубані, високі — повалені на землю.","І посіче хащу лісу залізом, і Ливан упаде від Всемогутнього."],"x":{"1":"50.23.4","2":"1.22.22|32.7.6","3":"31.9.12","4":"31.9.12","5":"31.7.20|31.36.1","6":"31.5.25|31.9.17|48.10.5","7":"54.4.28|54.13.27","8":"31.8.7","9":"0.10.10|31.36.19|32.46.2","12":"11.19.35|31.37.36","13":"45.1.16","16":"31.5.17|40.4.1","18":"32.21.14","19":"31.10.33","20":"32.3.23|48.13.9","21":"31.9.6","22":"62.9.27","23":"31.28.22","24":"43.7.14|1.1.14","25":"31.54.9","26":"6.7.25|25.82.12|31.9.4","28":"8.14.5","29":"5.18.25","30":"6.18.14|5.21.18","33":"31.10.19","34":"31.9.18"}},{"v":["І вийде паросток від кореня Ієссеєвого, і гілка виросте від кореня його;","і спочине на ньому Дух Господній, дух премудрости і розуму, дух ради і кріпкости, дух вíдання і благочестя;","і страхом Господнім сповниться, і буде судити не за поглядом очей Своїх, і не за слухом вух Своїх вирішувати діла.","Він буде судити бідних за правдою, і діла страдників землі вирішувати за істиною; і жезлом уст Своїх уразить землю, і духом уст Своїх уб’є нечестивого.","І буде опоясанням стегон Його правда, і опоясанням крижів Його — істина.","Тоді вовк буде жити разом з ягням, і барс буде лежати разом з козеням; і теля, і молодий лев, і віл будуть разом, і мале дитя буде водити їх.","І корова буде пастися з ведмедицею, і дитинчата їх будуть лежати разом, і лев, як віл, буде їсти солому.","І немовля буде гратися над норою аспида, і дитя простягне руку свою на гніздо змії.","Не будуть робити зла і шкоди на усій святій горі Моїй, бо земля буде наповнена віданням Господа, як води наповнюють море.","І буде у той день: до кореня Ієссеєвого, який стане, як знамено для народів, навернуться язичники, — і спокій його буде слава.","І буде у той день: Господь знову простягне руку Свою, щоб повернути Собі залишок народу Свого, який залишиться в Ассура, і в Єгипті, і в Патросі, й у Хуса, і в Елама, й у Сеннаарі, й у Емафі, й на островах моря,","І підніме знамено язичникам, і збере вигнанців Ізраїля, і розсіяних юдеїв скличе від чотирьох кінців землі.","І припиниться заздрість Єфрема, і ті, що ворогують проти Іуди, будуть знищені. Єфрем не буде заздрити Іуді, й Іуда не буде пригноблювати Єфрема.","І полетять через плечі филистимлян на захід, пограбують усіх дітей Сходу; на Едома і Моава накладуть руку свою, і діти Аммона будуть підданими їм.","І висушить Господь затоку моря Єгипетського, і простягне руку Свою на ріку в сильному вітрі Своєму, і розіб’є її на сім струмків, так що у сандаліях можуть переходити її.","Тоді для залишку народу Його, що залишиться в Ассура, буде велика дорога, як це було для Ізраїля, коли він виходив із землі Єгипетської."],"x":{"1":"52.3.32|54.13.22|62.15.12","2":"31.61.1","3":"31.2.4","4":"24.4.9|70.2.8","5":"25.44.5","6":"31.65.25","8":"63.3.1|25.57.5","9":"40.5.24","10":"62.15.12","12":"50.15.24|52.21.28|53.10.16","13":"38.1.11","14":"4.32.43|31.60.7|48.8.13","16":"1.14.29"}},{"v":["І скажеш у той день: славлю Тебе, Господи; Ти гнівався на мене, але відвернув гнів Твій і утішив мене.","Ось, Бог — спасіння моє: уповаю на Нього і не боюся; бо Господь — сила моя, і спів мій — Господь; і Він був мені на спасіння.","І у радості будете черпати воду із джерел спасіння,","і скажете у той день: славте Господа, закликайте ім’я Його; сповіщайте у народах діла Його; нагадуйте, що велике ім’я Його;","співайте Господу, бо Він створив велике, — нехай знають це по усій землі.","Веселися і радуйся, жителько Сиону, бо великий посеред тебе Святий Ізраїлів."],"x":{"2":"1.15.2|25.117.14","3":"53.4.14|53.7.38","4":"12.16.8","5":"25.46.7|31.24.14","6":"31.54.1|25.70.22"}},{"v":["Пророцтво про Вавилон, яке прорік Ісая, син Амосів.","Підніміть знамено на відкритій горі, піднесіть голос; махніть їм рукою, щоб ішли у ворота володарів.","Я дав повеління обраним Моїм і закликав для звершення гніву Мого сильних Моїх, які торжествують у величі Моїй.","Великий шум на горах, ніби від багатолюдного народу, бунтівний шум царств і народів, які зібралися разом: Господь Саваоф оглядає бойове військо.","Ідуть з далекої країни, від краю неба, Господь і знаряддя гніву Його, щоб скрушити усю землю.","Ридайте, бо день Господа близький, іде як руйнівна сила від Всемогутнього.","Від того руки у всіх опустилися, і серце у кожної людини розтануло.","Жахнулися, судома і болі схопили їх; мучаться, як та, що народжує, зі здивуванням дивляться одне на одного, обличчя у них розгорілися.","Ось, приходить день Господа лютий, з гнівом і палаючою люттю, щоб зробити землю пустелею і знищити з неї грішників її.","Зірки небесні і світила не дають від себе світла; сонце меркне при сході своєму, і місяць не сяє світлом своїм.","Я покараю світ за зло, і нечестивих — за беззаконня їхні, і покладу кінець зарозумілости гордих, і принижу пихатість гнобителів;","зроблю те, що люди будуть дорожчі за чисте золото, і мужі — дорожчі за золото офирське.","Для цього потрясу небо, і земля зрушиться з місця свого у люті Господа Саваофа, у день палаючого гніву Його.","Тоді кожен, як переслідувана сарна і як покинуті вівці, повернеться до народу свого, і кожен побіжить у свою землю.","Але хто попадеться, буде проколотий, і кого схоплять, той упаде від меча.","І немовлята їхні будуть розбиті на очах їхніх; доми їхні будуть розграбовані і дружини їхні знечещені.","Ось, Я підніму проти них мидян, які не цінують срібла і не мають пристрасти до золота.","Луки їхні уразять юнаків і не пощадять плоду утроби: око їх не зласкавиться над дітьми.","І Вавилон, краса царств, гордість халдеїв, буде знищений Богом, як Содом і Гоморра,","не заселиться ніколи, й у роди родів не буде жителів у ньому; не розкине аравитянин намету свого, і пастухи зі стадами не будуть відпочивати там.","Але будуть жити у ньому звірі пустелі, і доми наповняться пугачами; і страуси оселяться, і кошлаті будуть скакати там.","Шакали будуть вити у палацах їхніх, і гієни — у розважальних домах."],"x":{"1":"32.30.1|32.50.1","2":"31.5.26|31.18.3|32.4.6","3":"32.22.7","6":"39.1.15","8":"11.19.3|25.47.7|31.21.3","9":"31.22.5","10":"31.24.23|36.32.7|39.2.31|39.3.15|50.24.29|51.13.24|52.21.25","14":"10.22.17|51.6.34","16":"25.136.9|32.8.10","17":"32.51.11|37.5.31","19":"0.19.24-25|32.50.40|76.18.2","21":"32.50.39"}},{"v":["Близький час його, і не забаряться дні його, бо помилує Господь Якова і знову полюбить Ізраїля; і оселить їх на землі їхній, і приєднаються до них іноземці і приліпляться до дому Якова.","І візьмуть їх народи, і приведуть на місце їх, і дім Ізраїля засвоїть їх собі на землі Господній рабами і рабинями, і візьме у полон тих, що полонили його, і буде панувати над гнобителями своїми.","І буде у той день: коли Господь визволить тебе від скорботи твоєї і від страху і від тяжкого рабства, в якому ти був поневолений,","ти промовиш переможну пісню на царя Вавилонського і скажеш: як не стало мучителя, припинилося грабіжництво!","Розтрощив Господь жезл нечестивих, скіпетр владик,","який уражав народи у люті ударами невідворотними, який у гніві панував над племенами з нестримним переслідуванням.","Уся земля відпочиває, покоїться, викликує з радости;","і кипариси радіють за тебе, і кедри ливанські, говорячи: «з тих пір, як ти заснув, ніхто не приходить рубати нас».","Пекло глибинне почало рухатися заради тебе, щоб зустріти тебе при вході твоєму; пробудив для тебе рефаїмів, усіх вождів землі; підняв усіх царів язичницьких із престолів їхніх.","Усі вони будуть говорити тобі: і ти зробився безсилим, як ми! і ти став подібним до нас!","У пекло скинута гординя твоя з усім шумом твоїм; під тобою підстилається черва, і черва — покров твій.","Як упав ти з неба, денниця, син зорі! розбився об землю, який топтав народи.","А говорив у серці своєму: «зійду на небо, вище за зірки Божі піднесу престіл мій і сяду на горí у зібранні богів, на краю півночі;","зійду на висоти хмарні, буду подібний до Всевишнього».","Але скинутий у пекло, у глибини пекельні.","Ті, що бачили тебе, вдивляються у тебе, розмірковують про тебе: «чи той це чоловік, який коливав землю, тряс царства,","всесвіт зробив пустелею і руйнував міста його, полонених своїх не відпускав додому?».","Всі царі народів, усі лежать у шані, кожен у своїй усипальниці;","а ти повалений поза гробницею своєю, як знехтувана гілка, як одяг убитих, уражених мечем, яких опускають у кам’яні рови, — ти, як потоптаний труп,","не з’єднаєшся з ними у могилі; бо ти зруйнував землю твою, убив народ твій: повіки не пом’янеться плем’я лиходіїв.","Готуйте заколення синам його за беззаконня батька їхнього, щоб не повстали і не заволоділи землею і не наповнили всесвіт ворогами.","І повстану на них, — говорить Господь Саваоф, — і знищу ім’я Вавилона і весь залишок, і сина й онука, — говорить Господь.","І зроблю його володінням їжаків і болотом, і вимету його мітлою знищувальною, — говорить Господь Саваоф.","З клятвою говорить Господь Саваоф: як Я задумав, так і буде; як Я визначив, так і відбудеться,","щоб знищити Ассура у землі Моїй і розтоптати його на горах Моїх; і спаде з них ярмо його, і зніметься тягар його з рамен їхніх.","Таке визначення, ухвалене про усю землю, і ось рука, простягнута на усі народи,","бо Господь Саваоф визначив, і хто може скасувати це? рука Його простягнута, — і хто відверне її?","У рік смерти царя Ахаза було таке пророче слово:","не радуйся, земле Филистимська, що розтрощено жезл, який уражав тебе, бо з кореня зміїного вийде аспид, і плодом його буде летючий дракон.","Тоді найбідніші будуть нагодовані, жебраки будуть спочивати у безпеці; а твій корінь уморю голодом, і він уб’є залишок твій.","Ридайте, ворота! вий голосом, місто! Розпадешся ти, уся земле Филистимська, тому що від півночі дим іде, і немає відсталого у полчищах їх.","Що ж скажуть вісники народу? — Те, що Господь утвердив Сион, і у ньому знайдуть притулок бідні з народу Його."],"x":{"2":"41.1.17|76.13.10","4":"32.50.23","5":"25.124.3|31.9.4","8":"11.19.23","9":"36.31.16|32.50.9|37.8.5","10":"36.32.21","11":"37.4.29-31|52.1.52","12":"37.8.10","13":"58.2.16|36.40.2","15":"36.32.23","20":"24.18.19","21":"1.20.5","23":"32.25.12","25":"11.19.35","27":"13.20.6|24.9.12|37.4.32","28":"13.28.27","29":"13.26.6|32.48.17|11.18.8","30":"31.5.17","32":"25.86.2|25.101.17"}},{"v":["Пророцтво про Моав. — Так! уночі буде зруйнований Ар-Моав і знищений; так! уночі буде зруйнований Кир-Моав і знищений!","Він піднімається до Баїта і Дивона, піднімається на висоти, щоб плакати; Моав ридає над Нево́ і Медевою; у всіх них обстрижені голови, в усіх поголені бороди.","На вулицях його опоясуються веретищем; на покрівлях його і площах його усе ридає, потопає у сльозах.","І волає Есевон і Елеала; голос їх чується до самої Іааци; за ними і воїни Моава ридають; душа його збурена в ньому.","Ридає серце моє за Моавом; біжать з нього до Сигора, до третьої Егли; піднімаються на Лухит з плачем; по дорозі Хоронаїмській здіймають страшний крик;","тому що води Нимрима вичерпалися, луки засохли, трава вигоріла, не стало зелені.","Тому вони залишки запасів і те, що збережено ними, переносять за ріку Аравійську.","Бо волання по усіх краях Моава, до Еглаїма плач його і до Беер-Елима плач його;","тому що води Димона наповнилися кров’ю, і Я наведу на Димон ще нове — левів на тих, що втекли з Моава, і на тих, що залишилися у країні."],"x":{"1":"32.48.13","2":"32.48.37|36.7.18","3":"31.22.1","5":"32.48.34","6":"3.32.36","8":"3.21.15|9.8.2|11.1.1"}},{"v":["Посилайте агнців володарю землі з Сели у пустелі на гору дочки Сиону;","бо до мандрівного птаха, викинутого з гнізда, будуть подібні дочки Моава біля бродів Арнонських.","«Збери раду, ухвали рішення; осіни нас серед полудня, як уночі, тінню твоєю, укрий вигнаних, не видай тих, що блукають.","Нехай поживуть у тебе мої вигнані моавитяни; будь їм покровом від грабіжника: бо гнобителя не стане, грабунок припиниться, ті, що топчуть, зникнуть із землі.","Й утвердиться престіл милістю, і сяде на ньому в істині, у наметі Давидовому, суддя, що шукає правди і прагне правосуддя».","«Чули ми про гордість Моава, гордість надмірну, про пихатість його і зарозумілость і шаленість його: нещира мова його».","Тому заридає Моав за Моавом, — усі будуть ридати; стогніть за твердинями Кирхарешета: вони зовсім зруйновані.","Поля есевонські зубожіли, також і виноградник севамський; володарі народів знищили кращі лози його, які досягали Іазера, розстилалися по пустелі; пагони їх розширювалися, переходили за море.","Тому і я буду плакати за лозою севамською плачем Іазера, буду обливати тебе сльозами моїми, Есевон і Елеала; бо під час збирання винограду твого і під час жнив твоїх немає більше гучної радости.","Зникли з плодючої землі веселощі і радість, і у виноградниках не співають, не торжествують; виноградар не топче винограду у точилах: Я припинив радість.","Від того нутрощі мої стогнуть за Моавом, як гуслі, і серце моє — за Кирхарешетом.","Хоч і з’явиться Моав, і буде до втоми подвизатися на висотах, і прийде до святилища свого помолитися, але ніщо не допоможе.","Ось слово, яке прорік Господь про Моав здавна.","Нині ж так говорить Господь: через три роки, рахуючи роками найманства, велич Моава буде принижена з усією великою багатолюдністю, і залишок буде дуже малий і незначний."],"x":{"5":"37.7.14:27|43.4.7|52.1.32","7":"32.48.20","8":"32.48.32","10":"32.48.33","11":"32.4.19|32.48.36|33.1.20","13":"31.15.1","14":"31.21.16"}},{"v":["Пророцтво про Дамаск. — Ось, Дамаск виключається з числа міст і буде купою руїн.","Міста ароерські будуть покинуті, — залишаться для стад, які будуть відпочивати там, і нікому буде лякати їх.","Не стане твердині Єфремової і царства Дамаскського зі всією Сирією; з ними буде те саме, що зі славою синів Ізраїля, — говорить Господь Саваоф.","І буде у той день: умалиться слава Якова, і повне тіло його стане худим.","Те саме буде, що після збору хліба женцем, коли рука його пожне колосся, і коли зберуть колосся у долині Рефаїмській.","І залишаться у нього, як буває при оббиванні маслин, дві-три ягоди на самій вершині, або чотири-п’ять на плодючих гілках, — говорить Господь, Бог Ізраїлів.","У той день зверне людина погляд свій до Творця свого, і очі її будуть спрямовані до Святого Ізраїлевого;","і не гляне на жертовники, на діло рук своїх, і не подивиться на те, що зробили пальці її, на ідолів Астарти і Ваала.","У той день укріплені міста будуть, як руїни у лісах і на вершинах гір, залишені перед синами Ізраїля, — і буде порожньо.","Бо ти забув Бога спасіння твого, і не згадував про скелю притулку твого; від того розвів розважальні сади і насадив живці від чужої лози.","У день насадження твого ти піклувався, щоб воно росло і щоб посіяне тобою рано розцвіло; але у день збирання не купа жни́ва буде, але скорбота жорстока.","На жаль! шум народів багатьох! шумлять вони, як шумить море. Ревіння племен! вони ревуть, як ревуть сильні води.","Ревуть народи, як ревуть сильні води; але Він пригрозив їм і вони далеко побігли, і були гнані, як порох по горах від вітру і як пил від вихору.","Вечір — і ось жах! і раніше ранку вже немає його. Така доля грабіжників наших, жереб руйнівників наших."],"x":{"1":"31.7.8","5":"31.24.13","6":"31.1.9|32.6.9","8":"31.2.20","10":"4.32.32|50.15.13","12":"11.19.35|31.37.36","13":"25.1.4","14":"11.19.35"}},{"v":["Горе землі, яка осіняє крилами по той бік рік ефіопських,","і посилає послів по морю, у папірусних суднах по водах! Ідіть, швидкі посли, до народу міцного і бадьорого, до народу страшного від початку і донині, до народу рослого і який усе топче, землю якого розрізають ріки.","Усі ви, що населяєте всесвіт і живете на землі! дивіться, коли знамено підніметься на горах, і, коли засурмить труба, слухайте!","Бо так Господь сказав мені: Я спокійно дивлюся з оселі Моєї, як світла теплота після дощу, як хмара роси під час жнивної спеки.","Бо раніше збирання винограду, коли він відцвіте, і грона почнуть дозрівати, Він обріже ножем гілки і відкине, і відрубає гілля.","І залишать усе хижим птахам на горах і звірам польовим; і птахи будуть проводити там літо, а всі звірі польові будуть зимувати там.","У той час буде принесений дар Господу Саваофу від народу міцного і бадьорого, від народу страшного від початку і донині, від народу рослого, і який усе́ топче, землю якого розрізають ріки, — до місця імені Господа Саваофа, на гору Сион."],"x":{"1":"31.20.3|36.30.4|44.3.9","3":"31.5.26|32.4.5-6|32.6.1","4":"31.42.14","6":"36.31.13","7":"31.18.2|31.19.19|13.6.6"}},{"v":["Пророцтво про Єгипет. — Ось, Господь сидить на хмарі легкій і гряде в Єгипет. І затремтять від лиця Його ідоли єгипетські, і серце Єгипту розтане у ньому.","Я озброю єгиптян проти єгиптян; і будуть битися брат проти брата і друг проти друга, місто з містом, царство з царством.","І дух Єгипту знеможе у ньому, і зруйную раду його, і вдадуться вони до ідолів і до чаклунів, і до тих, що викликають мертвих, і до ворожбитів.","І віддам єгиптян до рук володаря жорстокого, і лютий цар буде панувати над ними, говорить Господь, Господь Саваоф.","І виснажаться води у морі і ріка вичерпається і висохне;","і збідніють ріки, і канали єгипетські обміліють і висохнуть; очерет і тростина зав’януть.","Поля біля ріки, по берегах ріки, і все, посіяне біля ріки, засохне, розвіється і зникне.","І заплачуть рибалки, і заридають усі, хто кидає вудку в ріку, і ті, що ставлять сіті у воді, засмутяться,","і будуть збентежені ті, що обробляють льон, і ткачі білих полотен;","і будуть роздерті сіті, й усі, які мають насадки для живої риби, впадуть духом.","Так! збожеволіли князі цоанські; рада мудрих радників фараонових стала безглуздою. Як скажете ви фараонові: «я син мудреців, син царів древніх?»","Де вони? де твої мудреці? нехай вони тепер скажуть тобі; нехай довідаються, що́ Господь Саваоф визначив про Єгипет.","Збожеволіли князі цоанські; впали в оману князі мемфиські, і звів Єгипет з путі глав племен його.","Господь послав у нього дух сп’яніння; і вони ввели Єгипет в оману в усіх ділах його, подібно до того, як п’яний бродить по блювотині своїй.","І не буде в Єгипті такого діла, яке вміли б зробити голова і хвіст, пальма і тростина.","У той день єгиптяни будуть подібні до жінок, і затремтять і убояться руху руки Господа Саваофа, яку Він підніме на них.","Земля Іудина зробиться жахом для Єгипту; хто згадає про неї, той затремтить від визначення Господа Саваофа, яке Він ухвалив про нього.","У той день п’ять міст у землі Єгипетській будуть говорити мовою ханаанською і клястися Господом Саваофом; одне назветься містом сонця.","У той день жертовник Господу буде посередині землі Єгипетської, і пам’ятник Господу — біля меж її.","І буде він знаменням і свідченням про Господа Саваофа у землі Єгипетській, тому що вони воззвуть до Господа з причини гнобителів, і Він пошле їм спасителя і заступника, і визволить їх.","І Господь явить Себе в Єгипті; і єгиптяни у той день пізнають Господа і принесуть жертви і дари, і дадуть обітниці Господу, і виконають.","І уразить Господь Єгипет; уразить і зцілить; вони навернуться до Господа, і Він почує їх, і зцілить їх.","У той день з Єгипту в Ассирію буде велика дорога, і буде приходити Ассур у Єгипет, і єгиптяни — в Ассирію; і єгиптяни разом з ассиріянами будуть служити Господу.","В той день Ізраїль буде третім з Єгиптом і Ассирією; благословення буде посеред землі,","яку благословить Господь Саваоф, говорячи: благословенний народ Мій — єгиптяни, і діла рук Моїх — ассиріяни, і спадщина Моя — Ізраїль."],"x":{"1":"32.46.2|36.29.2|36.30.18|31.10.10","2":"13.20.23|36.38.21","3":"31.8.10|11.1.2|36.21.21","5":"36.30.12","11":"3.13.23|25.77.12|31.30.4","13":"32.2.16|38.9.6","14":"10.22.21","15":"31.9.14","18":"4.10.20|31.48.1|32.12.16","19":"31.18.7|0.28.18|1.24.4","20":"5.24.27","21":"25.50.21|49.3.3|56.2.5","23":"31.11.16|31.35.8|31.57.14|54.15.17","25":"38.2.1"}},{"v":["У рік, коли Тартан прийшов до Азота, бувши посланим від Саргона, царя Ассирійського, і воював проти Азота, і взяв його,","у той самий час Господь сказав Ісаї, синові Амосовому, так: піди і зніми веретище зі стегон твоїх і скинь сандалії твої з ніг твоїх. Він так і зробив: ходив нагий і босий.","І сказав Господь: як раб Мій Ісая ходив нагий і босий три роки, на вказівку і знамення про Єгипет і Ефіопію,","так поведе цар Ассирійський полонених з Єгипту і переселенців з Ефіопії, молодих і старих, нагими і босими і з оголеними стегнами, для посоромлення Єгипту.","Тоді жахнуться і засоромляться через Ефіопію, надію свою, і через Єгипет, яким хвалилися.","І скажуть у той день жителі цієї країни: ось які ті, на яких ми надіялися і до яких зверталися по допомогу, щоб урятуватися від царя Ассирійського! і як урятувалися б ми?"],"x":{"1":"11.18.17","2":"11.1.8|48.13.4","6":"11.17.4"}},{"v":["Пророцтво про пустелю приморську. — Як бурі на півдні носяться, йде він від пустелі, із землі страшної.","Грізне видіння показане мені: грабіжник грабує, спустошувач спустошує; піднімайся, Еламе, облягай, Миде! усім стогнанням я покладу кінець.","Від цього стегна мої трясуться; муки схопили мене, як муки тієї, що народжує. Я схвильований від того, що чую; я збентежений від того, що бачу.","Серце моє тремтить; дрож б’є мене; відрадна ніч моя перетворилася на жах для мене.","Готують стіл, розстилають покривала, — їдять, п’ють. «Вставайте, князі, мажте щити!»","Бо так сказав мені Господь: піди, постав сторожа; нехай він розповідає, що побачить.","І побачив він вершників на конях, вершників на ослах, вершників на верблюдах, що їхали попарно; і вслухався він старанно, з великою увагою, —","і закричав, як лев: господарю мій! на сторожі стояв я весь день, і на місці моєму залишався цілі ночі:","і ось, їдуть люди, вершники на конях попарно. Потім він виголосив і сказав: упав, упав Вавилон, і всі ідоли богів його лежать на землі розбиті.","О, вимолочений мій і син току мого! Що чув я від Господа Саваофа, Бога Ізраїлевого, те і сповістив вам.","Пророцтво про Думу. — Кричать до мене із Сеїра: сторож! скільки ночі? сторож! скільки ночі?","Сторож відповідає: наближається ранок, але ще ніч. Якщо ви наполегливо запитуєте, то наверніться і приходьте.","Пророцтво про Аравію. — У лісі аравійському ночуйте, каравани деданські!","Хто живе у землі Фемайській! несіть воду назустріч спраглим; з хлібом зустрічайте тих, що біжать,","бо вони від мечів біжать, від меча оголеного і від лука натягнутого, і від лютости війни.","Бо так сказав мені Господь: ще рік, рівний року найманця, і вся слава Кидарова щезне,","і луків у хоробрих синів Кидара залишиться небагато: так сказав Господь, Бог Ізраїлів."],"x":{"2":"31.22.6|32.49.35|54.2.9","3":"32.4.19|43.1.8|31.13.8","4":"31.15.5","5":"32.6.4-5","6":"25.120.4","8":"45.2.1","9":"32.51.8|76.14.8|76.18.2:10","10":"31.25.10|32.51.33|43.4.13","13":"32.25.23","14":"0.25.3:15","16":"31.16.14|32.49.28","17":"31.22.25|31.25.8"}},{"v":["Пророцтво про долину видіння. — Що з тобою, що ти весь зійшов на покрівлі?","Місто гамірливе, яке хвилюється, місто радісне! Уражені твої не мечем убиті і не у битві померли;","усі вожді твої бігли разом, але були зв’язані стрільцями; усі знайдені у тебе зв’язані разом, як би далеко не бігли.","Тому говорю: залиште мене, я буду плакати гірко; не намагайтеся утішати мене у розоренні дочки народу мого.","Бо день сум’яття і потоптання і збентеження у долині видіння від Господа, Бога Саваофа. Ламають стіну, і крик піднімається у гори.","І Елам несе сагайдак; люди на колісницях і вершники, і Кир оголює щит.","І ось, кращі долини твої повні колісниць, і вершники вишикувалися навпроти воріт,","і знімають покров з Юдеї; і ти у той день звертаєш погляд на запас зброї у домі кедровому.","Але ви бачите, що багато проламів у стіні міста Давидового, і збираєте во́ди у нижньому ставку;","і відзначаєте доми у Єрусалимі, і руйнуєте доми, щоб зміцнити стіну;","і влаштовуєте між двома стінами сховище для вод старого ставка. А на Того, Хто це робить, не дивитеся, і не дивитеся на Того, Хто здавна визначив це.","І Господь, Господь Саваоф, закликає вас у цей день плакати і тужити, й обстригти волосся й опоясатися веретищем.","Але ось, веселощі і радість! Убивають волів, і ріжуть овець; їдять м’ясо, і п’ють вино: «будемо їсти і пити, бо завтра помремо!»","І відкрив мені у вуха Господь Саваоф: не буде прощено вам це нечестя, доки не помрете, сказав Господь, Господь Саваоф.","Так сказав Господь, Господь Саваоф: іди собі, піди до цього царедворця, до Севни, начальника палацу [і скажи йому]:","що у тебе тут, і хто тут у тебе, що ти тут висікаєш собі гробницю? — Він висікає собі гробницю на підвищенні, вирубує у скелі житло собі.","Ось, Господь перекине тебе, як кидає сильна людина, і стисне тебе у клубок;","згорнувши тебе у згорток, кине тебе, як меч, у землю простору; там ти помреш, і там чудові колісниці твої будуть ганьбою для дому господаря твого.","І зіштовхну тебе з місця твого, і скину тебе із ступеня твого.","І буде у той день, прикличу раба Мого Елиакима, сина Хелкиїного,","і вдягну його в одяг твій, і поясом твоїм підпережу його, і владу твою передам до рук його; і буде він батьком для жителів Єрусалима і для дому Іудиного.","І ключ дому Давидового покладу на рамена його; відчинить він, і ніхто не зачинить; зачинить він, і ніхто не відчинить.","І зміцню його як цвях у твердому місці; і буде він як сідалище слави для дома батька свого.","І буде висіти на ньому вся слава дому батька його, дітей та онуків, усього домашнього начиння до останніх музичних інструментів.","У той день, — говорить Господь Саваоф, — похитнеться цвях, укріплений у твердому місці, і буде вибитий, і впаде, і розпадеться уся вага, яка на ньому: бо Господь говорить."],"x":{"1":"31.15.3","2":"31.27.10","4":"32.4.20","5":"31.13.5","6":"31.21.2|32.49.35","8":"10.7.2","10":"32.33.4","11":"31.7.3","12":"43.1.16","13":"29.2.6|31.56.12|63.15.32","14":"50.12.32|75.6.4","18":"25.48.11|32.22.18","20":"11.18.18","22":"24.12.14|76.3.7","23":"14.9.8|48.10.4","25":"31.21.17"}},{"v":["Пророцтво про Тир. — Ридайте, кораблі Фарсиса, бо він зруйнований; немає домів, і нема кому входити у доми. Так їм сповіщено із землі Киттийської.","Замовкніть, мешканці острова, який наповнювали купці сидонські, що плавають по морю.","По великих водах привозили в нього насіння Сихора, жниво великої ріки, і був він торговищем народів.","Посоромся, Сидоне; бо ось що говорить море, сила морська: «як би не мучилося я пологами і не народжувало, і не виховувало юнаків, не вирощувало дівчат».","Коли звістка дійде до єгиптян, здригнуться вони, почувши про Тир.","Переселяйтеся у Фарсис, ридайте, мешканці острова!","Чи це ваше радісне місто, початок якого від днів древніх? Ноги його несуть його блукати у країні далекій.","Хто визначив це Тиру, який роздавав вінці, якого купці були князями, торговці — знаменитостями землі?","Господь Саваоф визначив це, щоб посоромити гордовитість усякої слави, щоб принизити всі знаменитості землі.","Ходи по землі твоїй, дочко Фарсиса, як ріка: немає більше перепони.","Він простяг руку Свою на море, потряс царства; Господь дав повеління про Ханаана зруйнувати укріплення його","і сказав: ти не будеш більше радіти, осоромлена дівчино, дочко Сидона! Вставай, іди в Киттим, але і там не буде тобі спокою.","Ось земля халдеїв. Цього народу раніше не було; Ассур поклав йому початок з мешканців пустель. Вони ставлять вежі свої, руйнують палаци його, перетворюють його на руїни.","Ридайте, кораблі фарсиські! Бо твердиня ваша розорена.","І буде в той день, забудуть Тир на сімдесят років, мірою днів одного царя. Після закінчення ж сімдесяти років з Тиром буде те саме, що співають про блудницю:","«візьми цитру, ходи по місту, забута блуднице! Грай складно, співай багато пісень, щоб згадали про тебе».","І буде, після закінчення сімдесяти років, Господь відвідає Тир; і він знову почне одержувати прибуток свій і буде блудодіяти з усіма царствами земними по всьому всесвіту.","Але торгівля його і прибуток його будуть присвячувані Господу; не будуть замкнені і покладені в комори, бо до тих, що живуть перед лицем Господа, буде переходити прибуток від торгівлі його, щоб вони їли до ситости і мали одяг міцний."],"x":{"1":"32.47.4|3.24.24","4":"36.28.21","8":"76.18.23","11":"24.12.24","16":"36.26.13"}},{"v":["Ось, Господь спустошує землю і робить її неплідною: змінює вигляд її і розсіває тих, що живуть на ній.","І що буде з народом, те і зі священиком; що зі слугою, те і з господарем його; що зі служницею, те і з господинею її; що з тим, хто купує, те і з тим, що продає; що з позичальником, те і з позикодавцем; що з лихварем, те і з тим, що дає у ріст.","Земля спустошена вкрай і зовсім розграбована, бо Господь прорік слово це.","Ремствує, смутна земля; поник, смутний всесвіт; поникли ті, що підносилися над народом землі.","І земля осквернена тими, що живуть на ній, бо вони переступили закони, змінили устав, порушили вічний завіт.","За те прокляття поїдає землю, і несуть покарання ті, що живуть на ній; за те спалені мешканці землі, і небагато залишилося людей.","Плаче сік грона; хворіє виноградна лоза; зітхають усі, що веселилися серцем.","Припинилися веселощі з тимпанами; замовк шум тих, хто веселиться; затихли звуки гуслів;","уже не п’ють вина з піснями; гірка сикера для тих, які п’ють її.","Зруйноване запустіле місто, всі доми замкнені, не можна ввійти.","Плачуть за вином на вулицях; затьмарилася усяка радість; вигнана усяка веселість землі.","У місті лишилося запустіння, і ворота розвалилися.","А посеред землі, між народами, буде те саме, що буває при оббиванні маслин, при оббиранні винограду, коли закінчене збирання.","Вони піднесуть голос свій, торжествуючи у величі Господа, голосно будуть викликувати з моря.","Отже, славте Господа на сході, на островах морських — ім’я Господа, Бога Ізраїлевого.","Від краю землі ми чуємо пісню: «Слава Праведному!» І сказав я: лихо мені, лихо мені! горе мені! лиходії злодійствують, і злодійствують лиходії як злочинники.","Жах і яма і петля для тебе, жителю землі!","Тоді той, хто побіжить від крику жаху, упаде в яму; і хто вийде з ями, потрапить у петлю; бо вікна з небесної висоти розкриються, і основи землі потрясуться.","Земля розтрощується, земля розпадається, земля сильно трясеться;","хитається земля, наче п’яний, і качається, як колиска, і беззаконня її тяжіє на ній; вона впаде, і вже не встане.","І буде у той день: відвідає Господь воїнство піднесене на висоті і царів земних на землі.","І будуть зібрані разом, як в’язні, у рів, і будуть зачинені у в’язниці, і після багатьох днів будуть покарані.","І почервоніє місяць, і засоромиться сонце, коли Господь Саваоф воцариться на горі Сионі й у Єрусалимі, і перед старійшинами його буде слава."],"x":{"1":"32.13.24|32.18.17|36.5.10","2":"38.4.9","5":"46.1.3","6":"31.1.9","8":"32.16.9|36.26.13|38.2.11","13":"31.17.5","14":"31.12.5","18":"32.48.44","19":"32.2.37|32.32.5","20":"31.19.14|24.27.18","21":"31.5.14|31.40.2","22":"36.32.18","23":"31.13.10"}},{"v":["Господи! Ти Бог мій; буду прославляти Тебе, буду величати ім’я Твоє, бо Ти звершив дивне; напередвизначення древні істинні, амінь.","Ти перетворив місто на купу каміння, міцне укріплення на руїни; палаців іноплемінників уже не стало у місті; повік не буде воно відновлене.","Тому будуть прославляти Тебе народи сильні; міста страшних племен будуть боятися Тебе,","бо Ти був притулком бідного, притулком убогого у тяжкий для нього час, захистом від бурі, тінню від спеки; бо гнівне дихання тиранів було подібне до бурі проти стіни.","Як спека в місці безводному, Ти приборкав буйство ворогів; як спеку тінню хмари, придушено тріумфування гнобителів.","І зробить Господь Саваоф на горі цій для усіх народів трапезу з ситних страв, трапезу з чистих вин, з жиру кісток і найчистіших вин;","і знищить на горі цій покривало, яке покриває усі народи, покривало, яке лежить на усіх племенах.","Поглинена буде смерть навіки, і витре Господь Бог сльози з усіх облич, і зніме ганьбу з народу Свого по усій землі; бо так говорить Господь.","І скажуть у той день: ось Він, Бог наш! на Нього ми уповали, і Він спас нас! Цей є Господь; на Нього уповали ми; радіймо і веселімось у спасінні Його!","Бо рука Господа спочиває на горі цій, і Моав буде подоланий на місці своєму, як топчеться солома у гною.","І хоч він простягне посеред нього руки свої, як плавець простягає їх для плавання, але Бог принизить гордість його разом з лукавством рук його.","І твердиню високих стін твоїх зруйнує, скине, повалить на землю, у порох."],"x":{"1":"1.15.2|31.28.29","2":"11.19.25|31.26.5","3":"24.12.14","4":"31.4.6|32.16.19","5":"31.18.4","6":"50.22.2|52.14.16","8":"63.15.54|76.7.17|76.21.4","9":"38.13.14|53.3.36|75.2.14","10":"31.41.15|48.10.5"}},{"v":["У той день будуть співати пісню цю у землі Іудиній: місто міцне у нас; спасіння дав Він замість стіни і валу.","Відчиніть ворота; нехай увійде народ праведний, який зберігає істину.","Твердого духом Ти зберігаєш у довершеному мирі, бо на Тебе уповає він.","Уповайте на Господа повіки, бо Господь Бог є твердиня вічна:","Він скидає тих, що жили на висоті, місто, що високо стояло; повалив його, повалив на землю, кинув його у порох.","Нога топче його, ноги бідного, стопи убогих.","Путь праведника пряма; Ти вирівнюєш шлях праведника.","І на путі судів Твоїх, Господи, ми уповали на Тебе; до імені Твого і до спогадів про Тебе прагнула душа наша.","Душею моєю я прагнув до Тебе вночі, і духом моїм я буду шукати Тебе у нутрощах моїх з раннього ранку, бо коли суди Твої звершуються на землі, тоді ті, що живуть у мирі, навчаються правди.","Якщо нечестивий буде помилуваний, то не навчиться він правди, — буде лиходійствувати у землі правих і не буде дивитися на велич Господа.","Господи! рука Твоя була високо піднята, але вони не бачили її; побачать і посоромляться ті, що ненавидять народ Твій; вогонь пожере ворогів Твоїх.","Господи! Ти даруєш нам мир; бо і всі діла наші Ти влаштовуєш для нас.","Господи Боже наш! інші владики, крім Тебе, панували над нами; але через Тебе тільки ми славимо ім’я Твоє.","Мертві не оживуть; рефаїми не встануть, тому що Ти відвідав і знищив їх, і знищив усяку пам’ять про них.","Ти примножив народ, Господи, примножив народ, — прославив Себе, поширив усі краї землі.","Господи! у біді він шукав Тебе; проливав тихе моління, коли покарання Твоє осягало його.","Як вагітна жінка, коли настає час пологів, мучиться, волає від болю свого, так були ми перед Тобою, Господи.","Були вагітні, мучилися, — і народжували ніби вітер; спасіння не надали землі, й інші жителі всесвіту не упали.","Оживуть мерці Твої, повстануть мертві тіла! Оживайте і торжествуйте, повалені у порох: бо роса Твоя — роса рослин, і земля вивергне мерців.","Піди, народе мій, увійди у покої твої і замкни за собою двері твої, сховайся на мить, доки не мине гнів;","бо ось, Господь виходить з оселі Своєї покарати мешканців землі за їхнє беззаконня, і земля відкриє поглинену нею кров і вже не сховає убитих своїх."],"x":{"1":"25.45.2|25.124.1|26.18.11","2":"25.117.19","3":"31.27.5","4":"4.32.4","5":"31.25.12","6":"31.28.3","8":"25.43.18","9":"25.76.7","10":"31.5.12|54.12.19","11":"31.33.3|50.21.15","12":"62.8.28","14":"76.20.5","16":"25.17.7","17":"53.16.21|11.19.3|31.13.8","19":"11.4.35|36.37.3","20":"25.29.6|31.54.8","21":"43.1.3"}},{"v":["У той день уразить Господь мечем Своїм тяжким, і великим і міцним, левіафана, змія, що прямо біжить, і левіафана, змія, що вигинається, й уб’є чудовисько морське.","У той день оспівайте його — улюблений виноградник:","Я, Господь, охоронитель його, кожної миті напуваю його; вночі і вдень стережу його, щоб ніхто не увірвався в нього.","Гніву немає у Мене. Але якби хто протиставив Мені у ньому бур’ян і терня, Я війною піду проти нього, випалю його зовсім.","Хіба удасться до захисту Мого й укладе мир зі Мною? тоді нехай укладе мир зі Мною.","У грядущі дні укоріниться Яків, дасть паросток і розцвіте Ізраїль; і наповниться плодами вселенна.","Чи так Він уражав його, як уражав тих, що уражали його? Чи так убивав його, як убиті ті, що убивали його?","Мірою Ти карав його, коли відкидав його; викинув його сильним подувом Своїм, ніби у день східного вітру.","І через це загладиться беззаконня Якова; і плодом цього буде зняття гріха з нього, коли усі камені жертовників він перетворить на шматки вапна, і не будуть уже стояти діброви й ідоли сонця.","Бо укріплене місто спорожніє, оселі будуть покинуті й обезлюднені, як пустеля. Там буде пастися теля, і там воно буде спочивати і об’їдати гілки його.","Коли гілки його засохнуть, їх обламають; жінки прийдуть і спалять їх. Оскільки це народ безрозсудний, то не пожаліє його Творець його, і не помилує його Творець його.","Але буде у той день: Господь потрясе усе́ від великої ріки до потоку Єгипетського, і ви, сини Ізраїля, будете зібрані один до одного;","і буде у той день: засурмить велика труба, і прийдуть заблудлі в Ассирійській землі і вигнані у землю Єгипетську і поклоняться Господу на горі святій у Єрусалимі."],"x":{"1":"24.26.13|76.19.20","6":"25.71.16|31.37.31","7":"9.7.14|64.4.17","8":"32.10.24|32.30.11|32.46.28","9":"48.3.4|2.26.30","10":"11.19.25|31.24.10","11":"24.24.20|32.5.21","13":"31.2.2|36.20.40"}},{"v":["Горе вінку гордости п’яних єфремлян, зів’ялій квітці красивого вбрання його, яка на вершині плодючої долини уражених вином!","Ось, міцний і сильний у Господа, як злива з градом і згубний вихор, як розлита повінь бурхливих вод, із силою валить його на землю.","Ногами топчеться вінок гордости п’яних єфремлян.","І з зів’ялою квіткою красивого убрання його, яка на вершині плодючої долини, відбувається те саме, що буває із дозрілою раніше часу смоквою, яку, як тільки хто побачить, негайно бере у руку і проковтує її.","У той день Господь Саваоф буде чудовим вінцем і славною діадемою для залишку народу Свого,","і духом правосуддя для того, хто сидить на судилищі, і мужністю для тих, що відбивають ворога біля воріт.","Але і ці хитаються від вина і збиваються зі шляху від сикери; священик і пророк спотикаються від міцних напоїв; переможені вином, збожеволіли від сикери, у видінні помиляються, у судженні спотикаються.","Бо усі столи наповнені гидкою блювотиною, немає чистого місця. —","А говорять: «кого хоче він учити вíдання? і кого врозумлювати проповіддю? віднятих від грудного молока, відлучених від сосків матері?","Бо усе заповідь на заповідь, заповідь на заповідь, правило на правило, правило на правило, тут трохи і там трохи».","За те белькотливими вустами і чужою мовою будуть говорити до цього народу.","Їм говорили: «ось — спокій, дайте спокій натрудженому, і ось — заспокоєння». Але вони не хотіли слухати.","І стало у них словом Господа: заповідь на заповідь, заповідь на заповідь, правило на правило, правило на правило, тут трохи, там трохи, — так що вони підуть, і упадуть горілиць, і розіб’ються, і потраплять у сітку і будуть уловлені.","Отже, слухайте слово Господнє, хульники, правителі народу цього, який у Єрусалимі.","Тому що ви говорите: «ми уклали союз зі смертю і з пеклом зробили договір: коли всевражаючий бич буде проходити, він не дійде до нас, — тому що неправду зробили ми притулком для себе, і обманом прикриємо себе».","Тому так говорить Господь Бог: ось, Я покладаю в основу на Сионі камінь, — камінь випробуваний, наріжний, дорогоцінний, міцно утверджений: віруючий у нього не посоромиться.","І поставлю суд мірилом і правду терезами; і градом знищиться притулок неправди, і води потоплять місце приховування.","І союз ваш зі смертю зруйнується, і договір ваш із пеклом не встоїть. Коли піде всевражаючий бич, ви будете потоптані.","Як тільки він піде, схопить вас; ходити ж буде щоранку, день і ніч, і одна чутка про нього буде вселяти жах.","Занадто коротка буде постіль, щоб простягнутися; занадто вузькою і ковдра, щоб загорнутися у неї.","Бо повстане Господь, як на горі Перацимі; розгнівається, як на долині Гаваонській, щоб зробити діло Своє, надзвичайне діло, і звершити дію Свою, дивну Свою дію.","Отже, не кощунствуйте, щоб кайдани ваші не стали міцнішими; бо я чув від Господа, Бога Саваофа, що знищення визначене для усієї землі.","Прихиліть вухо, і послухайте мого голосу; будьте уважні, і вислухайте промову мою.","Чи завжди хлібороб оре для посіву, борознить і боронить землю свою?","Ні; коли вирівняє поверхню її, він сіє чорнуху, або розсипає кмин, або розкидає пшеницю рядами, і ячмінь у визначеному місці, і просо поряд з ним.","І такого порядку вчить його Бог його; Він наставляє його.","Бо не молотять чорнуху котком зубцюватим, і коліс молотильних не катають по кмину; але палкою вибивають чорнуху, і кмин — палкою.","Зерновий хліб вимолочують, але не розбивають його; і водять по ньому молотильні колеса з конями їх, але не розтирають його.","І це походить від Господа Саваофа: дивні долі Його, велика премудрість Його!"],"x":{"2":"11.17.3","3":"37.7.7|43.7.10","4":"31.1.30","5":"26.4.9|31.62.3|36.16.12","7":"26.20.1|38.4.11|38.9.7","10":"31.42.20","11":"63.14.21","12":"50.11.28-29","13":"31.8.15","14":"54.13.40","15":"32.5.12|31.29.15","16":"25.117.22|31.8.14|50.21.42|51.12.10|52.20.17|54.4.11|56.2.7|62.9.33","18":"31.28.15|50.7.27","19":"50.6.13","21":"9.5.20|12.14.11|5.10.12","22":"31.10.23","23":"31.34.1","26":"29.3.5|35.3.37","27":"31.25.10","29":"31.55.8|32.32.19"}},{"v":["Горе Ариїлу, Ариїлу, місту, в якому жив Давид! прикладіть рік до року; нехай заколюють жертви.","Але Я стисну Ариїл, і буде плач і нарікання; і він залишиться у Мене, як Ариїл.","Я розташуюся станом навколо тебе і стисну тебе сторожею спостерігачів, і збудую проти тебе укріплення.","І будеш принижений, із землі будеш говорити, і глуха буде мова твоя з-під пороху, і голос твій буде, як голос утробомовця, і з-під пороху шепотіти буде голос твій.","Безліч ворогів буде у тебе, як дрібний пил, і полчище лютих, як пліва, що розлітається; і це звершиться раптово, в одну мить.","Господь Саваоф відвідає тебе громом і землетрусом, і сильним голосом, бурею і вихром, і полум’ям усепожерливого вогню.","І як сон, як нічне сновидіння, буде безліч усіх народів, які воюють проти Ариїла, й усіх, що виступили проти нього й укріплень його і тих, що стиснули його.","І як голодному сниться, ніби він їсть, але пробуджується, і душа його голодна; і як спраглому сниться, ніби він п’є, але пробуджується, і ось він знемагає, і душа його спрагла: те саме буде і з безліччю усіх народів, які воюють проти гори Сион.","Чудуйтеся і дивуйтеся: вони осліпили інших, і самі осліпли; вони п’яні, але не від вина, — хитаються, але не від сикери;","бо навів на вас Господь дух приспання і зімкнув очі ваші, пророки, і закрив ваші голови, прозорливці.","І всяке пророцтво для вас те саме, що слова в запечатаній книзі, яку подають тому, хто вміє читати книгу, і говорять: «прочитай її»; і той відповідає: «не можу, тому що вона запечатана».","І передають книгу тому, хто читати не вміє, і говорять: «прочитай її»; і той відповідає: «я не вмію читати».","І сказав Господь: оскільки цей народ наближається до Мене вустами своїми, і язиком своїм шанує Мене, серце ж його далеко відстоїть від Мене, і благоговіння їх переді Мною є вивчення заповідей людських;","то ось, Я ще незвичайно вчиню з цим народом, чудно і дивно, так що мудрість мудреців його загине, і розуму у розумних його не стане.","Горе тим, які думають сховатися у глибині, щоб намір свій приховати від Господа, які роблять діла свої у мороці й говорять: «хто побачить нас? і хто пізнає нас?»","Яка нерозсудливість! Хіба можна вважати гончара глиною? Чи скаже витвір про того, хто зробив його: «не він зробив мене»? і чи скаже твір про художника свого: «він не розуміє»?","Ще трохи, дуже трохи, і Ливан чи не перетвориться на сад, а сад чи не будуть вважати за ліс?","І у той день глухі почують слова книги, і прозріють із пітьми і мороку очі сліпих.","І стражденні більше і більше будуть радіти у Господі, і бідні люди будуть торжествувати за Святого Ізраїля,","бо не буде більше кривдника, і хульник зникне, і будуть знищені усі поборники неправди,","які заплутують людину у словах, і тому, хто вимагає суду, біля воріт розставляють сіті, і відштовхують правого.","Тому так говорить про дім Якова Господь, Який відкупив Авраама: тоді Яків не буде у соромі, і лице його більше не зблідне.","Бо коли побачить у себе дітей своїх, діла рук Моїх, то вони свято будуть шанувати ім’я Моє і свято шанувати Святого Яковового, і благоговіти перед Богом Ізраїлевим.","Тоді ті, що блукають духом, пізнають мудрість, і непокірливі навчаться послуху."],"x":{"1":"9.5.9","3":"32.6.3|36.17.17|52.19.43","4":"2.19.31|31.8.19","5":"25.34.5","6":"31.30.30","7":"31.30.30|25.72.20","10":"32.51.39|62.11.8","11":"31.8.16|36.20.49|37.12.4","12":"64.3.14","13":"50.15.8|51.7.6","14":"32.49.7|41.1.8|63.1.19","15":"30.23.24","16":"31.45.9|32.18.6","17":"31.32.15","18":"50.15.30|31.42.18|75.10.7","20":"76.19.17|43.2.1","21":"40.5.10","22":"0.11.31|0.48.16","23":"25.99.3|66.2.10|75.2.10"}},{"v":["Горе непокірливим синам, — говорить Господь, — які роблять наради, але без Мене, і укладають союзи, але не за духом Моїм, щоб додавати гріх до гріха:","не запитавши вуст Моїх, йдуть у Єгипет, щоб підкріпити себе силою фараона й укритися під тінню Єгипту.","Але сила фараона буде для вас соромом, і притулок під тінню Єгипту — нечестям;","тому що князі його* вже у Цоані, і посли його дійшли до Ханеса.","Усі вони будуть посоромлені через народ, який некорисний для них; не буде від нього ні допомоги, ні користи, але — стид і сором.","Тягарі на тваринах, які йдуть на південь, по землі гноблення й утисків, звідки виходять левиці і леви, аспиди і летючі змії; вони несуть на хребтах ослів багатства свої і на горбах верблюдів скарби свої до народу, який не принесе їм користи.","Бо допомога Єгипту буде марна і даремна; тому Я сказав їм: сила їх — сидіти спокійно.","Тепер піди, накресли це на дошці у них, і впиши це у книгу, щоб залишилося на майбутній час, назавжди, навіки.","Бо це народ непокірний, діти неправдиві, діти, які не хочуть слухати закону Господнього,","які провидцям говорять: «перестаньте провидіти», і пророкам: «не пророкуйте нам правди, говоріть нам утішне, пророкуйте приємне;","зійдіть з дороги, ухиліться від путі; усуньте від очей наших Святого Ізраїлевого».","Тому так говорить Святий Ізраїлів: оскільки ви відкидаєте слово це, а сподіваєтеся на обман і неправду, і спираєтеся на те:","то беззаконня це буде для вас, як тріщина, що загрожує падінням, виявлена у високій стіні, руйнування якої настане раптово, в одну мить.","І Він зруйнує її, як розтрощують глиняну посудину, розбиваючи її без пощади, так що в уламках її не знайдеться і черепка, щоб узяти вогню з вогнища або зачерпнути води з водойми;","бо так говорить Господь Бог, Святий Ізраїлів: залишаючись на місці й у спокої, ви спаслися б; у тиші й упованні міцність ваша; але ви не хотіли","і говорили: «ні, ми на конях утечемо», — за те і побіжите; «ми на швидких поскачемо», — за те і ті, що переслідують вас, будуть швидкі.","Від погрози одного побіжить тисяча, від погрози п’ятьох побіжите так, що залишок ваш буде як віха на вершині гори і як знамено на пагорбі.","І тому Господь бариться, щоб поми́лувати вас, і тому ще утримується, щоб пожаліти вас; бо Господь є Бог правди: блаженні всі, що уповають на Нього!","Народ буде жити на Сионі в Єрусалимі; ти не будеш багато плакати, — Він помилує тебе, за голосом волання твого, і як тільки почує його, відповість тобі.","І дасть вам Господь хліб у горі і воду в нужді; і вчителі твої уже не будуть ховатися, й очі твої будуть бачити вчителів твоїх;","і вуха твої будуть чути слово, що говорить позаду тебе: «ось шлях, ідіть ним», якби ви ухилилися праворуч і якби ви ухилилися ліворуч.","Тоді ви будете вважати скверною оклад ідолів зі срібла твого й оклад ідолів із золота твого; ти кинеш їх, як нечистоту; ти скажеш їм: геть звідси.","І Він дасть дощ на насіння твоє, яким засієш поле, і хліб, плід землі, і він буде рясний і соковитий; стада твої у той день будуть пастися на широких пасовищах.","І воли й осли, які обробляють поле, будуть їсти корм солоний, очищений лопатою і віялом.","І на всякій горі високій і на всякому пагорбі підвищеному потечуть струмки, потоки вод, у день великої поразки, коли упадуть вежі.","І світло місяця буде, як світло сонця, а світло сонця буде світлішим усемеро, як світло семи днів, у той день, коли Господь обв’яже рану народу Свого і зцілить нанесені йому виразки.","Ось, ім’я Господа йде здаля, горить гнів Його, і полум’я його сильне, вуста Його сповнені обурення, і язик Його, як вогонь, що поїдає,","і подих Його, як потік, що розлився, який піднімається навіть до шиї, щоб розвіяти народи до останку; і буде у щелепах народів вузда, яка направляє до омани.","А у вас будуть пісні, як у ніч священного свята, і веселість серця, як у того, хто йде із сопілкою на гору Господню, до твердині Ізраїлевої.","І загримить Господь величним гласом Своїм і явить тяжкий м’яз Свій у сильному гніві й у полум’ї вогню, що поїдає, у бурі й у повені й у кам’яному граді.","Бо від гласу Господа здригнеться Ассур, жезлом уражений.","І всякий рух визначеного йому жезла, який Господь направить на нього, буде з тимпанами і цитрами, і Він піде проти нього війною спустошливою.","Бо Тофет давно уже влаштований; він приготований і для царя, глибокий і широкий; у багатті його багато вогню і дров; подув Господа, як потік сірки, запалить його."],"x":{"1":"52.12.17","2":"11.18.21|32.2.18|32.37.7","3":"32.2.36","4":"31.19.13|32.2.16","5":"32.2.36","8":"31.8.1","9":"54.7.52","10":"40.2.12","11":"31.1.4","12":"25.61.11|31.47.10","13":"31.29.5","14":"25.2.9","15":"33.3.26","16":"38.14.4","17":"2.26.36","18":"52.1.54|62.2.4|26.16.20|32.17.7","19":"25.90.15|31.58.9","20":"25.79.6","21":"4.5.32|4.28.14|26.4.27","22":"2.15.19","23":"4.11.14","25":"31.2.15|31.41.18","26":"32.4.23|39.2.10|76.21.23","27":"36.22.21|1.24.17|4.4.24","28":"9.22.16|31.8.8","29":"25.41.5","30":"31.29.6|76.20.15","31":"25.28.4","33":"76.19.20|50.25.41"},"n":{"4":["Єрусалима."]}},{"v":["Горе тим, які йдуть у Єгипет по допомогу, сподіваються на коней і покладаються на колісниці, тому що їх багато, і на вершників, тому що вони дуже сильні, а на Святого Ізраїлевого не дивляться і до Господа не прибігають!","Але премудрий Він; і наведе біду, і не скасує слів Своїх; повстане проти дому нечестивих і проти допомоги тих, що чинять беззаконня.","І єгиптяни — люди, а не Бог; і коні їхні — плоть, а не дух. І простягне руку Свою Господь, і спіткнеться захисник, і упаде той, кого захищають, і усі разом загинуть.","Бо так сказав мені Господь: як лев, як скимен, який реве над своєю здобиччю, хоч би багато пастухів кричало на нього, від крику їхнього не здригнеться і безлічі їх не поступиться, — так Господь Саваоф зійде воювати за гору Сион і за пагорб його.","Як птахи — пташенят, так Господь Саваоф покриє Єрусалим, захистить і визволить, пощадить і спасе.","Наверніться до Того, від Якого вас стільки відпало, сини Ізраїля!","У той день відкине кожна людина своїх срібних ідолів і золотих своїх ідолів, яких руки ваші зробили вам на гріх.","І Ассур упаде не від людського меча, і не людський меч уразить його, — він уникне меча, і юнаки його будуть податтю.","І від страху пробіжить повз укріплення своє; і князі його будуть лякатися прапора, — говорить Господь, Якого вогонь на Сионі і горно в Єрусалимі."],"x":{"1":"31.30.1|32.2.36|38.8.13","2":"40.3.6|25.9.21","3":"32.17.5|36.28.9-10|33.4.17","4":"76.20.8","5":"4.32.11|50.23.37","6":"32.3.14","7":"31.2.20","8":"31.37.36","9":"14.1.3"}},{"v":["Ось, Цар буде царювати за правдою, і князі будуть правити за законом;","і кожен з них буде як захист від вітру і покрив від негоди, як джерела вод у степу, як тінь від високої скелі у землі спраглій.","І очі тих, що бачать, не будуть закриватися, і вуха тих, що чують, будуть слухати.","І серце легковажних буде вміти міркувати; і недорікуваті будуть говорити ясно.","Невігласа уже не будуть називати шановним, і про підступного не скажуть, що він чесний.","Бо невіглас говорить дурне, і серце його думає про беззаконне, щоб діяти лицемірно і промовляти хулу на Господа, душу голодного позбавляти хліба і віднімати питво у спраглих.","У підступного і дії згубні: він задумує підступи, щоб згубити бідного словами неправди, хоч би бідний був і правий.","А чесний і думає про чесне і твердо стоїть у всьому, що чесне.","Жінки недбалі! встаньте, послухайте голосу мого; дочки безтурботні! прихиліть слух до моїх слів.","Ще кілька днів понад рік, і жахнетеся, недбалі! бо не буде оббирання винограду, і час жнив не настане.","Здригніться, безтурботні! жахніться, недбалі! скиньте одяг, оголіться й опояшіть стегна.","Будуть бити себе у груди за прекрасні поля, за плідну виноградну лозу.","На землі народу мого будуть рости терни і бур’ян, також і на усіх домах веселощів у радісному місті;","бо палаци будуть залишені; гамірливе місто буде покинуте; Офел і вежа назавжди будуть служити, замість печер, притулком диких ослів і стад, що пасуться,","доки не виллється на нас Дух звище, і пустеля не зробиться садом, а сад не будуть вважати лісом.","Тоді суд установиться у цій пустелі, і правосуддя буде перебувати на плодоносному полі.","І справою правди буде мир, і плодом правосуддя — спокій і безпека навіки.","Тоді народ мій буде жити в оселях миру й у селищах безпечних, і у покоях блаженних.","І град буде падати на ліс, і місто спуститься у долину.","Блаженні ви, що сієте біля усіх вод і посилаєте туди вола й осла."],"x":{"1":"32.23.5|32.33.15|31.11.5","2":"25.142.6","4":"52.10.21","6":"8.24.14","7":"8.8.3|26.29.4|54.20.35","8":"52.6.45","10":"2.26.34","13":"31.34.13|38.9.6","14":"13.27.3","15":"31.29.17","16":"31.35.1","17":"62.5.1","18":"32.33.16|36.34.27","20":"25.71.16"}},{"v":["Горе тобі, спустошувач, який не був спустошуваним, і грабіжник, якого не грабували! Коли закінчиш спустошування, будеш спустошений і ти; коли припиниш грабунки, розграбують і тебе.","Господи! помилуй нас; на Тебе уповаємо ми; будь нашою силою з раннього ранку і спасінням нашим у час тисняви.","Від грізного гласу Твого побіжать народи; коли повстанеш, розсіються племена,","і будуть збирати здобич вашу, як збирає гусінь; кинуться на неї, як кидається сарана.","Високий Господь, Який живе у вишніх; Він наповнить Сион судом і правдою.","І настануть безпечні часи твої, повнота спасіння, мудрости і відання; страх Господній буде скарбом твоїм.","Ось, сильні їхні кричать на вулицях; посли для миру гірко плачуть.","Спорожніли дороги; не стало подорожніх; він порушив договір, зруйнував міста, — ні у що ставить людей.","Земля нарікає, сохне; Ливан посоромлений, зів’янув; Сарон схожий став на пустелю, й оголені від листя свого Васан і Кармил.","Нині Я повстану, — говорить Господь, — нині піднімуся, нині піднесуся.","Ви вагітні сіном, розродіться соломою; дихання ваше — вогонь, який пожере вас.","І будуть народи, як розпалене вапно, як зрубане терня, будуть спалені у вогні.","Слухайте, далекі, що зроблю Я; і ви, ближні, пізнайте могутність Мою.","Злякалися грішники на Сионі; тремтіння оволоділо нечестивими: «хто з нас може жити при вогні, що пожирає? хто з нас може жити при вічному полум’ї?»","Той, хто ходить у правді і говорить істину; хто нехтує користь від утиску, утримує руки свої від хабарів, затикає вуха свої, щоб не чути про кровопролиття, і закриває очі свої, щоб не бачити зла;","той буде жити на висотах; притулок його — неприступні скелі; хліб буде даний йому; вода у нього не висохне.","Очі твої побачать Царя у красі Його, побачать землю віддалену;","серце твоє буде тільки згадувати про жахи: «де той, хто робив перепис? де той, хто зважував данину? де той, хто оглядав вежі?»","Не побачиш більше народу лютого, народу з глухою, нерозбірливою мовою, з мовою дивною, незрозумілою.","Поглянь на Сион, місто святкових зібрань наших; очі твої побачать Єрусалим, житло мирне, непохитну скинію; стовпи її ніколи не викоріняться, і жоден шнур її не порветься.","Там у нас великий Господь буде замість рік, замість широких каналів; туди не ввійде жодне веслове судно, і не пройде великий корабель.","Бо Господь — суддя наш, Господь — законодавець наш, Господь — цар наш; Він спасе нас.","Ослабли мотузки твої, не можуть утримати щогли і натягнути вітрила. Тоді буде великий розподіл здобичі, так що і кульгаві підуть на грабунок.","І жоден з жителів не скаже: «я хворий»; народу, який живе там, будуть відпущені гріхи."],"x":{"1":"25.136.8|32.30.16|41.1.10","2":"25.16.7","3":"25.67.2|31.26.11","5":"31.9.7|31.11.4","6":"11.18.5|32.10.16","7":"13.36.15","8":"31.37.2","10":"25.101.14|31.33.3","11":"25.7.15|31.1.31|31.47.14","12":"31.9.18","13":"31.60.4|66.2.13","14":"54.5.11|4.5.24","15":"25.14.2","16":"45.3.19|25.17.3","17":"25.44.3|25.92.1|51.9.2","18":"63.1.20","19":"4.28.49|32.5.15|36.3.5","20":"50.16.18|25.124.1","22":"25.43.5|25.57.12|31.43.15|55.4.12","23":"31.35.6","24":"31.40.29|31.45.24|56.1.3"}},{"v":["Приступіть, народи, слухайте і прислуховуйтеся, племена! нехай чує земля і усе, що наповнює її, вселенна і усе, що народжується у ній!","Бо гнів Господа на усі народи, і лють Його на усе воїнство їх. Він піддав їх закляттю, віддав їх на заколення.","І вбиті їхні будуть розкидані, і від трупів їхніх підніметься сморід, і гори розмокнуть від крови їхньої.","І зотліє все небесне воїнство*; і небеса згорнуться, як сувій книжний; і усе воїнство їх упаде, як спадає лист з виноградної лози, і як зів’ялий лист — зі смоковниці.","Бо упився меч Мій на небесах: ось, для суду сходить він на Едом і на народ, підданий Мною закляттю.","Меч Господа наповниться кров’ю, утучниться від жиру, від крови агнців і козлів, від жиру з нирок баранів: бо жертва у Господа у Восорі і велике заколення в землі Едома.","І буйволи впадуть з ними, і тельці разом з волами, й уп’ється земля їх кров’ю, і прах їх наповниться жиром.","Бо день помсти у Господа, рік відплати за Сион.","І перетворяться ріки його на смолу, і прах його — на сірку, і буде земля його розпаленою смолою:","не буде гаснути ні вдень, ні вночі; вічно буде підніматися дим її; буде від роду у рід залишатися спустілою; повіки віків ніхто не пройде по ній;","і заволодіють нею пелікан і їжак; і пугач і ворон оселяться у ній; і протягнуть по ній шнур руйнування і висок знищення.","Нікого не залишиться там зі знатних її, кого можна було б покликати на царство, і усі князі її будуть ніщо.","І заростуть палаци її колючими рослинами, кропивою і реп’яхом — твердині її; і буде вона житлом шакалів, пристановищем страусів.","І звірі пустелі будуть зустрічатися з дикими кішками, і лісовики будуть перегукуватися один з одним; там буде відпочивати нічна примара і знаходити собі спокій.","Там угніздиться летючий змій, буде відкладати яйця і виводити дітей і збирати їх під тінь свою; там і шуліки будуть збиратися один до одного.","Відшукайте у книзі Господній і прочитайте; жодне з цих не промине прийти, і одне іншим не заміниться. Бо самі вуста Його повеліли, і сам дух Його збере їх.","І Сам Він кинув їм жереб, і Його рука розділила їм своєю мірою; повіки будуть вони володіти нею, з роду у рід будуть жити на ній."],"x":{"1":"31.28.23","2":"32.25.33","3":"36.39.17|76.19.18","4":"37.8.10|51.13.24|57.3.10|76.6.14","5":"32.46.10|31.63.1","6":"46.1.7","7":"25.21.22|40.4.1","8":"31.63.4","10":"31.66.24|50.5.26|51.9.44","11":"46.2.14|76.18.2","13":"31.32.13|38.9.6|32.9.11","14":"76.18.2","16":"4.28.15|5.21.45|36.12.24","17":"25.36.9"},"n":{"4":["Зірки."]}},{"v":["Звеселиться пустеля і суха земля, і зрадіє країна ненаселена і розцвіте як нарцис;","чудово буде цвісти і радіти, буде торжествувати і тріумфувати; слава Ливану дасться їй, пишнота Кармила і Сарона; вони побачать славу Господа, велич Бога нашого.","Укріпіть ослаблені руки й утвердіть коліна тремтячі;","скажіть боязким душею: будьте тверді, не бійтеся; ось Бог ваш, прийде помста, воздаяння Боже; Він прийде і спасе вас.","Тоді прозріють очі сліпих, і вуха глухих відкриються.","Тоді кульгавий скакатиме, як олень, і язик німого буде співати; бо проб’ються води у пустелі, і у степу — потоки.","І перетвориться примара вод на озеро, і спрагла земля — на джерела вод; у житло шакалів, де вони спочивають, буде місцем для тростини й очерету.","І буде там велика дорога, і путь по ній назветься шляхом святим: нечистий не буде ходити по ньому; але він буде для них одних; ті, що йдуть цим шляхом, навіть і недосвідчені, не заблукають.","Лева не буде там, і хижий звір не зійде на нього; його не знайдеться там, а будуть ходити відкуплені.","І повернуться визволені Господом, прийдуть на Сион з радісними вигуками; і радість вічна буде над головою їх; вони знайдуть радість і веселощі, а сум і зітхання відійдуть."],"x":{"1":"31.32.16","2":"10.4.33|53.1.14","3":"75.12.12","4":"52.1.70|31.40.1","5":"50.9.30|50.11.5|50.15.30|52.7.22|53.9.6-7","6":"53.5.8-9|53.7.38|54.3.8|50.9.32-33|50.21.14|31.41.18","8":"53.14.6","9":"56.5.8","10":"31.51.11|31.61.7|31.66.14"}},{"v":["І було у чотирнадцятий рік царя Єзекії, пішов Сеннахирим, цар Ассирійський, проти усіх укріплених міст Юдеї і узяв їх.","І послав цар Ассирійський з Лахиса в Єрусалим до царя Єзекії Рабсака з великим військом; і він зупинився біля водопроводу верхнього ставу на дорозі до поля білильного.","І вийшов до нього Елиаким, син Хелкіїн, начальник палацу, і Севна писар, й Іоах, син Асафів, дієописувач.","І сказав їм Рабсак: скажіть Єзекії: так говорить цар великий, цар Ассирійський: що це за уповання, на яке ти уповаєш?","Я думаю, що це одні пусті слова, а для війни потрібні рада і сила: отже, на кого ти уповаєш, що відійшов від мене?","Ось, ти думаєш спертися на Єгипет, на цю тростину надламану, яка, якщо хто зіпреться на неї, ввійде тому у руку і проколе її! Такий фараон, цар Єгипетський, для усіх, хто надіється на нього.","А якщо скажеш мені: «на Господа, Бога нашого ми уповаємо», то чи на того, якого висоти і жертовники відмінив Єзекія і сказав Іуді та Єрусалиму: «перед цим тільки жертовником поклоняйтеся»?","Отже, вступи у союз з господарем моїм, царем Ассирійським; я дам тобі дві тисячі коней; чи можеш дістати собі вершників на них?","І як ти хочеш примусити відступити вождя, одного з найменших рабів господаря мого, сподіваючись на Єгипет, заради колісниць і коней?","Та хіба я без волі Господньої пішов на землю цю, щоб розорити її? Господь сказав мені: піди на землю цю і розори її.","І сказав Елиаким і Севна та Іоах Рабсаку: говори рабам твоїм по-арамейськи, бо ми розуміємо, а не говори з нами по-юдейськи, уголос при народі, який на стіні.","І сказав Рабсак: хіба тільки до господаря твого і до тебе послав мене господар мій сказати слова ці? Ні, також і до людей, які сидять на стіні, щоб їсти кал свій і пити сечу свою з вами.","І встав Рабсак, і виголосив гучним голосом по-юдейськи, і сказав: слухайте слово царя великого, царя Ассирійського!","Так говорить цар: нехай не зваблює вас Єзекія, тому що він не може врятувати вас;","і нехай не подає вам Єзекія надію на Господа, говорячи: «спасе нас Господь; не буде місто це віддане у руки царя Ассирійського».","Не слухайте Єзекію, бо так говорить цар Ассирійський: примиріться зі мною і вийдіть до мене, і нехай кожен їсть плоди виноградної лози своєї і смоковниці своєї, і нехай кожен п’є воду зі свого колодязя,","доки я не прийду і не візьму вас у землю таку ж, як і ваша земля, у землю хліба і вина, в землю плодів і виноградників.","Отже, нехай не зваблює вас Єзекія, говорячи: «Господь спасе нас». Чи врятували боги народів, кожен свою землю, від руки царя Ассирійського?","Де боги Емафа й Арпада? Де боги Сепарваїма? Чи врятували вони Самарію від руки моєї?","Який з усіх богів земель цих урятував землю свою від руки моєї? Так невже спасе Господь Єрусалим від руки моєї?","Але вони мовчали і не відповідали йому жодного слова, бо від царя даний був наказ: не відповідайте йому.","І прийшов Елиаким, син Хелкіїн, начальник палацу, і Севна писар, й Іоах, син Асафів, дієописувач, до Єзекії у розідраному одязі і переказали йому слова Рабсака."],"x":{"1":"11.18.13|13.32.1|30.48.20","2":"31.7.3","5":"11.18.7","6":"36.29.6-7","9":"11.18.24","10":"13.35.21","11":"13.32.18","14":"11.18.29","16":"11.18.31","18":"11.18.33|31.10.9|31.37.12","19":"3.13.22|11.17.31","21":"11.18.36"}},{"v":["Коли почув це цар Єзекія, те роздер одяг свій і покрився веретищем, і пішов у дім Господній;","і послав Елиакима, начальника палацу, і Севну писаря, і старших священиків, покритих веретищами, до пророка Ісаї, сина Амосового.","І вони сказали йому: так говорить Єзекія: день скорботи і покарання і посоромлення день цей, бо немовлята дійшли до отвору утроби материнської, а сили немає родити.","Можливо, почує Господь Бог твій слова Рабсака, якого послав цар Ассирійський, господар його, хулити Бога живого і ганьбити словами, які чув Господь, Бог твій; піднеси ж молитву про тих, що залишилися, які перебувають ще у живих.","І прийшли слуги царя Єзекії до Ісаї.","І сказав їм Ісая: так скажіть господарю вашому: так говорить Господь: не бійся слів, які чув ти, якими ганьбили Мене слуги царя Ассирійського.","Ось, Я пошлю на нього дух, і він почує звістку, і повернеться у землю свою, і Я вражу його мечем у землі його.","І повернувся Рабсак і знайшов царя Ассирійського, що воював проти Ливни; бо він чув, що той відійшов від Лахиса.","І почув він про Тиргака, царя Ефіопського; йому сказали: ось, він вийшов воювати з тобою. Почувши це, він послав послів до Єзекії, сказавши:","так скажіть Єзекії, царю Юдейському: нехай не обманює тебе Бог твій, на Якого ти уповаєш, думаючи: «не буде відданий Єрусалим до рук царя Ассирійського».","Ось, ти чув, що зробили царі ассирійські з усіма землями, поклавши на них закляття; чи ти вцілієш?","Боги народів, яких розорили батьки мої, чи спасли їх, чи спасли Гозан і Харан, і Рецеф, і синів Едена, що у Фалассарі?","Де цар Емафа і цар Арпада, і цар міста Сепарваїма, Ени та Івви?","І узяв Єзекія лист із руки послів і прочитав його, і пішов у дім Господній, і розгорнув його Єзекія перед лицем Господнім;","і молився Єзекія перед лицем Господнім і говорив:","Господи Саваофе, Боже Ізраїлів, що сидиш на херувимах! Ти один Бог усіх царств землі; Ти створив небо і землю.","Прихили, Господи, вухо Твоє і почуй; відкрий, Господи, очі Твої і подивись, і почуй слова Сеннахирима, який послав ганьбити Тебе, Бога живого.","Правда, о, Господи! царі ассирійські спустошили усі країни і землі їх","і покидали богів їх у вогонь; але це були не боги, а витвори рук людських, дерево і камінь, тому і знищили їх.","І нині, Господи Боже наш, спаси нас від руки його; і дізнаються усі царства землі, що Ти, Господи, Бог один.","І послав Ісая, син Амосів, до Єзекії сказати: так говорить Господь, Бог Ізраїлів: про що ти молився Мені проти Сеннахирима, царя Ассирійського, —","ось слово, яке Господь прорік про нього: знехтує тебе, посміється з тебе дівствена дочка Сиону, похитає вслід тобі головою дочка Єрусалима.","Кого ти хулив і ганьбив? і на кого підняв голос і підніс так високо очі твої? на Святого Ізраїлевого.","Через рабів твоїх ти хулив Господа і сказав: «з безліччю колісниць моїх я зійшов на висоту гір, на ребра Ливану, і зрубав високі кедри його, відмінні кипариси його, і прийшов на саму вершину його, у гай саду його;","і відкопував я, і пив воду; й осушу ступнями ніг моїх усі ріки єгипетські».","Хіба не чув ти, що Я здавна зробив це, у давні дні наперед накреслив це, а нині виконав тим, що ти спустошуєш міцні міста, перетворюючи їх на купи руїн?","І жителі їх зробилися слабкосилі, тремтять і залишаються в соромі; вони стали як трава на полі і ніжна зелень, як проріст на покрівлях і обпалений хліб, перше ніж виколосився.","Чи сядеш ти, чи вийдеш, чи ввійдеш, Я знаю все, знаю і зухвалість твою проти Мене.","За твою зухвалість проти Мене і за те, що пихатість твоя дійшла до вух Моїх, Я вкладу кільце Моє у ніздрі твої і вудила Мої в рот твій, і поверну тебе назад тією ж дорогою, якою ти прийшов.","І ось, тобі, Єзекіє, знамення: їжте у цей рік те, що виросло від упалого зерна, і на другий рік — самородне; а на третій рік сійте і жніть, і садіть виноградні сади, і їжте плоди їх.","І уцілілий у домі Іуди залишок пустить знову корінь унизу і принесе плід угорі,","бо з Єрусалима вийде залишок, і спасіння — від гори Сиону. Ревність Господа Саваофа зробить це.","Тому так говорить Господь про царя Ассирійського: «не увійде він у це місто і не кине туди стріли́, і не приступить до нього зі щитом, і не насипле проти нього валу.","Тією ж дорогою, якою прийшов, повернеться, а у місто це не ввійде, — говорить Господь.","Я буду охороняти місто це, щоб спасти його заради Себе і заради Давида, раба Мого».","І вийшов ангел Господній і вразив у стані ассирійському сто вісімдесят п’ять тисяч чоловік. І встали вранці, і ось, усі тіла мертві.","І відступив, і пішов, і повернувся Сеннахирим, цар Ассирійський, і жив у Ниневії.","І коли він поклонявся у домі Нисроха, бога свого, Адрамелех і Шарецер, сини його, убили його мечем, а самі втекли у землю Араратську. І став царем Асардан, син його, замість нього."],"x":{"1":"11.19.1","3":"11.19.3|38.13.13","9":"11.19.9","13":"31.36.19","14":"11.19.14","16":"25.79.2|31.42.5|54.4.24","20":"13.20.12","21":"11.19.20","24":"32.22.27","25":"11.19.24","27":"25.36.2|25.128.6","28":"32.48.30","31":"36.12.16|40.2.9","32":"11.19.31|31.9.7","33":"11.19.32","35":"11.20.6","36":"11.19.35|30.48.24|31.10.12|21.7.41|22.8.19|13.32.21","38":"18.1.21"}},{"v":["У ті дні Єзекія занедужав смертельно. І прийшов до нього пророк Ісая, син Амосів, і сказав йому: так говорить Господь: зроби заповіт для дому твого, бо ти помреш, не видужаєш.","Тоді Єзекія відвернувся лицем до стіни і молився Господу, говорячи:","«о, Господи! пом’яни, що я ходив перед лицем Твоїм вірно і з відданим Тобі серцем і робив угодне в очах Твоїх». І заплакав Єзекія сильно.","І було слово Господнє до Ісаї, і сказано:","піди і скажи Єзекії: так говорить Господь, Бог Давида, батька твого: Я почув молитву твою, побачив сльози твої, і ось, Я додам до днів твоїх п’ятнадцять років,","і від руки царя Ассирійського спасу тебе і місто це і захищу місто це.","І ось тобі знамення від Господа, що Господь виконає слово, яке Він прорік.","Ось, я поверну назад на десять ступенів сонячну тінь, яка пройшла по ступенях Ахазових. І повернулося сонце на десять ступенів по ступенях, по яких воно сходило.","Молитва Єзекії, царя Юдейського, коли він хворий був і видужав від хвороби:","«Я сказав у собі: у переполовення днів моїх повинен я іти у врата пекла; я позбавлений залишку років моїх.","Я говорив: не побачу я Господа, Господа на землі живих; не побачу більше людини між тими, що живуть у мирі;","оселя моя знімається з місця і несеться від мене, як курінь пастуший; я повинен відрізати подібно до ткача життя моє; Він відріже мене від основи; день і ніч я чекав, що Ти пошлеш мені кончину.","Я чекав до ранку; подібно до лева, Він скрушав усі кістки мої; день і ніч я чекав, що Ти пошлеш мені кончину.","Як журавель, як ластівка видавав я звуки, тужив як голуб; сумно дивилися очі мої до неба: Господи! тяжко мені; спаси мене.","Що скажу я? Він сказав мені, Він і зробив. Тихо буду проводити усі роки життя мого, пам’ятаючи гіркоту душі моєї.","Господи! так живуть, і в усьому цьому життя мого духу; Ти зцілиш мене, даруєш мені життя.","Ось, на благо мені була сильна гіркота, і Ти визволив душу мою від рову погибелі, кинув усі гріхи мої за хребет Свій.","Бо не пекло славить Тебе, не смерть вихваляє Тебе, не ті, що зійшли у могилу, уповають на істину Твою.","Живий, тільки живий прославить Тебе, як я нині: батько сповістить дітям істину Твою.","Господь спасе мене; і ми в усі дні життя нашого зі звуками струн моїх будемо співати пісні у домі Господньому».","І сказав Ісая: нехай принесуть пласт смокв і обкладуть ним нарив; і він стане здоровим.","А Єзекія сказав: яке знамення, що я буду ходити у дім Господній?"],"x":{"1":"11.20.1|13.32.24","2":"30.38.9","3":"50.5.48","5":"11.20.5|75.11.34","8":"30.48.26","12":"57.1.13|24.30.22","13":"24.4.21","17":"53.3.16|36.18.22","18":"25.6.6|25.113.25|35.2.17","19":"11.20.18","20":"25.26.6","22":"31.38.8"}},{"v":["У той час Меродах Валадан, син Валадана, цар Вавилонський, надіслав Єзекії лист і дари, бо чув, що він був хворий і одужав.","І зрадів посланим Єзекія, і показав їм дім скарбів своїх, срібло і золото, й аромати, і дорогоцінні масті, весь збройовий свій дім і усе, що знаходилося у скарбницях його; нічого не залишилося, чого не показав би їм Єзекія у домі своєму і в усьому володінні своєму.","І прийшов пророк Ісая до царя Єзекії і сказав йому: що говорили ці люди? і звідки вони приходили до тебе? Єзекія сказав: з далекої землі приходили вони до мене, з Вавилона.","І сказав Ісая: що бачили вони у домі твоєму? Єзекія сказав: бачили все, що є у домі моєму; нічого не залишилося у скарбницях моїх, чого я не показав би їм.","І сказав Ісая Єзекії: вислухай слово Господа Саваофа:","ось, прийдуть дні, і все, що є у домі твоєму і що зібрали батьки твої до цього дня, буде віднесене у Вавилон; нічого не залишиться, — говорить Господь.","І візьмуть із синів твоїх, які народяться від тебе, яких ти народиш, — і вони будуть євнухами у палаці царя Вавилонського.","І сказав Єзекія Ісаї: благе слово Господнє, яке ти прорік; тому що, — додав він, — мир і добробут будуть у дні мої."],"x":{"1":"11.20.12","2":"13.32.25","7":"37.1.3-4","8":"11.20.19"}},{"v":["Утішайте, утішайте народ Мій, — говорить Бог ваш;","говоріть до серця Єрусалима і сповіщайте йому, що сповнився час боротьби його, що за неправди його зроблено відкуплення, тому що він від руки Господньої прийняв удвічі за усі гріхи свої.","Голос волаючого в пустелі: приготуйте путь Господу, прямими зробіть у степу стежки Богу нашому;","усякий діл нехай наповниться, і усяка гора і пагорб нехай понизяться, кривизни випрямляться і нерівні путі зробляться гладенькими;","і явиться слава Господня, і побачить усяка плоть [спасіння Боже]; бо вуста Господні вирекли це.","Голос говорить: звіщай! І сказав: що мені звіщати? Усяка плоть — трава, і уся краса її — як цвіт польовий.","Засихає трава, в’яне цвіт, коли дуне на нього подув Господа: так і народ — трава.","Трава засихає, цвіт в’яне, а слово Бога нашого перебуватиме вічно.","Зійди на високу гору, Сионе, що благовістиш! піднеси сильно голос твій, Єрусалиме, що благовістиш! піднеси, не бійся; скажи містам Іудиним: ось Бог ваш!","Ось, Господь Бог гряде із силою, і сила Його з владою. Ось, нагорода Його з Ним і воздаяння Його перед лицем Його.","Як пастир Він буде пасти стадо Своє; агнців буде брати на руки і носити на грудях Своїх, і водити дійних.","Хто вичерпав во́ди жменею своєю і п’яддю виміряв небеса, і вмістив у міру порох землі, і зважив на терезах гори і на чашах вагових пагорби?","Хто зрозумів дух Господа, і був радником у Нього й учив Його?","З ким радиться Він, і хто напоумляє Його і наставляє Його на путь правди, і вчить Його знання, і вказує Йому путь мудрости?","Ось народи — як крапля з відра, і вважаються як порошинка на терезах. Ось, острови як порошинку піднімає Він.","І Ливану недостатньо для жертовного вогню, і тварин на ньому — для всепалення.","Усі народи перед Ним як ніщо, — менше за нікчемність і порожнечу вважаються у Нього.","Отже, кому уподібните ви Бога? І яку подобу знайдете Йому?","Ідола відливає художник, і золотильник покриває його золотом і прилаштовує срібні ланцюжки.","А хто бідний для такого приношення, вибирає дерево, що не гниє, знаходить собі майстерного художника, щоб зробити ідола, який стояв би твердо.","Хіба не знаєте? хіба ви не чули? хіба вам не говорено було від початку? хіба ви не зрозуміли із основ землі?","Він є Той, Який сидить над колом землі, і ті, що живуть на ній, — як сарана перед Ним; Він розпростер небеса, як тонку тканину, і розкинув їх, як намет для житла.","Він обертає князів на ніщо, робить чимось пустим суддів землі.","Ледь вони посаджені, ледь посіяні, ледь укорінився у землі стовбур їх, і як тільки Він дихнув на них, вони засохли, і вихор розніс їх, як солому.","До кого ж ви уподібните Мене і з ким порівняєте? — говорить Святий.","Зведіть очі ваші на висоту небес і подивіться, хто створив їх? Хто виводить воїнство їх за переліком? Він усіх їх називає на ім’я: через безліч могутности і велику силу у Нього ніщо не вибуває.","Як же говориш ти, Якове, і вимовляєш, Ізраїлю: «путь мій прихований від Господа, і діла мої забуті у Бога мого»?","Хіба ти не знаєш? хіба ти не чув, що вічний Господь Бог, Який створив краї землі, не стомлюється і не знемагає? розум Його недослідимий.","Він дає стомленому силу, і знеможеному дарує міцність.","Стомлюються і юнаки і слабшають, і молоді люди падають,","а ті, що надіються на Господа, оновляться у силі: піднімуть крила, як орли, потечуть — і не втомляться, підуть — і не зморяться."],"x":{"1":"31.35.4|31.52.9|52.2.10","2":"32.16.18","3":"50.3.3|51.1.3|52.3.4|53.1.23","4":"52.18.14|31.42.16","5":"54.11.14","6":"24.14.2|25.102.15|30.14.18|55.1.10|56.1.24","8":"25.118.89|50.24.35|56.1.25","10":"53.1.27|31.62.11","11":"36.34.23|53.10.11","12":"31.48.13","13":"29.9.13|30.1.6|62.11.34|63.2.14:16","15":"25.102.14|37.4.32|30.7.31","17":"25.38.6","18":"54.17.29","19":"31.44.12|29.13.11|29.15.9","22":"32.10.12","23":"24.12.21","25":"31.40.18","26":"25.146.4","27":"24.34.5:12","28":"31.42.5|31.45.11","29":"31.33.24|64.12.9|68.1.11","31":"24.29.20|31.41.1"}},{"v":["Замовкніть переді Мною, острови, і народи нехай оновлять свої сили; нехай вони наблизяться і скажуть: «станьмо разом на суд».","Хто воздвиг від сходу мужа правди, закликав його йти за собою, віддав йому народи і підкорив царів? Він обернув їх мечем своїм на порох, луком своїм на солому, яку розносить вітром.","Він жене їх, іде спокійно дорогою, якою ніколи не ходив ногами своїми.","Хто зробив і звершив це? Той, Хто від початку викликає пологи; Я — Господь перший, і в останніх — Я той самий.","Побачили острови і жахнулися, краї землі затріпотіли. Вони зблизилися і зійшлися;","кожен допомагає своєму товаришеві і говорить своєму братові: «кріпися!»","Коваль підбадьорює плавильника, той, який розгладжує листи молотом, — того, хто кує на ковадлі, говорячи про спайку: «гарна»; і зміцнює цвяхами, щоб було твердо.","А ти, Ізраїль, раб Мій, Яків, якого Я обрав, сíм’я Авраама, друга Мого, —","ти, якого Я взяв від країв землі і покликав від кінців її, і сказав тобі: «ти Мій раб, Я обрав тебе і не відкину тебе»:","не бійся, бо Я з тобою; не знічуйся, бо Я Бог твій; Я зміцню тебе, і допоможу тобі, і підтримаю тебе правицею правди Моєї.","Ось, у соромі й посоромленні залишаться всі, роздратовані проти тебе; будуть як ніщо і загинуть ті, що сперечаються з тобою.","Будеш шукати їх, і не знайдеш їх, які ворогують проти тебе; ті, що борються з тобою, будуть як ніщо, зовсім ніщо;","бо Я Господь, Бог твій; тримаю тебе за праву руку твою, говорю тобі: «не бійся, Я допомагаю тобі».","Не бійся, черв’як Яків, малолюдний Ізраїль, — Я допомагаю тобі, говорить Господь і Відкупитель твій, Святий Ізраїлів.","Ось, Я зробив тебе гострим молотилом, новим, зубцюватим; ти будеш молотити і розтирати гори, і пагорби зробиш, як полову.","Ти будеш віяти їх, і вітер рознесе їх, і вихор розвіє їх; а ти зрадієш у Господі, будеш хвалитися Святим Ізраїлевим.","Бідні й убогі шукають води, і немає її; язик їх сохне від спраги: Я, Господь, почую їх, Я, Бог Ізраїлів, не залишу їх.","Відкрию на горах ріки і серед долин джерела; пустелю зроблю озером і суху землю — джерелами води;","посаджу в пустелі кедр, ситим і мирту й оливу; насаджу в степу кипарис, явір і бук разом,","щоб побачили і пізнали, і розглянули й зрозуміли, що рука Господня зробила це, і Святий Ізраїлів створив це.","Подайте справу вашу, — говорить Господь; наведіть ваші докази, говорить Цар Якова.","Нехай вони подадуть і скажуть нам, що відбудеться; нехай сповістять що-небудь раніше, ніж воно відбулося, і ми вникнемо розумом своїм і дізнаємось, як воно закінчилося, або нехай наперед сповістять нам про майбутнє.","Скажіть, що відбудеться у майбутньому, і ми будемо знати, що ви боги, або зробіть що-небудь, чи добре, чи лихе, щоб ми здивувалися і разом з вами побачили.","Але ви ніщо, і діло ваше ніщо; мерзота той, хто обирає вас.","Я воздвиг його від півночі, і він прийде; від сходу сонця буде прикликати ім’я Моє і топтати владик, як бруд, і топтати, як гончар глину.","Хто звістив про це спочатку, щоб нам знати, і задовго перед тим, щоб нам можна було сказати: «правда»? Але ніхто не сказав, ніхто не сповістив, ніхто не чув слів ваших.","Я перший сказав Сиону: «ось воно!» і дав Єрусалиму благовісника.","Отже, Я дивився, і не було нікого, і між ними не знайшлося радника, щоб Я міг запитати їх, і вони дали відповідь.","Ось, усі вони ніщо, нікчемні й діла їх; вітер і порожнеча ідоли їх."],"x":{"1":"31.1.18|31.40.31|32.2.35","2":"54.7.4","4":"31.43.10|76.1.17|76.22.13","7":"32.10.4","8":"4.7.8|25.134.4|31.44.1|52.1.54|55.2.23","10":"0.15.1|31.43.1","11":"1.23.22|32.30.16|48.12.3","13":"25.72.23","14":"52.12.32","15":"43.4.13","16":"38.4.19","18":"31.30.25|25.106.35","19":"31.55.13","20":"31.44.7","23":"32.10.5","27":"50.23.34","29":"25.95.5|32.10.3"}},{"v":["Ось, Отрок Мій, Якого Я тримаю за руку, обраний Мій, до якого благоволить душа Моя. Покладу дух Мій на Нього, і сповістить народам суд;","не заволає і не підвищить голосу Свого, і не дасть почути його на вулицях;","тростини надламаної не переломить, і льону, що димить, не загасить; буде чинити суд за істиною;","не ослабне і не знеможе, доки на землі не утвердить суд, і на закон Його будуть уповати острови*.","Так говорить Господь Бог, Який створив небеса і простір їх, розпростер землю з плодами її, Який дає дихання народу на ній і дух тим, що ходять по ній.","Я, Господь, прикликав Тебе у правду, і буду тримати Тебе за руку й оберігати Тебе, і поставлю Тебе у завіт для народу, у світло для язичників,","щоб відкрити очі сліпих, щоб в’язнів вивести з ув’язнення і тих, хто сидить у пітьмі, — з темниць.","Я Господь, це — Моє ім’я, і не дам слави Моєї іншому і хвали Моєї ідолам.","Ось, передвіщене раніше збулося, і нове Я звіщу; перш ніж воно відбудеться, Я звіщу вам.","Співайте Господу нову пісню, хвалу Йому від країв землі, ви, що плаваєте по морю, і все, що наповнює його, острови і ті, що живуть на них.","Нехай піднесе голос пустеля і міста її, селища, де живе Кидар; нехай торжествують ті, що живуть на скелях, нехай виголошують з вершин гір.","Нехай воздадуть Господу славу, і хвалу Його нехай звістять на островах.","Господь вийде, як велетень, як муж битв пробудить ревність; закличе і підніме воїнський крик, і покаже Себе сильним проти ворогів Своїх.","Довго мовчав Я, терпів, стримувався; тепер буду кричати, як та, що народжує, буду руйнувати і поглинати усе;","спустошу гори і пагорби, і всю траву їх висушу; і ріки зроблю островами, й осушу озера;","і поведу сліпих дорогою, якої вони не знають, невідомими шляхами буду вести їх; морок зроблю світлом перед ними, і криві шляхи — прямими: ось що Я зроблю для них і не залишу їх.","Тоді повернуться назад і великим соромом покриються ті, що надіються на ідолів, які говорять бовванам: «ви наші боги».","Слухайте, глухі, й дивіться, сліпі, щоб бачити.","Хто такий сліпий, як раб Мій, і глухий, як вісник Мій, Мною посланий? Хто такий сліпий, як закоханий, такий сліпий, як раб Господа?","Ти бачив багато чого, але не помічав; вуха були відкриті, але не чув.","Господу вгодно було, заради правди Своєї, звеличити і прославити закон.","Але це народ розорений і пограбований; усі вони зв’язані у підземеллях і сховані у в’язницях; зробилися здобиччю, і немає визволителя; пограбовані, і ніхто не говорить: «віддай назад!»","Хто з вас прихилив до цього вухо, вник і вислухав це для майбутнього?","Хто зрадив Якова на руйнування й Ізраїля грабіжникам? чи не Господь, проти Якого ми грішили? Не хотіли вони ходити путями Його і не слухали закону Його.","І Він вилив на них лють гніву Свого і лютість війни: вона оточила їх полум’ям з усіх боків, але вони не помічали; і горіла у них, але вони не зрозуміли цього серцем."],"x":{"1":"50.12.18","3":"53.20.27|31.43.17","5":"31.37.16","6":"31.49.6|54.13.47","7":"31.61.1|52.4.18","8":"31.48.11","10":"76.5.9","13":"31.59.1","14":"31.57.11|31.62.1|31.65.6","16":"31.35.5","17":"25.96.7","18":"31.29.18|36.12.2","19":"50.15.14","20":"36.33.31","21":"48.8.8","25":"32.21.14"},"n":{"4":["За перекладом 70-ти: на ім’я Його будуть уповати народи."]}},{"v":["Нині ж так говорить Господь, Який створив тебе, Якове, і Який упорядкував тебе, Ізраїлю, не бійся, тому що Я відкупив тебе, назвав тебе на ім’я твоє; ти Мій.","Чи будеш переходити через води, Я з тобою, — чи через ріки, вони не потоплять тебе; чи підеш через вогонь, не обпалишся, і полум’я не обпече тебе.","Бо Я Господь, Бог твій, Святий Ізраїлів, Спаситель твій; у викуп за тебе віддав Єгипет, Ефіопію і Савею за тебе.","Оскільки ти дорогий в очах Моїх, коштовний, і Я полюбив тебе, то віддам інших людей за тебе, і народи за душу твою.","Не бійся, бо Я з тобою; від сходу приведу плем’я твоє і від заходу зберу тебе.","Півночі скажу: «віддай»; і півдню: «не утримуй; веди синів Моїх здалеку і дочок Моїх від країв землі,","кожного, хто називається Моїм ім’ям, кого Я створив для слави Моєї, утворив і впорядкував.","Виведи народ сліпий, хоч у нього є очі, і глухий, хоч у нього є вуха».","Нехай усі народи зберуться разом, і з’єднаються племена. Хто між ними передбачив це? нехай звістять, що було від початку; нехай представлять свідків від себе і виправдаються, щоб можна було почути і сказати: «правда!»","А Мої свідки, говорить Господь, ви і раб Мій, якого Я обрав, щоб ви знали і вірили Мені, і розуміли, що це Я: раніше Мене не було Бога і після Мене не буде.","Я, Я Господь, і немає Спасителя, крім Мене.","Я передрік і спас і сповістив; а іншого немає у вас, і ви — свідки Мої, говорить Господь, що Я Бог;","від початку днів Я Той самий, і ніхто не спасе від руки Моєї; Я зроблю, і хто скасує це?","Так говорить Господь, Відкупитель ваш, Святий Ізраїлів: заради вас Я послав у Вавилон і скрушив усі запори і халдеїв, які величалися кораблями.","Я Господь, Святий ваш, Творець Ізраїля, Цар ваш.","Так говорить Господь, Який відкрив у море дорогу, у великих водах шлях,","Хто вивів колісниці і коней, військо і силу; усі лягли разом, не встали; потухли як світильня, згасли.","Але ви не згадуєте минулого і про давнє не помишляєте.","Ось, Я творю нове; нині ж воно явиться; невже ви і цього не хочете знати? Я прокладу дорогу в степу, ріки у пустелі.","Польові звірі прославлять Мене, шакали і страуси, тому що Я у пустелях дам воду, ріки у сухому степу, щоб напувати обраний народ Мій.","Цей народ Я утворив для Себе; він буде звіщати славу Мою.","А ти, Якове, не волав до Мене; ти, Ізраїлю, не трудився для Мене.","Ти не приносив Мені агнців твоїх у всепалення і жертвами твоїми не шанував Мене. Я не змушував тебе служити Мені хлібним приношенням і не обтяжував тебе фіміамом.","Ти не купував Мені запашної трави за срібло і жиром жертв твоїх не насичував Мене; але ти гріхами твоїми утруднював Мене, беззаконнями твоїми обтяжував Мене.","Я, Я Сам згладжую злочини твої заради Себе Самого і гріхів твоїх не пом’яну:","пригадай Мені; станемо судитися; говори ти, щоб виправдатися.","Праотець твій згрішив, і заступники твої відступили від Мене.","За те Я предстоятелей святилища позбавив священства і Якова віддав на закляття й Ізраїля на ганьбу."],"x":{"1":"31.41.8","2":"25.68.2|25.90.15|50.8.26","4":"49.1.2","5":"50.8.11|48.8.7","7":"4.28.10|32.14.8|66.1.12","8":"31.42.18|52.1.79","9":"31.42.9","10":"31.41.4","11":"38.13.4","13":"24.9.12|31.14.27","15":"31.33.22|31.49.7|38.3.5","16":"1.14.22","18":"31.65.17","19":"64.5.17|76.21.5","22":"53.15.16|58.4.10","24":"31.53.12|52.24.27","25":"31.44.22"}},{"v":["А нині слухай, Якове, рабе Мій, і Ізраїлю, якого Я обрав.","Так говорить Господь, Який створив тебе й утворив тебе, Який допомагає тобі від утроби матері: не бійся, рабе Мій, Якове, й улюблений [Ізраїлю], якого Я обрав;","бо Я виллю во́ди на спрагле і потоки на висохле; виллю дух Мій на плем’я твоє і благословення Моє на нащадків твоїх.","І будуть рости між травою, як і ви при потоках вод.","Один скаже: «я Господній», інший назветься ім’ям Якова; а ще інший напише рукою своєю: «я Господній», і прозветься ім’ям Ізраїля.","Так говорить Господь, Цар Ізраїля, і Відкупитель його, Господь Саваоф: Я перший і Я останній, і, крім Мене, немає Бога,","бо хто як Я? Нехай він розповість, сповістить і в порядку представить Мені усе з того часу, коли Я утворив народ древній, або нехай звістять про те, що настає, і про майбутнє.","Не бійтеся і не страшіться: чи не здавна Я звістив тобі і пророкував? І ви Мої свідки. Чи є Бог, крім Мене? немає іншої твердині, ніякої не знаю.","Ті, що роблять ідолів, усі нікчемні, і найжаданіші їхні не приносять ніякої користи, і вони самі собі свідки у тім. Вони не бачать і не розуміють, і тому будуть посоромлені.","Хто зробив бога і відлив ідола, який не приносить ніякої користи?","Усі, хто бере участь у цьому, будуть посоромлені, бо і художники самі з людей же; нехай усі вони зберуться і стануть; вони злякаються, й усі будуть посоромлені.","Коваль робить із заліза сокиру і працює на вугіллі, молотами обробляє її і трудиться над нею сильною рукою своєю до того, що стає голодний і безсилий, не п’є води і знемагає.","Тесля [вибравши дерево], накреслює на ньому лінію, гострим знаряддям робить на ньому обрис, потім оброблює його різцем і округлює його, і витворює з нього образ людини, красивої на вигляд, щоб поставити його у домі.","Він рубає собі кедри, бере сосну і дуб, які вибере між деревами в лісі, саджає ясен, а дощ вирощує його.","І це служить людині паливом, і частину з цього вживає вона на те, щоб їй було тепло, і розводить вогонь, і пече хліб. І з того самого робить бога, і поклоняється йому, робить ідола, і падає перед ним.","Частину дерева спалює у вогні, іншою частиною варить м’ясо для їжі, смажить печеню і їсть досита, а також гріється і говорить: «добре, я зігрівся; відчув вогонь».","А з залишків від того робить бога, ідола свого, поклоняється йому, падає перед ним і молиться йому, і говорить: «спаси мене, бо ти бог мій».","Не знають і не розуміють вони: Він закрив очі їхні, щоб не бачили, і серця їхні, щоб не розуміли.","І не візьме він цього до свого серця, і немає у нього стільки знання і глузду, щоб сказати: «половину його я спалив у вогні і на вугіллі його спік хліб, засмажив м’ясо і з’їв; а із залишку його чи не зроблю я мерзоту? чи буду поклонятися шматку дерева?»","Він ганяється за пилом; обмануте серце ввело його в оману, і він не може звільнити душу свою і сказати: «чи не обман у правій руці моїй?»","Пам’ятай це, Якове й Ізраїлю, бо ти раб Мій; Я утворив тебе: раб Мій ти, Ізраїль, не забувай Мене.","Згладжу беззаконня твої, як туман, і гріхи твої, як хмару; звернися до Мене, бо Я відкупив тебе.","Торжествуйте, небеса, бо Господь створив це. Викликуйте, глибини землі; шуміть з радости, гори, ліс і всі дерева у ньому; бо відкупив Господь Якова і прославиться в Ізраїлі.","Так говорить Господь, Який відкупив тебе й утворив тебе від утроби материнської: Я Господь, Який створив усе, один розпростер небеса і Своєю силою розстелив землю,","Який робить нікчемними знамення лжепророків і виявляє безумство чарівників, мудреців проганяє назад і знання їх робить дурістю,","Який утверджує слово раба Свого і здійснює висловлювання Своїх посланців, Який говорить Єрусалиму: «ти будеш населений», і містам Іудиним: «ви будете побудовані, й руїни його Я відновлю»,","Який безодні говорить: «висохни!» і ріки твої Я висушу,","Який говорить про Кира: пастир Мій, і він виконає усю волю Мою і скаже Єрусалиму: «ти будеш побудований!» і храму: «ти будеш заснований!»"],"x":{"1":"31.43.10","2":"32.30.10|32.46.27","3":"39.2.28|53.7.38|54.2.17","4":"25.1.3","5":"40.9.12|76.3.12","6":"31.41.4|31.48.12|76.1.17|76.22.13","7":"31.42.9|11.19.25|54.17.26","8":"4.4.35|31.45.5","10":"31.2.8|31.45.16","12":"31.40.19|31.41.6-7","13":"29.13.11|32.10.3","17":"31.42.17","18":"52.10.21","22":"31.43.25","23":"31.49.13|36.6.3","24":"25.103.2|31.40.22|32.51.15","25":"24.5.12-13|63.1.19","26":"31.14.32|32.31.4","27":"1.14.21|5.3.16","28":"10.13.2|31.49.13|37.6.28"}},{"v":["Так говорить Господь помазаникові Своєму Киру: Я тримаю тебе за праву руку, щоб підкорити тобі народи, і зніму пояси зі стегон царів, щоб відчинялися для тебе двері, й ворота не зачинялися;","Я піду перед тобою і гори вирівняю, мідні двері розтрощу і запори залізні зламаю;","і віддам тобі збережені у тайні скарби і приховані багатства, щоб ти пізнав, що Я Господь, який називає тебе на ім’я, Бог Ізраїлів.","Заради Якова, раба Мого, й Ізраїля, обраного Мого, Я назвав тебе на ім’я, вшанував тебе, хоча ти не знав Мене.","Я Господь, і немає іншого; немає Бога, крім Мене; Я перепоясав тебе, хоча ти не знав Мене,","щоб дізналися від сходу сонця і від заходу, що немає, крім Мене; Я Господь, і немає іншого.","Я утворюю світло і творю пітьму, роблю мир і роблю біди; Я, Господь, роблю усе це.","Кропіть, небеса, звище, і хмари нехай проливають правду; нехай розкриється земля і приносить спасіння, і нехай виростає разом правда. Я, Господь, творю це.","Горе тому, хто сперечається з Творцем своїм, черепок з черепків земних! Чи скаже глина гончару: «що ти робиш?» і твоя справа чи скаже про тебе: «у нього немає рук»?","Горе тому, хто говорить батькові: «навіщо ти породив мене на світ?», а матері: «навіщо ти народила мене?»","Так говорить Господь, Святий Ізраїля і Творець його: ви запитуєте Мене про майбутнє синів Моїх і хочете Мені вказувати у ділі рук Моїх?","Я створив землю і створив на ній людину; Я — Мої руки розпростерли небеса, і всьому воїнству їх дав закон Я.","Я воздвиг його в правді й вирівняю усі путі його. Він побудує місто Моє і відпустить полонених Моїх, не за викуп і не за дари, — говорить Господь Саваоф.","Так говорить Господь: труди єгиптян і торгівля ефіоплян, і савейці, люди рослі, до тебе перейдуть і будуть твоїми; вони підуть за тобою, у кайданах прийдуть і впадуть перед тобою, і будуть благати тебе, говорячи: у тебе тільки Бог, і немає іншого Бога.","Істинно Ти Бог потаємний, Бог Ізраїлів, Спаситель.","Усі вони будуть посоромлені й осоромлені; разом з ними із соромом підуть і всі, що роблять ідолів.","Ізраїль же буде спасенний спасінням вічним у Господі; ви не будете посоромлені й осоромлені довіку.","Бо так говорить Господь, Який створив небеса, Він, Бог, Який утворив землю і створив її; Він утвердив її, не марно створив її; Він утворив її для проживання: Я Господь, і немає іншого.","Не таємно Я говорив, не у темному місці землі; не говорив Я племені Якова: «марно шукаєте Мене». Я Господь, Який проголошує правду, Який відкриває істину.","Зберіться і прийдіть, наблизьтеся усі, уцілілі з народів. Невігласи ті, які носять дерев’яного свого ідола і моляться богу, який не спасає.","Оголосіть і скажіть, порадившись між собою: хто звістив це з давніх часів, наперед сказав це? Чи не Я Господь? і немає іншого Бога, крім Мене, Бога праведного і спасительного немає, крім Мене.","До Мене наверніться, і будете спасенні, усі кінці землі, бо я Бог, і немає іншого.","Мною клянуся: з уст Моїх виходить правда, слово незмінне, що переді Мною схилиться усяке коліно, Мною буде клястися усякий язик.","Тільки у Господа, — будуть говорити про Мене, — правда і сила; до Нього прийдуть і посоромляться усі, що ворогували проти Нього.","Господом буде виправдане і прославлене усе плем’я Ізраїлеве."],"x":{"1":"13.36.23|31.44.28","5":"31.44.8","7":"0.1.3|40.3.6|43.1.12","8":"31.61.11|38.10.12","9":"31.29.16|32.18.6|62.9.21","12":"31.40.28|31.42.5|25.32.6","13":"31.52.3","14":"31.13.3|31.18.7|1.29.46","16":"31.44.11","17":"36.6.9|36.39.7","18":"31.42.5|4.4.35","19":"53.18.20","20":"31.46.7|4.32.37|6.10.14","21":"31.42.9|4.4.35|9.7.22","23":"62.14.11|67.2.10","24":"31.65.16","25":"32.4.2|32.23.6|64.5.21"}},{"v":["Упав Вил, звалився Нево́; ідоли їх — на худобі і в’ючних тваринах; ваша ноша зробилася тягарем для стомлених тварин.","Звалилися, упали разом; не могли захистити тих, які носили, і самі пішли у полон.","Послухайте мене, доме Яковів і весь залишок дому Ізраїлевого, прийняті Мною від утроби, носимі Мною від утроби материнської:","і до старости вашої Я той самий буду, і до сивини вашої Я ж буду носити вас; Я створив і буду носити, підтримувати й охороняти вас.","До кого уподібните Мене, і з ким порівняєте, і з ким звірите, щоб ми були подібні?","Висипають золото з гаманця і зважують срібло на терезах, і наймають срібляра, щоб він зробив з нього бога; кланяються йому і падають перед ним;","піднімають його на плечі, несуть його і ставлять його на своє місце; він стоїть, з місця свого не рухається; кричать до нього, — він не відповідає, не спасає від лиха.","Згадайте це і покажіть себе мужами; прийміть це, відступники, до серця;","згадайте, що було раніше, від початку віку, бо Я Бог, і немає іншого Бога, і немає подібного до Мене.","Я звіщаю від початку, що буде у кінці, і від давніх часів те, що ще не сталося, говорю: Моя рада відбудеться, й усе, що Мені вгодно, Я зроблю.","Я прикликав орла від сходу, з далекої країни, виконавця визначення Мого. Я сказав, і приведу це до виконання; накреслив наперед, і зроблю.","Послухайте Мене, жорстокі серцем, далекі від правди:","Я наблизив правду Мою, вона не далеко, і спасіння Моє не забариться; і дам Сиону спасіння, Ізраїлю славу Мою."],"x":{"1":"32.50.2","4":"25.70.9:18","5":"31.40.18|31.41.7","6":"6.17.4","7":"32.10.5|35.4.7","9":"4.32.39","10":"25.32.11|75.6.17","11":"25.32.9"}},{"v":["Зійди і сядь на порох, дівчино, дочко Вавилона; сиди на землі: престолу немає, дочко халдеїв, і надалі не будуть називати тебе ніжною і розкішною.","Візьми жорна і мели борошно; зніми покривало твоє, підбери поділ, відкрий гомілки, переходь через ріки:","відкриється нагота твоя, і навіть видний буде сором твій. Звершу помсту і не пощаджу нікого.","Відкупитель ваш — Господь Саваоф ім’я Йому, Святий Ізраїлів.","Сиди мовчки і піди у темряву, дочко халдеїв: бо надалі не будуть називати тебе господинею царств.","Я прогнівався на народ Мій, принизив спадщину Мою і віддав їх у руки твої; а ти не виявила їм милосердя, на старця накладала украй тяжке ярмо твоє.","І ти говорила: «вічно буду господинею», а не уявляла того у розумі твоєму, не думала, що буде опісля.","Але нині вислухай це, зніжена, що живеш безтурботно, говориш у серці своєму: «я, — й іншої подібної до мене немає; не буду сидіти вдовою і не буду знати втрати дітей».","Але раптово, в один день, прийде до тебе те й інше, втрата дітей і вдівство; повною мірою прийдуть вони на тебе, незважаючи на безліч чародійств твоїх і на велику силу чаклувань твоїх.","Бо ти сподівалася на лиходійство твоє, говорила: «ніхто не бачить мене». Мудрість твоя і знання твоє — вони збили тебе з путі; і ти говорила у серці твоєму: «я, і ніхто, крім мене».","І прийде на тебе біда: ти не дізнаєшся, звідки вона підніметься; і нападе на тебе біда, якої ти не в силах будеш відвернути, і раптово прийде на тебе згуба, про яку ти і не думаєш.","Залишайся ж зі своїми чаклуваннями і з безліччю чародійств твоїх, якими ти займалася від юности твоєї: можливо, допоможеш собі, можливо, встоїш.","Ти стомлена безліччю порад твоїх; нехай же виступлять спостерігачі небес і звіздарі й віщуни по новомісяччях, і спасуть тебе від того, що повинно статися з тобою.","Ось вони, як солома: вогонь спалив їх, — не визволили душі своєї від полум’я; не залишилося ні вугілля, щоб погрітися, ні вогню, щоб посидіти біля нього.","Такими стали для тебе ті, з якими ти трудилася, з якими вела торгівлю від юности твоєї. Кожен побрів у свій бік; ніхто не рятує тебе."],"x":{"1":"32.13.18|32.48.18|4.28.56","2":"6.16.21","3":"44.3.5","4":"71.4.10","6":"48.1.15|9.24.14","7":"76.18.7","8":"46.2.15","9":"31.51.19","10":"25.61.11|31.30.12|36.28.2","14":"31.33.11|24.31.12"}},{"v":["Слухайте це, доме Якова, що називаєтеся ім’ям Ізраїля і походите від джерела Іудиного, клянетеся ім’ям Господа і сповідуєте Бога Ізраїлевого, хоча не за істиною і не за правдою.","Бо вони називають себе тими, хто походить від святого міста і спираються на Бога Ізраїлевого; Господь Саваоф — ім’я Йому.","Минуле Я задовго оголошував; з Моїх уст виходило воно, і Я звіщав це і раптово робив, і все збувалося.","Я знав, що ти впертий, і що у шиї твоїй жили залізні, і чоло твоє — мідне;","тому й оголошував тобі задовго до того, як це приходило, і пред’являв тобі, щоб ти не сказав: «ідол мій зробив це, й істукан мій і вирізьблений мій повелів цьому бути».","Ти чув, — подивися на усе це! і невже ви не визнаєте́ цього? А нині Я звіщаю тобі нове і таємне, і ти не знав цього.","Воно відбулося нині, а не задовго і не за день, і ти не чув про те, щоб ти не сказав: «ось! я знав це».","Ти і не чув і не знав про це, і вухо твоє не було раніше відкрите; бо Я знав, що ти вчиниш віроломно, і від самої утроби материнської ти прозваний відступником.","Заради імені Мого відкладав гнів Мій, і заради слави Моєї утримував Себе від знищення тебе.","Ось, Я розплавив тебе, але не як срібло; випробував тебе у горнилі страждання.","Заради Себе, заради Себе Самого роблю це, — бо яке було б нарікання на ім’я Моє! слави Моєї не дам іншому.","Послухай Мене, Якове та Ізраїлю, покликаний Мій: Я той же, Я перший і Я останній.","Моя рука заснувала землю, і Моя правиця розпростерла небеса; покличу їх, і вони постануть разом.","Зберіться усі і слухайте: хто між ними передрік це? Господь полюбив його, і він виконає волю Його над Вавилоном і виявить силу Його над халдеями.","Я, Я сказав, і прикликав його; Я привів його, і путь його буде благоуспішною.","Приступіть до Мене, слухайте це: Я і спочатку говорив не таємно; з того часу, як це відбувається, Я був там; і нині послав Мене Господь Бог і Дух Його.","Так говорить Господь, Відкупитель твій, Святий Ізраїлів: Я Господь, Бог твій, Який навчає тебе корисного, Який веде тебе тим шляхом, яким слід тобі йти.","О, якби ти дослухався до заповідей Моїх! тоді мир твій був би як ріка, і правда твоя — як хвилі морські.","І сíм’я твоє було б як пісок, і те, що походить від стегон твоїх, — як піщинки: не згладилось би, не знищилось би ім’я його переді Мною.","Виходьте з Вавилона, біжіть від халдеїв, із гласом радости звіщайте і проповідуйте це, поширюйте цю звістку до меж землі; говоріть: «Господь відкупив раба Свого Якова».","І не мають вони спраги у пустелях, через які Він веде їх: Він виточує їм воду з каменя; розсікає скелю, і ллються води.","Нечестивим же немає миру, — говорить Господь."],"x":{"1":"32.4.2","2":"32.25.29|37.9.18|73.1.16","4":"13.30.8|32.5.3|36.2.4|36.3.7","8":"25.57.5|48.7.12","9":"3.14.8|25.105.45","10":"48.13.9|49.3.3|56.1.7","11":"31.42.8","12":"31.41.4|31.44.6","13":"25.101.26|31.40.28|62.4.17","16":"4.30.11|53.1.2|53.15.26","17":"31.45.19","18":"4.5.29|25.80.15|31.66.12","20":"32.50.8|76.18.4","21":"1.17.6|3.20.10-11|25.77.15|25.104.41|29.11.4|63.10.4","22":"31.57.21"}},{"v":["Слухайте Мене, острови, і слухайте, народи далекі: Господь прикликав Мене від утроби, від утроби матері Моєї називав ім’я Моє;","і зробив уста Мої як гострий меч; тінню руки Своєї покривав Мене, і зробив Мене стрілою загостреною; у сагайдаці Своєму зберігав Мене;","і сказав Мені: Ти раб Мій, Ізраїль, у Тобі Я прославлюся.","А Я сказав: даремно Я трудився, ні на що і марно виснажував силу Свою. Але Моє право у Господа, і нагорода Моя у Бога Мого.","І нині говорить Господь, Який утворив Мене від утроби рабом Своїм, щоб навернути до Нього Якова і щоб Ізраїль зібрався до Нього; Я вшанований в очах Господа, і Бог Мій — сила Моя.","І Він сказав: мало того, що Ти будеш рабом Моїм для відновлення колін Яковових і для повернення залишків Ізраїля, але Я зроблю Тебе світлом народів, щоб спасіння Моє простяглося до країв землі.","Так говорить Господь, Відкупитель Ізраїля, Святий Його, тому, кого зневажають усі, кого ганьбить народ, рабові володарів: царі побачать, і встануть; князі поклоняться заради Господа, Який вірний, заради Святого Ізраїлевого, Який обрав Тебе.","Так говорить Господь: у час благоприємний Я почув Тебе, й у день спасіння допоміг Тобі; і Я буду охороняти Тебе, і зроблю Тебе завітом народу, щоб відновити землю, щоб повернути спадкоємцям спадщини спустошені,","сказати в’язням: «виходьте», і тим, що у темряві: «покажіться». Вони при дорогах будуть пасти, і по усіх пагорбах будуть пасовища їхні;","не будуть терпіти голоду і спраги, і не вразить їх спека і сонце; бо Той, Хто милує їх, буде вести їх і приведе їх до джерел вод.","І всі гори Мої зроблю шляхом, і дороги Мої будуть підняті.","Ось, одні прийдуть здалеку; і ось, одні від півночі і моря, а інші з землі Синим.","Радуйтеся, небеса, і веселися, земле, і викликуйте, гори, з радости; бо утішив Господь народ Свій і помилував страдників Своїх.","А Сион говорив: «залишив мене Господь, і Бог мій забув мене!»","Чи забуде жінка грудне дитя своє, щоб не пожаліти сина утроби своєї? але якби і вона забула, то Я не забуду тебе.","Ось, Я накреслив тебе на долонях Моїх; стіни твої завжди переді Мною.","Сини твої поспішать до тебе, а розорителі і спустошувачі твої підуть від тебе.","Зведи очі твої і подивися навколо, — усі вони збираються, йдуть до тебе. Живу Я! говорить Господь, — усіма ними ти одягнешся, як убранням, і нарядишся ними, як наречена.","Бо руїни твої і пустелі твої, і розорена земля твоя будуть тепер занадто тісні для жителів, і ті, що поглинали тебе, віддаляться від тебе.","Діти, які будуть у тебе після втрати попередніх, будуть говорити вголос тобі: «тісне для мене місце; уступи мені, щоб я міг жити».","І ти скажеш у серці твоєму: хто мені породив їх? я була бездітна і неплідна, відведена у полон і вилучена; хто ж виростив їх? ось, я залишалася самотньою; де ж вони були?","Так говорить Господь Бог: ось, Я підніму руку Мою до народів, і виставлю знамено Моє племенам, і принесуть синів твоїх на руках і дочок твоїх на плечах.","І будуть царі годувальниками твоїми, і цариці їхні годувальницями твоїми; лицем до землі будуть кланятися тобі і лизати порох ніг твоїх, і пізнаєш, що Я Господь, що ті, які надіються на Мене, не посоромляться.","Чи може бути відібрана у сильного здобич, і чи можуть бути відняті у переможця узяті в полон?","Так! так говорить Господь: і полонені сильним будуть відняті, і здобич тирана буде визволена; тому що Я буду змагатися із супротивниками твоїми і синів твоїх Я спасу;","і пригноблювачів твоїх нагодую власною їх плоттю, і вони будуть упоєні кров’ю своєю, як молодим вином; і всяка плоть пізнає, що Я Господь, Спаситель твій і Відкупитель твій, Сильний Яковів."],"x":{"1":"31.45.3-4|32.1.5|50.1.21","2":"75.4.12|76.1.16|31.51.16","3":"50.12.18|53.17.4","6":"31.42.6|54.13.47","7":"31.53.3","8":"64.6.2","9":"31.61.1","10":"76.7.16","11":"31.62.10","13":"25.95.11|76.12.12|31.52.9","14":"32.31.20","15":"50.7.11|52.15.20|53.14.18","16":"25.50.20","18":"31.56.7|31.60.4","21":"31.60.4","22":"31.66.12:20|52.18.15:17","23":"31.60.16","24":"50.12.29","25":"52.11.22|31.49.9","26":"76.16.6|36.7.27|36.21.15"}},{"v":["Так говорить Господь: де розвідний лист вашої матері, з яким Я відпустив її? або якому з Моїх позикодавців Я продав вас? Ось, ви продані за гріхи ваші, і за злочини ваші відпущена мати ваша.","Чому, коли Я приходив, нікого не було, і коли Я кликав, ніхто не відповідав? Хіба рука Моя короткою стала для того, щоб визволяти, чи немає сили у Мені, щоб спасати? Ось, забороною Моєю Я висушую море, перетворюю ріки на пустелю; риби у них гниють від нестачі води і помирають від спраги.","Я одягаю небеса мороком, і веретище роблю покровом їх.","Господь Бог дав Мені язик мудрих, щоб Я міг словом підкріплювати того, хто знемагає; щоранку Він пробуджує, пробуджує вухо Моє, щоб Я слухав, подібно до учнів.","Господь Бог відкрив Мені вухо, і Я не заперечив, не відступив назад.","Я віддав хребет Мій тим, що б’ють, і щоки Мої тим, що уражають; лиця Мого не закривав від наруг і обплювання.","І Господь Бог допомагає Мені: тому Я не соромлюся, тому Я тримаю лице Моє, як кремінь, і знаю, що не залишуся у соромі.","Близько Той, Хто виправдовує Мене: хто хоче змагатися зі Мною? станьмо разом. Хто хоче судитися зі Мною? нехай підійде до Мене.","Ось, Господь Бог допомагає Мені: хто осудить Мене? Ось, усі вони, як одяг, постаріють; міль з’їсть їх.","Хто з вас боїться Господа, слухається гласу Раба Його? Хто ходить у мороці, без світла, нехай уповає на ім’я Господа і нехай утверджується у Бозі своєму.","Ось, усі ви, що запалюєте вогонь, озброєні запалювальними стрілами, — йдіть у полум’я вогню вашого і стріл, розжарених вами! Це буде вам від руки Моєї; у муках помрете."],"x":{"2":"3.11.23|31.59.1|31.65.2|44.1.4","3":"76.6.14","4":"50.7.29|51.1.22","5":"53.15.10","6":"50.26.67","8":"62.8.33","9":"62.8.34|25.101.27|31.51.8","10":"25.111.4|31.49.23"}},{"v":["Послухайте Мене ті, що прагнуть до правди, що шукають Господа! Гляньте на скелю, з якої ви висічені, у глибину рову, з якого ви витягнуті.","Подивіться на Авраама, батька вашого, і на Сарру, яка народила вас: бо Я прикликав його одного і благословив його, і розмножив його.","Так, Господь утішить Сион, утішить усі руїни його і зробить пустелі його, як рай, і степ його, як сад Господа; радість і веселість буде у ньому, славослів’я і піснеспіви.","Послухайте Мене, народе Мій, і плем’я Моє, прихиліть вухо до Мене! бо від Мене вийде закон, і суд Мій поставлю світлом для народів.","Правда Моя близька; спасіння Моє сходить і сила Моя буде судити народи; острови будуть уповати на Мене і сподіватися на силу Мою.","Підніміть очі ваші до небес, і подивіться на землю вниз: бо небеса зникнуть, як дим, і земля постаріє, як одяг, і жителі її також вимруть; а Моє спасіння буде перебувати вічно, і правда Моя не перестане.","Послухайте Мене ті, що знають правду, народ, у якого в серці закон Мій! Не бійтеся ганьби від людей, і лихослів’я їх не страшіться.","Бо, як одяг, з’їсть їх міль і, як вовну, з’їсть їх черва; а правда Моя перебуватиме повік, і спасіння Моє — у роди родів.","Повстань, повстань, одягнись міцністю, сила Господня! Повстань, як у дні древні, у роди давні! Чи не ти убила Раава, вразила крокодила?","Чи не ти висушила море, во́ди великої безодні, перетворила глибини моря на дорогу, щоб пройшли відкуплені?","І повернуться визволені Господом і прийдуть на Сион зі співом, і радість вічна над головою їх; вони знайдуть радість і веселощі: печаль і зітхання віддаляться.","Я, Я Сам — Утішитель ваш. Хто ти, що боїшся людини, яка помирає, і сина людського, який те саме, що трава,","і забуваєш Господа, Творця свого, Який розпростер небеса і заснував землю; і безперестанно, кожного дня страшишся люті гнобителя, ніби він готовий був знищити? Але де лють гнобителя?","Скоро буде визволений полонений, і не помре в ямі і не буде мати потреби у хлібі.","Я Господь, Бог твій, Який збурює море, так що хвилі його ревуть: Господь Саваоф — ім’я Його.","І Я вкладу слова Мої у вуста твої, і тінню руки Моєї покрию тебе, щоб упорядкувати небеса й утвердити землю і сказати Сиону: «ти Мій народ».","Пробудися, пробудися, встань, Єрусалиме, ти, який з руки Господа випив чашу люті Його, випив до дна чашу сп’яніння, осушив.","Нікому було вести його з усіх синів, породжених ним, і нікому було підтримати його за руку з усіх синів, яких він виростив.","Тебе спостигли дві біди, хто пошкодує про тебе? — спустошення і знищення, голод і меч: ким я втішу тебе?","Сини твої знемогли, лежать на розі усіх вулиць, як сарна в тенетах, сповнені гніву Господа, заборони Бога твого.","Отже, вислухай це, страдник і сп’янілий, але не від вина.","Так говорить Господь твій, Господь і Бог твій, Який мститься за Свій народ: ось, Я беру з руки твоєї чашу сп’яніння, дріжджі з чаші люті Моєї: ти не будеш уже пити їх,","і подам її у руки мучителям твоїм, які говорили тобі: «впади ниць, щоб нам пройти по тобі»; і ти хребет твій робив ніби землею й вулицею для тих, що проходили."],"x":{"2":"0.12.1","3":"36.36.35|25.109.2|31.2.3","5":"31.59.16","6":"25.101.27","7":"25.36.31","8":"31.51.6","9":"52.1.51|1.14.14","10":"1.14.21","11":"25.125.5|31.66.14|53.16.22","12":"50.10.28|25.89.6","13":"32.51.15","15":"24.26.12|31.54.5","16":"31.49.2","17":"25.59.5|32.25.15|36.23.31","19":"31.47.9","21":"32.25.18:27","22":"31.51.17","23":"25.74.9|25.128.3|31.49.26"}},{"v":["Повстань, повстань, одягнись у силу твою, Сионе! Одягнись в одяг величі твоєї, Єрусалиме, місто святе! бо вже не буде більше входити у тебе необрізаний і нечистий.","Струси із себе порох; встань, полонений Єрусалиме! зніми ланцюги із шиї твоєї, полонена дочко Сиону!","бо так говорить Господь: за ніщо були ви продані, і без срібла будете викуплені;","бо так говорить Господь Бог: народ Мій ходив колись у Єгипет, щоб там пожити, й Ассур тіснив його ні за що.","І тепер що у Мене тут? говорить Господь; народ Мій узятий задарма, володарі їхні шаленіють, — говорить Господь, — і постійно, кожного дня ім’я Моє неславиться.","Тому народ Мій пізна́є ім’я Моє; тому дізнається у той день, що Я той самий, Який сказав: «ось Я!»","Які прекрасні на горах ноги благовісника, що сповіщає мир, благовістить радість, проповідує спасіння, який говорить Сиону: «воцарився Бог твій!»","Голос вартових твоїх — вони піднесли голос і всі разом радіють, бо своїми очима бачать, що Господь повертається у Сион.","Торжествуйте, співайте разом, руїни Єрусалима, бо утішив Господь народ Свій, відкупив Єрусалим.","Оголив Господь святу правицю Свою перед очима всіх народів; і всі краї землі побачать спасіння Бога нашого.","Ідіть, ідіть, виходьте звідти; не доторкайтеся до нечистого; виходьте із середовища його, очистіть себе ті, що носите сосуди Господні!","бо ви вийдете неквапливо, і не побіжите; тому що попереду вас піде Господь, і Бог Ізраїлів буде стражем позаду вас.","Ось, раб Мій буде благоуспішний, підніметься і піднесеться, і звеличиться.","Як багато хто дивувався, дивлячись на Тебе, — настільки був спотворений більше за будь-яку людину лик Його, і вигляд Його — більше за синів людських!","Так багато народів приведе Він у здивування; царі закриють перед Ним уста свої, тому що вони побачать те, про що не було говорено їм, і узнають те, чого не чули."],"x":{"1":"31.60.1|54.7.51|76.21.27","3":"56.1.18-19","4":"0.46.6","5":"36.36.20|62.2.24","7":"25.67.12|44.1.15|62.10.15","8":"36.3.17","9":"31.40.1","10":"25.97.2-3","11":"64.6.17|76.18.4","12":"1.12.33","13":"48.3.8|50.12.18|67.2.9","14":"31.8.14|52.2.34","15":"62.15.21"}},{"v":["[Господи!] хто повірив чутому від нас, і кому відкрилася сила Господня?","Бо Він зійшов перед Ним, як пагін і як паросток із сухої землі; немає у Ньому ні вигляду, ні величі; і ми бачили Його, і не було у Ньому вигляду, який приваблював би нас до Нього.","Він був знехтуваний і умалений перед людьми, муж скорбот, що пізнав болісті, і ми відвертали від Нього лице своє; Він був зневажуваний, і ми ні у що ставили Його.","Але Він узяв на Себе наші немочі і поніс наші хвороби; а ми думали, що Він був уражений, покараний і принижений Богом.","Але Він укритий виразками був за гріхи наші і мучимий за беззаконня наші; покарання світу нашого було на Ньому, і ранами Його ми зцілилися.","Усі ми блукали, як вівці, зведені були кожен на свою дорогу: і Господь поклав на Нього гріхи усіх нас.","Він був мучимий, але страждав добровільно і не відкривав уст Своїх; як агнець, ведений був Він на заколення, і як агнець перед тим, хто стриже його, безмовний, так Він не відкривав уст Своїх.","Від пут і суду Він був узятий; але рід Його хто пояснить? бо Він відірваний від землі живих; за злочини народу Мого перетерпів страту.","Йому призначали гріб зі злочинцями, але Він похований у багатого, тому що не вчинив гріха, і не було неправди у вустах Його.","Але Господу вгодно було уразити Його, і Він віддав Його на муки; коли ж душа Його принесе жертву умилостивлення, Він побачить потомство довговічне, і воля Господня благоуспішно буде виконуватися рукою Його.","На подвиг душі Своєї Він буде дивитися із задоволенням; через пізнання Його Він, Праведник, Раб Мій, виправдає багатьох і гріхи їхні на Собі понесе.","Тому Я дам Йому частку між великими, і з сильними буде ділити здобич, за те, що віддав душу Свою на смерть, і до лиходіїв приєднаний був, тоді як Він поніс на Собі гріх багатьох і за злочинців зробився заступником."],"x":{"1":"31.42.20|53.12.38|62.10.16","2":"52.2.46","3":"51.9.12","4":"25.109.7|50.20.19","5":"62.4.25|63.15.3|56.2.24","6":"62.3.12|53.3.16","7":"50.26.63|50.27.12|51.14.61|54.8.32","8":"50.17.23|63.15.3","9":"56.2.22|58.3.5","10":"53.12.24","11":"32.23.6|54.7.52|53.1.29","12":"51.15.28|52.22.37"}},{"v":["Звеселись, неплідна, яка не народжує; викликни і виголоси, яка не мучилася пологами; тому що у залишеної набагато більше дітей, ніж у тієї, яка має чоловіка, — говорить Господь.","Розшир місце намету твого, розшир покрівлі осель твоїх; не соромся, пусти довше шнури твої і утверди кілки твої;","бо ти поширишся праворуч і ліворуч, і потомство твоє заволодіє народами і населить спустошені міста.","Не бійся, бо не будеш посоромлена; не знічуйся, бо не будеш у нарузі: ти забудеш посоромлення юности твоєї і не будеш більше згадувати про безславність удівства твого.","Тому що твій Творець є чоловік твій; Господь Саваоф — ім’я Його; і Відкупитель твій — Святий Ізраїлів: Богом усієї землі назветься Він.","Бо як дружину, залишену і скорботну духом, закликає тебе Господь, і як дружину юности, яка була відкинута, — говорить Бог твій.","На малий час Я залишив тебе, але з великою милістю прийму тебе.","У полум’ї гніву Я приховав від тебе лице Моє на час, але вічною милістю помилую тебе, — говорить Відкупитель твій, Господь.","Бо це для Мене, як води Ноя: як Я поклявся, що води Ноя не прийдуть більше на землю, так поклявся не гніватися на тебе і не дорікати тобі.","Гори зрушаться і пагорби захитаються, — а милість Моя не відступить від тебе, і завіт миру Мого не похитнеться, — говорить Господь, Який милує тебе.","Бідна, яку кидає буря, безутішна! Ось, Я покладу камені твої на рубіні і зроблю основу твою із сапфірів;","і зроблю вікна твої з рубінів і ворота твої — з перлин, і всю огорожу твою — із коштовних каменів.","І всі сини твої будуть навчені Господом, і великий мир буде у синів твоїх.","Ти утвердишся правдою, будеш далека від гноблення, бо тобі боятися немає чого, і від жаху, бо він не наблизиться до тебе.","Ось, будуть озброюватися проти тебе, але не від Мене; хто б не озброївся проти тебе, впаде.","Ось, Я створив коваля, який роздуває вугілля у вогні і робить знаряддя для своєї справи, — і Я творю губителя для знищування.","Жодне знаряддя, зроблене проти тебе, не буде успішним; і всякий язик, який буде змагатися з тобою на суді, — ти звинуватиш. Це є спадщина рабів Господа, виправдання їх від Мене, — говорить Господь."],"x":{"1":"52.23.29|65.4.27","3":"0.9.27","4":"48.8.15","5":"52.1.31-32","6":"31.62.4","7":"29.3.5","8":"31.26.20","9":"0.9.11","10":"32.31.31|45.3.6|36.34.25","12":"76.21.12","13":"32.31.34|53.6.45|75.8.11|62.5.1","17":"52.21.15|54.6.10"}},{"v":["Спраглі! йдіть усі до вод; навіть і ви, у яких немає срібла, йдіть, купуйте і споживайте; йдіть, купуйте без срібла і без плати вино і молоко.","Для чого вам відважувати срібло за те, що не хліб, і надбане трудами своїми за те, що не насичує? Послухайте Мене уважно і споживайте благо, і душа ваша нехай насолодиться жиром.","Прихиліть вухо ваше і прийдіть до Мене: послухайте, і жива буде душа ваша, — і дам вам завіт вічний, незмінні милості, обіцяні Давиду.","Ось, Я дав Його свідком для народів, вождем і наставником народам.","Ось, ти прикличеш народ, якого ти не знав, і народи, які тебе не знали, поспішать до тебе заради Господа Бога твого і заради Святого Ізраїлевого, бо Він прославив тебе.","Шукайте Господа, коли можна знайти Його; прикликайте Його, коли Він близько.","Нехай залишить нечестивий путь свій і беззаконник — думки свої, і нехай навернеться до Господа, і Він помилує його, і до Бога нашого, бо Він многомилостивий.","Мої думки — не ваші думки, ні ваші путі — путі Мої, говорить Господь.","Але, як небо вище за землю, так путі Мої вищі за путі ваші, і думки Мої вищі за думки ваші.","Як дощ і сніг сходить з неба і туди не повертається, але напуває землю і робить її здатною родити і вирощувати, щоб вона давала насіння тому, хто сіє, і хліб тому, хто їсть, —","так і слово Моє, яке виходить з уст Моїх, — воно не повертається до Мене марним, але виконує те, що Мені угодно, і звершує те, для чого Я послав його.","Отже, ви вийдете з веселощами і будете випроваджені з миром; гори і пагорби будуть співати перед вами пісню, і всі дерева у полі рукоплескати вам.","Замість терня виросте кипарис; замість кропиви виросте мирт; і це буде на славу Господа, у знамення вічне, незламне."],"x":{"1":"53.7.37","2":"49.4.2","3":"9.7.12|54.13.34","4":"4.18.15","5":"54.13.46","6":"31.45.19|32.29.13|38.10.12","7":"36.18.23","8":"63.3.19","10":"4.32.2","11":"72.2.9","13":"31.41.19"}},{"v":["Так говорить Господь: зберігайте суд і чиніть правду; бо близько спасіння Моє й одкровення правди Моєї.","Блажен муж, який робить це, і син людський, який міцно тримається цього, який зберігає суботу від осквернення й оберігає руку свою, щоб не зробити ніякого зла.","Нехай не говорить син іноплемінника, який приєднався до Господа: «Господь зовсім відокремив мене від Свого народу», і нехай не говорить євнух: «ось я сухе дерево».","Бо Господь так говорить про євнухів: які зберігають Мої суботи й обирають угодне Мені, і міцно тримаються завіту Мого, —","тим дам Я у домі Моєму й у стінах Моїх місце й ім’я краще, ніж синам і дочкам; дам їм вічне ім’я, яке не знищиться.","І синів іноплемінників, які приєдналися до Господа, щоб служити Йому і любити ім’я Господа, бути рабами Його, усіх, що зберігають суботу від осквернення її і твердо тримаються завіту Мого,","Я приведу на святу гору Мою й обрадую їх у Моєму домі молитви; всепалення їхні й жертви їхні будуть благоприємні на жертовнику Моєму, бо дім Мій назветься домом молитви для усіх народів.","Господь Бог, Який збирає розсіяних ізраїльтян, говорить: до зібраних у нього Я буду ще збирати інших.","Усі звірі польові, усі звірі лісові! йдіть їсти.","Вартові їхні сліпі усі й невігласи: усі вони німі пси, що не можуть гавкати, що марять лежачи, що люблять спати.","І це пси, жадібні душею, які не знають ситости; і це пастирі безглузді: усі дивляться на свою дорогу, кожен до останнього, на свою користь;","приходьте, говорять, я дістану вина, і ми нап’ємося сикери; і завтра те саме буде, що сьогодні, та ще й більше."],"x":{"1":"29.1.1","4":"31.58.13","5":"53.1.12|58.3.2|76.2.17","6":"31.60.10|36.47.22|54.10.35","7":"31.2.2|50.21.13|51.11.17|52.19.46","8":"53.10.16|66.2.13","9":"32.7.33","10":"52.6.39|76.22.15|57.2.13","11":"32.6.13|32.8.10","12":"31.22.13|29.2.6|63.15.32"}},{"v":["Праведник помирає, і ніхто не приймає цього до серця; і мужі благочестиві підносяться від землі, і ніхто не помислить, що праведник підноситься від зла.","Він відходить до миру; ті, що ходять прямими путями, будуть спочивати на ложах своїх.","Але наблизьтеся сюди ви, сини чаклунки, сíм’я перелюбника і блудниці!","З кого ви глузуєте? проти кого розширюєте рот, висуваєте язик? чи ви не діти злочину, сíм’я неправди,","розпалені похіттю до ідолів під кожним гіллястим деревом, ті, що заколюєте дітей біля струмків, між розщелинами скель?","У гладеньких каменях струмків доля твоя; вони, вони жереб твій; їм ти робиш узливання і приносиш жертви: чи можу Я бути задоволений цим?","На високій і видатній горі ти ставиш ложе твоє і туди піднімаєшся приносити жертву.","За дверима також і за одвірками ставиш пам’яті твої; бо, відвернувшись від Мене, ти оголюєшся і сходиш; розширюєш постіль твою і домовляєшся з тими з них, з якими любиш лежати, видивляєшся місце.","Ти ходила також до царя із запашною мастю і примножила масті твої, і далеко посилала послів твоїх, і принижувалася до пекла.","Від довгого шляху твого стомлювалася, але не говорила: «надія загублена!»; усе ще знаходила жвавість у руці твоїй, і тому не відчувала ослаблення.","Кого ж ти злякалася й устрашилася, що зробилася невірною і Мене перестала пам’ятати і зберігати у твоєму серці? чи не від того, що Я мовчав, і притому довго, ти перестала боятися Мене?","Я покажу правду твою і діла твої, — і вони будуть не на користь тобі.","Коли ти будеш волати, чи спасе тебе збіговисько твоє? — усіх їх віднесе вітер, розвіє подув; а той, хто надіється на Мене, успадкує землю і буде володіти святою горою Моєю.","І сказав: піднімайте, піднімайте, рівняйте шлях, прибирайте перешкоду зі шляху народу Мого.","Бо так говорить Вишній і Звеличений, Який вічно живе, — Святий ім’я Його: Я живу на висоті небес і у святилищі, й також із упокореними і смиренними духом, щоб оживляти дух смиренних і оживляти серця упокорених.","Бо не вічно буду Я судитися і не до кінця гніватися; інакше знеможе переді Мною дух і все, що дише, що Мною створене.","За гріх користолюбства його Я гнівався й уражав його, ховав лице і обурювався; але він, відвернувшись, пішов шляхом свого серця.","Я бачив шляхи його, і зцілю його, і буду водити його й утішати його і засмучених його.","Я виконаю слово: мир, мир далекому і ближньому, — говорить Господь, — і зцілю його.","А нечестиві — як море схвильоване, яке не може заспокоїтися, і во́ди якого викидають мул і бруд.","Немає миру нечестивим, — говорить Бог мій."],"x":{"1":"25.11.2|43.7.2","2":"29.4.7","3":"50.12.39","4":"62.9.6","5":"11.16.4|32.2.20","7":"36.18.6","9":"38.12.1","11":"25.49.21|31.42.14","12":"31.64.6","13":"25.14.1|31.28.16","14":"31.62.10","15":"25.137.6|31.66.2","16":"25.102.9|46.3.9|43.7.18","18":"4.32.39","19":"31.52.7|62.5.1","21":"31.48.22"}},{"v":["Волай голосно, не стримуйся; піднеси голос твій, подібно до труби, і вкажи народу Моєму на беззаконня його, і дому Якова — на гріхи його.","Вони щодня шукають Мене і хочуть знати шляхи Мої, ніби народ, який живе праведно і не полишає законів Бога свого; вони запитують Мене про суди правди, бажають наближення до Бога:","«Чому ми постимося, а Ти не бачиш? смиряємо душі свої, а Ти не знаєш?» — Ось, у день посту вашого ви виконуєте волю вашу і вимагаєте тяжких трудів від інших.","Ось, ви поститеся для сварок і суперечок і для того, щоб жорстокою рукою бити інших; ви не поститеся у цей час так, щоб голос ваш був почутий на висоті.","Чи такий той піст, який Я обрав, день, в який томить людина душу свою, коли гне голову свою, як тростину, і підстилає під себе руб’я і попіл? Чи це назвеш постом і днем, угодним Господу?","Ось піст, що Я обрав: зніми кайдани неправди, розв’яжи пута ярма, і пригноблених відпусти на волю, і розірви усяке ярмо;","розділи з голодним хліб твій, і подорожніх бідних уведи у дім; коли побачиш нагого, вдягни його, і від єдинокровного твого не ховайся.","Тоді відкриється, як зоря, світло твоє, і зцілення твоє швидко проросте, і правда твоя піде перед тобою, і слава Господня буде супроводжувати тебе.","Тоді ти взиватимеш, і Господь почує; заволаєш, і Він скаже: «ось Я!» Коли ти викинеш із середовища твого ярмо, перестанеш піднімати палець і говорити образливе,","і віддаси голодному душу твою і наситиш душу страдника: тоді світло твоє зійде у темряві, і морок твій буде як полудень;","і буде Господь вождем твоїм завжди, і під час засухи буде насичувати душу твою й наповнювати кістки твої, і ти будеш, як напоєний водою сад і як джерело, води якого ніколи не висихають.","І забудуються нащадками твоїми пустелі вікові: ти відновиш основи багатьох поколінь, і будуть називати тебе тим, хто відбудовує руїни, відновителем шляхів для населення.","Якщо ти утримуєш ногу твою заради суботи від виконання примх твоїх у святий день Мій, і будеш називати суботу відрадою, святим днем Господнім, шанованим, і вшануєш її тим, що не будеш займатися звичайними твоїми справами, догоджати твоїм примхам і марнословити, —","то будеш мати радість у Господі, і Я піднесу тебе на висоти землі і дам спожити тобі спадщину Якова, батька твого: вуста Господні вирекли це."],"x":{"1":"36.33.7|72.4.2","2":"31.1.18|36.33.17|49.3.7","3":"50.6.16|52.5.33|52.18.12","4":"52.6.35","5":"48.7.5","6":"32.21.12","7":"36.18.7|50.25.35","8":"25.36.6","9":"31.1.19|31.65.24","10":"31.42.16","11":"32.31.12|53.4.10","12":"31.61.4","13":"31.56.4|32.17.24","14":"4.32.13"}},{"v":["Ось, рука Господа не скоротилася на те, щоб спасати, і вухо Його не обважніло для того, щоб чути.","Але беззаконня ваші зробили розділення між вами і Богом вашим, і гріхи ваші відвертають лице Його від вас, щоб не чути.","Бо руки ваші осквернені кров’ю і пальці ваші — беззаконням; уста ваші говорять лжу, язик ваш вимовляє неправду.","Ніхто не підносить голосу за правду, і ніхто не заступається за істину; сподіваються на пусте і говорять неправду, зачинають зло і породжують злодійство;","висиджують зміїні яйця і тчуть павутиння; хто з’їсть яйця їх, — помре, а якщо розчавить, — виповзе єхидна.","Павутиння їх для одягу непридатне, і вони не покриються своїм виробом; діла їхні — діла неправедні, і насильство у руках їхніх.","Ноги їхні біжать до зла, і вони поспішають на пролиття невинної крови; думки їхні — думки нечестиві; спустошення і загибель на стежках їхніх.","Путі миру вони не знають, і немає суду на стежках їхніх; путі їхні викривлені, і ніхто, який іде ними, не знає миру.","Тому-то і далекий від нас суд, і правосуддя не досягає до нас; чекаємо світла, і ось темрява, — осяяння, і ходимо у мороці.","Сприймаємо на дотик, як сліпі стіну, і, як без очей, ходимо навпомацки; спотикаємося опівдні, як у сутінках, між живими — як мертві.","Усі ми ревемо, як ведмеді, і стогнемо, як голуби; очікуємо суду, і немає його, — спасіння, але воно далеко від нас.","Бо злочини наші численні перед Тобою, і гріхи наші свідчать проти нас; бо злочини наші з нами, і беззаконня наші ми знаємо.","Ми зрадили і сказали неправду перед Господом, і відступили від Бога нашого; говорили наклеп і зраду, зачинали і народжували із серця неправдиві слова.","І суд відступив назад, і правда стала вдалині, бо істина спотикнулася на площі, і чесність не може увійти.","І не стало істини, і той, хто віддаляється від зла, піддається образі. І Господь побачив це, й огидно було очам Його, що немає суду.","І бачив, що немає людини, і дивувався, що немає заступника; і допомогла Йому правиця Його, і правда Його підтримала Його.","І Він поклав на Себе правду, як броню, і шолом спасіння на голову Свою; і вдягнувся у ризу помсти, як в одяг, і покрив Себе ревністю, як плащем.","Мірою відплати, за цією мірою Він воздасть супротивникам Своїм — люттю, ворогам Своїм — помстою, островам віддасть належне.","І будуть боятися імені Господа на заході і слави Його — на сході сонця. Якщо ворог прийде як ріка, подув Господа прожене його.","І прийде Відкупитель Сиону і синів Якова, які навернулися від нечестя, — говорить Господь.","І ось завіт Мій з ними, — говорить Господь: Дух Мій, Який на тобі, і слова Мої, які вклав Я в уста твої, не відступлять від уст твоїх і від уст потомства твого, і від уст нащадків потомства твого, — говорить Господь, відтепер і до віку."],"x":{"1":"3.11.23|31.50.2","2":"33.3.44","3":"31.1.15","4":"25.7.15|32.7.8|24.15.35","5":"50.12.34","7":"26.1.16|62.3.15","8":"31.57.20","9":"31.59.14|24.30.26","10":"4.28.29","11":"31.38.14|32.8.15","12":"25.39.13","14":"31.59.9|38.4.1","16":"31.63.5","17":"29.5.18|66.6.17|69.5.8","19":"31.45.6","20":"62.11.26","21":"36.36.27"}},{"v":["Восстань, світися, [Єрусалиме], бо прийшло світло твоє, і слава Господня зійшла над тобою.","Бо ось, темрява покриє землю, і морок — народи; а над тобою засяє Господь, і слава Його явиться над тобою.","І прийдуть народи до світла твого, і царі — до сяйва, яке сходить над тобою.","Зведи очі твої і подивися навколо: усі вони збираються, йдуть до тебе; сини твої здалеку йдуть і дочок твоїх на руках несуть.","Тоді побачиш, і зрадієш, і затремтить і розшириться серце твоє, тому що багатство моря повернеться до тебе, надбання народів прийде до тебе.","Безліч верблюдів покриє тебе — дромадери з Мадіама й Ефи; усі вони із Сави прийдуть, принесуть золото і ладан і звістять славу Господа.","Усі вівці кидарські будуть зібрані до тебе; барани неваїофські послужать тобі: зійдуть на вівтар Мій жертвою благоугодною, і Я прославлю дім слави Моєї.","Хто це летить, як хмари, і як голуби, — до голубників своїх?","Так, на Мене чекають острови, і попереду них — кораблі фарсиські, щоб перевезти синів твоїх здалеку і з ними срібло їх і золото їх, в ім’я Господа Бога твого і Святого Ізраїлевого, бо Він прославив тебе.","Тоді сини іноземців будуть будувати стіни твої, і царі їхні — служити тобі; бо у гніві Моєму Я вражав тебе, але у благоволінні Моєму буду милостивим до тебе.","І будуть завжди відкриті врата твої, не будуть зачинятися ні вдень ні вночі, щоб принесено було до тебе надбання народів і приведені були царі їх.","Бо народ і царства, які не захочуть служити тобі, — загинуть, і такі народи зовсім знищаться.","Слава Ливану прийде до тебе, кипарис і певг і разом кедр, щоб прикрасити місце святилища Мого, і Я прославлю підніжжя ніг Моїх.","І прийдуть до тебе з покірністю сини гнобителів твоїх, і впадуть до стоп ніг твоїх усі, що зневажали тебе, і назвуть тебе містом Господа, Сионом Святого Ізраїлевого.","Замість того, що ти був залишений і ненавидимий, так що ніхто не проходив через тебе, Я зроблю тебе величчю навіки, радістю у роди родів.","Ти будеш насичуватися молоком народів, і груди царські ссати будеш, і пізнаєш, що Я Господь — Спаситель твій і Відкупитель твій, Сильний Яковів.","Замість міді буду доставляти тобі золото, і замість заліза срібло, і замість дерева мідь, і замість каменів залізо; і поставлю правителем твоїм мир і наглядачами твоїми — правду.","Не чутно буде більше насильства в землі твоїй, спустошення і руйнування — у краях твоїх; і будеш називати стіни твої спасінням і ворота твої — славою.","Не буде уже сонце служити тобі світлом денним, і сяйво місяця — світити тобі; але Господь буде тобі вічним світлом, і Бог твій — славою твоєю.","Не зайде уже сонце твоє, і місяць твій не сховається, бо Господь буде для тебе вічним світлом, і закінчаться дні сумування твого.","І народ твій весь буде праведний, навіки успадкує землю, — паросток насадження Мого, справу рук Моїх, для прославляння Мого.","Від малого вийде тисяча, і від найслабшого — сильний народ. Я, Господь, прискорю звершити це у свій час."],"x":{"1":"31.52.1|52.1.78|53.1.9","2":"66.4.18","3":"52.2.32","4":"76.21.24|31.49.22|31.66.12","5":"54.11.18","6":"25.71.10","7":"31.11.14|31.42.11|49.1.11","10":"25.29.6","11":"76.21.25","12":"32.12.17|48.14.17","13":"31.35.1","15":"31.35.10","16":"31.49.23","17":"31.54.11","19":"76.22.5","20":"31.42.7","21":"31.52.1|31.61.3|76.21.27","22":"0.15.5"}},{"v":["Дух Господа Бога на Мені, бо Господь помазав Мене благовістити убогим, послав Мене зціляти скрушених серцем, проповідувати полоненим визволення і в’язням відкриття в’язниці,*","проповідувати літо Господнє благоприємне і день помсти Бога нашого, утішити усіх засмучених,","сповістити тим, що тужать на Сионі, що їм замість попелу дасться прикраса, замість плачу — єлей радости, замість сумного духу — славний одяг, і назвуть їх сильними правдою, насадженням Господа на славу Його.","І забудують пустелі вікові, відбудують древні руїни і відновлять міста зруйновані, які залишалися в запустінні з давніх родів.","І прийдуть іноземці і будуть пасти стада ваші; і сини чужоземців будуть вашими хліборобами і вашими виноградарями.","А ви будете називатися священиками Господа, служителями Бога нашого будуть іменувати вас; будете користуватися надбанням народів і славитися славою їх.","За посоромлення вам буде удвічі; за ганьбу вони будуть радіти своїй частці, тому що у землі своїй удвічі одержать; веселість вічна буде у них.","Бо Я, Господь, люблю правосуддя, ненавиджу грабіжництво з насильством і воздам нагороду їм за істиною, і завіт вічний укладу з ними;","і буде відомо між народами сíм’я їх, і потомство їх — серед племен; усі, що бачать їх, пізнають, що вони сíм’я, благословенне Господом.","Радістю буду радуватися у Господі, звеселиться душа моя у Бозі моєму: бо Він одягнув мене у ризи спасіння, одежею правди одяг мене, як на нареченого, поклав вінець і, як наречену, прикрасив убранням.","Бо, як земля родить рослини свої, і як сад вирощує посіяне в ньому, так Господь Бог виявить правду і славу перед усіма народами."],"x":{"1":"31.11.2|31.42.7|52.4.18|25.146.3","2":"31.63.4|50.5.4|52.6.21","3":"31.60.21","4":"31.58.12|36.36.34","5":"31.60.10","6":"32.33.21|76.1.6|76.21.26","8":"26.15.8","9":"31.65.23|48.8.13","10":"31.59.17|50.22.11|25.44.10","11":"31.45.8"},"n":{"1":["За перекладом 70-ти: сліпим прозріння."]}},{"v":["Не вмовкну заради Сиону, і заради Єрусалима не заспокоюся, доки не зійде, як світло, правда його, і спасіння його — як запалений світильник.","І побачать народи правду твою і всі царі — славу твою, і назвуть тебе новим ім’ям, яке наречуть уста Господа.","І будеш вінцем слави у руці Господа і царською діадемою на долоні Бога твого.","Не будуть уже називати тебе «залишеним», і землю твою не будуть більше називати «пустелею», але будуть називати тебе: «Моє благовоління до нього», а землю твою — «заміжньою», бо Господь благоволить до тебе, і земля твоя поєднається.","Як юнак поєднується з дівою, так поєднаються з тобою сини твої; і як наречений радіє за наречену, так буде радіти за тебе Бог твій.","На стінах твоїх, Єрусалиме, Я поставив вартових, які не будуть умовкати ні вдень, ні вночі. О, ви, що нагадуєте про Господа! не умовкайте, —","не умовкайте перед Ним, доки Він не відновить і доки не зробить Єрусалим славою на землі.","Господь поклявся правицею Своєю і міцними м’язами Своїми: не дам зерна твого більше в їжу ворогам твоїм, і сини чужих не будуть пити вина твого, над яким ти трудився;","але ті, що збирають його, будуть їсти його і славити Господа, і ті, що оббирають виноград, будуть пити вино його у дворах святилища Мого.","Проходьте, проходьте у ворота, готуйте шлях народу! Рівняйте, рівняйте дорогу, прибирайте камені, підніміть знамено для народів!","Ось, Господь повідомляє до краю землі: скажіть дочці Сиону: гряде Спаситель твій; нагорода Його з Ним і воздаяння Його перед Ним.","І назвуть їх народом святим, відкупленим Господом, а тебе назвуть знайденим містом, незалишеним."],"x":{"1":"31.42.14|31.61.11|31.64.12","2":"31.56.5|31.65.15|76.2.17","4":"38.1.10|56.2.10","5":"51.2.19|46.3.17","6":"31.41.27|32.16.17","7":"25.101.15","8":"31.54.9|31.65.21|40.9.13","9":"31.41.16","10":"31.57.14","11":"48.9.9|50.21.5|53.12.15|31.40.10","12":"37.7.27|31.51.11|31.62.4"}},{"v":["Хто це йде від Едома, у червлених ризах від Восора, настільки величний у Своєму одязі, Який виступає у повноті сили Своєї? «Я — Який проголошує правду, сильний, щоб спасати».","Від чого ж одіяння Твоє червоне, і ризи у Тебе, як у того, хто топтав у точилі?","«Я топтав точило один, і з народів нікого не було зі Мною; і Я топтав їх у гніві Моєму і давив їх у люті Моїй; кров їх бризкала на ризи Мої, і Я заплямував усе одіяння Своє;","бо день помсти — у серці Моєму, і рік Моїх відкуплених настав.","Я дивився, і не було помічника; дивувався, що не було того, хто підтримує; але допомогла Мені правиця Моя, і лють Моя — вона підтримала Мене:","і потоптав Я народи у гніві Моєму, і скрушив їх у люті Моїй, і вилив на землю кров їх».","Пом’яну милості Господні і славу Господню за все, що Господь дарував нам, і велику благість Його до дому Ізраїлевого, яку вчинив Він йому за милосердям Своїм і за множеством щедрот Своїх.","Він сказав: «дійсно вони народ Мій, діти, які не скажуть неправди», і Він був для них Спасителем.","У всякій скорботі їх Він не залишав їх, і ангел лиця Його спасав їх; з любови Своєї і благосердя Свого Він відкупив їх, узяв і носив їх в усі дні давні.","Але вони збурилися і засмутили Святого Духа Його; тому Він обернувся на ворога їх: Сам воював проти них.","Тоді народ Його згадав давні дні, Мойсеєві: де Той, Який вивів їх з моря з пастирем овець Своїх? де Той, Який уклав у серце його Святого Духа Свого,","Який вів Мойсея за праву руку величною правицею Своєю, розділив перед ними води, щоб зробити Собі вічне ім’я,","Який вів їх через безодні, як коня по степу, і вони не спотикалися?","Як стадо сходить у долину, Дух Господній вів їх до спокою. Так вів Ти народ Твій, щоб зробити Собі славне ім’я.","Споглянь з небес і подивися з оселі святині Твоєї і слави Твоєї: де ревність Твоя і могутність Твоя? — благосердя Твоє і милості Твої до мене утримані.","Тільки Ти — Отець наш; бо Авраам не впізнає нас, і Ізраїль не визнає нас своїми; Ти, Господи, Отець наш, від віку ім’я Твоє: «Відкупитель наш».","Для чого, Господи, Ти попустив нам звестися зі шляхів Твоїх, озлобитися серцю нашому, щоб не боятися Тебе? обернися заради рабів Твоїх, заради колін спадщини Твоєї.","Короткий час володів ним народ святині Твоєї: вороги наші потоптали святилище Твоє.","Ми зробилися такими, над якими Ти ніби ніколи не володарював і над якими не іменувалося ім’я Твоє."],"x":{"1":"31.34.6","2":"76.19.13","3":"31.43.25|33.1.15|53.13.33","4":"31.34.8|31.61.2","5":"25.97.1|31.59.16","6":"31.49.26","9":"4.7.7-8|4.32.11-12|1.19.4","10":"3.14.11|25.77.57","11":"1.14.30","12":"1.14.21|3.14.17","13":"29.19.9","14":"25.105.8","15":"4.26.15|35.2.16","16":"31.64.8","17":"62.11.7|64.3.14|4.32.9","18":"25.73.3","19":"31.64.10"}},{"v":["О, якби Ти розірвав небеса і зійшов! гори розтанули б від лиця Твого,","як від вогню, який розплавляє, як від того, хто кип’ятить воду, щоб ім’я Твоє зробити відомим ворогам Твоїм; від лиця Твого здригнулися б народи.","Коли Ти звершував страшні діла, для нас несподівані, і сходив, — гори танули від лиця Твого.","Бо від віку не чули, не слухали вухом, і ніяке око не бачило іншого бога, крім Тебе, Який стільки зробив би для тих, що надіються на нього.","Ти милостиво зустрічав того, хто радіє і чинить правду, хто поминає Тебе на путях Твоїх. Але ось, Ти прогнівався, тому що ми здавна грішили; і як же ми будемо спасені?","Усі ми зробилися — як нечистий, і вся праведність наша — як забруднений одяг; і всі ми зблякли, як лист, і беззаконня наші, як вітер, несуть нас.","І немає того, хто прикликає ім’я Твоє, хто поклав би міцно триматися за Тебе; тому Ти сховав від нас лице Твоє і залишив нас гинути від беззаконь наших.","Але нині, Господи, Ти — Отець наш; ми — глина, а Ти — утворитель наш, і всі ми — діло руки Твоєї.","Не гнівайся, Господи, без міри, і не вічно пам’ятай беззаконня. Споглянь же: ми усі народ Твій.","Міста святині Твоєї зробилися пустелею; пустелею став Сион; Єрусалим спустошений.","Дім освячення нашого і слави нашої, де батьки наші прославляли Тебе, спалений вогнем, і всі коштовності наші розграбовані.","Після цього чи будеш ще стримуватися, Господи, чи будеш мовчати і карати нас без міри?"],"x":{"1":"52.10.24|76.22.20|25.96.5","2":"25.82.19","3":"6.5.5","4":"63.2.9","5":"25.30.20","6":"25.89.6","8":"31.63.16","9":"25.78.8","10":"25.78.1","12":"31.62.1"}},{"v":["Я відкрився тим, що не запитували про Мене; Мене знайшли ті, що не шукали Мене. «Ось Я! ось Я!» — говорив Я народу, який не іменувався ім’ям Моїм.","Кожного дня простягав Я руки Мої до народу непокірливого, який ходив шляхом недобрим, за своїми помислами, —","до народу, який постійно ображає Мене у лице, приносить жертви у дібровах і спалює фіміам на черепках,","сидить у гробах і ночує у печерах; їсть свиняче м’ясо, і мерзенне вариво у посудинах у нього;","який говорить: «зупинися, не підходь до мене, тому що я святий для тебе». Вони — дим для нюху Мого, вогонь, що горить кожного дня.","Ось що написано перед лицем Моїм: не змовчу, але воздам, воздам у надра їх","беззаконня ваші, — говорить Господь, — і разом беззаконня батьків ваших, які курили фіміам на горах, і на пагорбах ганьбили Мене; і відміряю у надра їх попередні діяння їх.","Так говорить Господь: коли у виноградному гроні знаходиться сік, тоді говорять: «не пошкодь його, тому що у ньому благословення»; те саме зроблю Я і заради рабів Моїх, щоб не усіх погубити.","І виведу від Якова сíм’я, і від Іуди спадкоємця гір Моїх, і успадкують це обрані Мої, і раби Мої будуть жити там.","І буде Сарон пасовищем для овець і долина Ахор — місцем спочинку для волів народу Мого, який знайшов Мене.","А вас, які залишили Господа, забули святу гору Мою, готуєте трапезу для Гада і розчиняєте повну чашу для Мени,* —","вас прирікаю Я до меча, і всі ви схилитеся на заколення: тому що Я кликав, і ви не відповідали; говорив, і ви не слухали, але робили лихе в очах Моїх і обирали те, що було неугодно Мені.","Тому так говорить Господь Бог: ось, раби Мої будуть їсти, а ви будете голодувати; раби Мої будуть пити, а ви будете знемагати від спраги;","раби Мої будуть веселитися, а ви будете у соромі; раби Мої будуть співати від сердечної радости, а ви будете кричати від сердечної скорботи і ридати від скрушення духу.","І залишите ім’я ваше обраним Моїм для прокляття; і вб’є тебе Господь Бог, а рабів Своїх назве іншим ім’ям,","яким хто буде благословляти себе на землі, буде благословлятися Богом істини; і хто буде клястися на землі, буде клястися Богом істини, — тому що колишні скорботи будуть забуті і приховані від очей Моїх.","Бо ось, Я творю нове небо і нову землю, і попередні уже не будуть згадувані і не прийдуть на серце.","А ви будете веселитися і радіти повіки за те, що Я творю: бо ось, Я творю Єрусалим веселістю і народ його радістю.","І буду радуватися за Єрусалим і веселитися за народ Мій; і не почуєте у ньому більше голосу плачу і голосу волання.","Там не буде більше малолітнього і старця, який не досягнув би повноти днів своїх; бо столітній буде помирати юнаком, але столітній грішник буде проклятим.","І буду будувати доми і жити у них, і насаджувати виноградники і їсти плоди їх.","Не будуть будувати, щоб інший жив, не будуть насаджувати, щоб інший їв; бо дні народу Мого будуть, як дні дерева, й обрані Мої довго будуть користуватися плодами рук своїх.","Не будуть трудитися марно і народжувати дітей на горе; бо будуть сіменем, благословенним від Господа, і нащадки їх з ними.","І буде, перше ніж вони будуть взивати, Я відповім; вони ще будуть говорити, і Я уже почую.","Вовк і ягня будуть пастися разом, і лев, як віл, буде їсти солому, а для змія порох буде їжею: вони не будуть чинити зла і шкоди на усій святій горі Моїй, — говорить Господь."],"x":{"1":"31.66.19|62.9.24|62.10.20|66.2.12-13","2":"26.1.24|31.50.2","3":"4.32.5|31.1.29","4":"4.14.8","5":"31.66.5|62.14.3|32.4.4","6":"32.17.1","7":"36.18.6","8":"50.24.22","10":"31.35.2|5.7.26","11":"32.7.18","12":"26.1.24|32.7.13|32.35.14|31.66.4","13":"52.6.25","15":"3.5.21|54.11.26|65.3.14","16":"4.6.13","17":"57.3.13|76.21.1|31.43.18|31.66.22","18":"32.31.13","19":"31.61.3|31.62.5|76.21.4","20":"48.8.4","21":"31.62.8","22":"25.1.3|25.91.13","23":"31.61.9|75.6.10","24":"25.33.16|31.58.9","25":"31.11.6"},"n":{"11":["Гад (або Ваал-Гад) і Мени (Мануфи) — імена божеств сонця і місяця."]}},{"v":["Так говорить Господь: небо — престіл Мій, а земля — підніжжя ніг Моїх; де ж побудуєте ви дім для Мене, і де місце спокою Мого?","Бо усе це створила рука Моя, і усе це було, — говорить Господь. А ось на кого Я спогляну: на смиренного і скрушеного духом і на того, хто тріпоче перед словом Моїм.","[Беззаконник же,] який заколює вола — те саме, що той, хто вбиває людину; хто приносить агнця у жертву — те саме, що хто задушив пса; хто приносить семидал — те саме, що той, хто приносить свинячу кров; хто курить фіміам [у пам’ять] — те саме, що той, хто молиться ідолу; і як вони обрали власні свої шляхи, і душа їх знаходить задоволення у мерзотах їхніх, —","так і Я вживу їх спокусу і наведу на них жахливе для них: тому що Я кликав, і ніхто не відповідав, говорив, і вони не слухали, а робили лихе в очах Моїх і обирали те, що неугодно Мені.","Вислухайте слово Господа ви, що тремтите перед словом Його: ваші брати, які ненавидять вас і виганяють вас за ім’я Моє, говорять: «нехай явить Себе у славі Господь, і ми подивимося на радість вашу». Але вони будуть посоромлені.","Ось, шум з міста, голос із храму, голос Господа, Який відомщає ворогам Своїм.","Ще не мучилася пологами, а народила; раніше ніж настали болі її, розрішилася сином.","Хто чув таке? хто бачив подібне до цього? чи виникала країна в один день? чи народжувався народ в один раз, як Сион, ледь почав пологами мучитися, породив синів своїх?","Чи доведу Я до пологів, і не дам народити? — говорить Господь. Або, даючи силу народити, чи закрию утробу? — говорить Бог твій.","Звеселіться з Єрусалимом і радійте за нього усі, хто любить його! радійте з ним радістю усі, хто сумував за нього,","щоб вам годуватися і насичуватися від сосків утішення його, упиватися і насолоджуватися перенасиченням слави його.","Бо так говорить Господь: ось, Я направляю до нього мир як ріку, і багатство народів — як потік, що розливається для насолоди вашої; на руках будуть носити вас і на колінах пестити.","Як утішає когось мати його, так утішу Я вас, і ви будете втішені в Єрусалимі.","І побачите це, і зрадіє серце ваше, і кістки ваші розцвітуть, як молода зелень, і відкриється рука Господа рабам Його, а на ворогів Своїх Він розгнівається.","Бо ось, прийде Господь у вогні, і колісниці Його — як вихор, щоб вилити гнів Свій з люттю і покарання Своє з палаючим вогнем.","Бо Господь з вогнем і мечем Своїм зробить суд над усякою плоттю, і багато буде вражених Господом.","Ті, які освячують і очищають себе у дібровах, один за одним, їдять свиняче м’ясо і мерзоти і мишей, — усі загинуть, — говорить Господь.","Бо Я знаю діяння їх і думки їх; і ось, прийду зібрати всі народи і язики, і вони прийдуть і побачать славу Мою.","І покладу на них знамення, і пошлю зі спасенних від них до народів: у Фарсис, до Пула і Луда, до тих, що натягують лук, до Тубала і Явана, на далекі острови, які не чули про Мене і не бачили слави Моєї: і вони сповістять народам славу Мою","і представлять усіх братів ваших від усіх народів у дар Господу на конях і колісницях, і на ношах, і на мулах, і на швидких верблюдах, на святу гору Мою, в Єрусалим, — говорить Господь, — подібно до того, як сини Ізраїлеві приносять дар у дім Господа у чистому сосуді.","З них буду брати також у священики і левити, — говорить Господь.","Бо, як нове небо і нова земля, які Я створю, завжди будуть перед лицем Моїм, — говорить Господь, — так буде і сíм’я ваше й ім’я ваше.","Тоді з місяця у місяць і з суботи у суботу буде приходити усяка плоть перед лице Моє на поклоніння, говорить Господь.","І будуть виходити і побачать трупи людей, які відступили від Мене: бо черва їх не помре, і вогонь їх не згасне; і будуть вони мерзотою для усякої плоті."],"x":{"1":"54.7.49","2":"31.57.15","3":"31.1.11|50.5.24|4.14.8","4":"26.1.24|31.65.12|32.7.13","6":"76.18.6","8":"31.54.1|31.60.4","9":"32.3.19","10":"31.61.2-3|52.6.21","11":"31.60.16","12":"31.60.4","14":"31.35.10|31.51.11|53.16.22","15":"25.49.3|70.1.8","16":"32.25.33|76.19.21","17":"31.65.4","18":"76.7.9","19":"1.19.5|31.65.1","20":"31.49.22|31.60.7|62.15.16","21":"56.2.9|76.1.6","22":"31.65.17","23":"3.28.10|76.15.4","24":"51.9.44"}}];
